import sys

def solve():
    it = iter(sys.stdin.buffer.readline, b"")
    out_lines = []

    for line in it:
        if not line:
            break
        line = line.strip()
        if not line:
            continue
        n = int(line)
        if n == 0:
            break

        # DP for largest all-unmarked square:
        # dp[j] = size of largest square ending at current row, column j (1-based)
        # Transition for cell (i,j):
        # if unmarked: dp[j] = min(dp[j] (up), dp[j-1] (left), prev_diag) + 1
        # else: dp[j] = 0
        dp = [0] * (n + 1)
        best = 0

        for _ in range(n):
            row = next(it).strip().decode()
            prev_diag = 0
            for j, ch in enumerate(row, start=1):
                up = dp[j]
                if ch == '.':
                    val = dp[j - 1]
                    if up < val:
                        val = up
                    if prev_diag < val:
                        val = prev_diag
                    dp[j] = val + 1
                    if dp[j] > best:
                        best = dp[j]
                else:
                    dp[j] = 0
                prev_diag = up

        out_lines.append(str(best))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

