def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for AOJ/Aizu p00447 Searching Constellation.

    Returns:
        (True, "OK") if valid
        (False, "FORMAT_INVALID: ...") for malformed input
        (False, "SPEC_INVALID: ...") for constraint/spec violations
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    # Allow trailing whitespace/newlines, but not an entirely empty input.
    text = inp.rstrip()
    if text == "":
        return False, "FORMAT_INVALID: empty input"

    lines = text.splitlines()
    idx = 0
    datasets = 0

    def parse_int_line(line_no: int, expected_count: int):
        if line_no >= len(lines):
            return None, f"FORMAT_INVALID: missing line {line_no + 1}"
        parts = lines[line_no].split()
        if len(parts) != expected_count:
            return None, (
                f"FORMAT_INVALID: line {line_no + 1} must contain "
                f"{expected_count} integer(s)"
            )
        vals = []
        for tok in parts:
            if not _INT_RE.match(tok):
                return None, f"FORMAT_INVALID: non-integer token on line {line_no + 1}"
            try:
                vals.append(int(tok))
            except Exception:
                return None, f"FORMAT_INVALID: invalid integer on line {line_no + 1}"
        return vals, None

    while True:
        vals, err = parse_int_line(idx, 1)
        if err:
            return False, err
        m = vals[0]
        idx += 1

        if m == 0:
            break

        datasets += 1
        if datasets > 5:
            return False, "SPEC_INVALID: number of datasets exceeds 5"

        if not (1 <= m <= 200):
            return False, "SPEC_INVALID: m out of range"

        constellation = []
        seen_constellation = set()

        for _ in range(m):
            vals, err = parse_int_line(idx, 2)
            if err:
                return False, err
            x, y = vals
            idx += 1

            if not (0 <= x <= 1_000_000 and 0 <= y <= 1_000_000):
                return False, "SPEC_INVALID: constellation coordinate out of range"

            p = (x, y)
            if p in seen_constellation:
                return False, "SPEC_INVALID: duplicate constellation star position"
            seen_constellation.add(p)
            constellation.append(p)

        vals, err = parse_int_line(idx, 1)
        if err:
            return False, err
        n = vals[0]
        idx += 1

        if not (1 <= n <= 1000):
            return False, "SPEC_INVALID: n out of range"

        photo = []
        seen_photo = set()

        for _ in range(n):
            vals, err = parse_int_line(idx, 2)
            if err:
                return False, err
            x, y = vals
            idx += 1

            if not (0 <= x <= 1_000_000 and 0 <= y <= 1_000_000):
                return False, "SPEC_INVALID: photo coordinate out of range"

            p = (x, y)
            if p in seen_photo:
                return False, "SPEC_INVALID: duplicate photo star position"
            seen_photo.add(p)
            photo.append(p)

        # The statement guarantees the photo contains exactly one translated copy.
        # Enforce that guarantee.
        p0x, p0y = constellation[0]
        valid_translations = 0

        for qx, qy in photo:
            dx, dy = qx - p0x, qy - p0y
            ok = True
            for px, py in constellation:
                if (px + dx, py + dy) not in seen_photo:
                    ok = False
                    break
            if ok:
                valid_translations += 1
                if valid_translations > 1:
                    return False, "SPEC_INVALID: more than one matching translation"

        if valid_translations != 1:
            return False, "SPEC_INVALID: no matching translation"

    if datasets == 0:
        # The formal format allows m=0 as termination. This is a valid empty set
        # of datasets unless a judge-specific policy forbids it.
        pass

    if idx != len(lines):
        return False, "FORMAT_INVALID: extra data after terminating 0"

    return True, "OK"

