    if len(first_tokens) != 2:
        return False, "FORMAT_INVALID: first line must contain exactly two integers"

    if not all(_INT_RE.fullmatch(tok) for tok in first_tokens):
        return False, "FORMAT_INVALID: N and M must be integers"

    N, M = map(int, first_tokens)

    if not (1 <= N <= M <= 1000):
        return False, "SPEC_INVALID: constraints require 1 <= N <= M <= 1000"

    expected_lines = 1 + N + M
    if len(lines) != expected_lines:
        return False, (
            f"FORMAT_INVALID: expected {expected_lines} lines, got {len(lines)}"
        )

    # Next N lines: D_i
    for i in range(N):
        line_no = 2 + i
        tokens = lines[1 + i].strip().split()
        if len(tokens) != 1:
            return False, f"FORMAT_INVALID: line {line_no} must contain exactly one integer"
        if not _INT_RE.fullmatch(tokens[0]):
            return False, f"FORMAT_INVALID: D_{i + 1} must be an integer"
        d = int(tokens[0])
        if not (1 <= d <= 1000):
            return False, f"SPEC_INVALID: D_{i + 1} must satisfy 1 <= D_i <= 1000"

    # Following M lines: C_j
    for j in range(M):
        line_no = 2 + N + j
        tokens = lines[1 + N + j].strip().split()
        if len(tokens) != 1:
            return False, f"FORMAT_INVALID: line {line_no} must contain exactly one integer"
        if not _INT_RE.fullmatch(tokens[0]):
            return False, f"FORMAT_INVALID: C_{j + 1} must be an integer"
        c = int(tokens[0])
        if not (1 <= c <= 1000):
            return False, f"SPEC_INVALID: C_{j + 1} must satisfy 1 <= C_j <= 1000"

    return True, "OK"

import re
from typing import Tuple

_INT_RE = re.compile(r"-?\d+\Z")


def _is_int_token(s: str) -> bool:
    return _INT_RE.fullmatch(s) is not None


def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for AOJ/Aizu p00953 style input.

    Expected format:
        N M
        a1 b1 c1
        ...
        aM bM cM

    where the graph has N vertices and M weighted edges.
    Vertices are numbered from 1 to N, and edge weights are positive.
    """
    if not isinstance(inp, str):
        return False, "FORMAT_INVALID: input is not a string"

    if inp.strip() == "":
        return False, "FORMAT_INVALID: empty input"

    # Preserve line structure, but allow trailing blank/whitespace-only lines.
    lines = inp.rstrip().splitlines()

    if len(lines) < 1:
        return False, "FORMAT_INVALID: missing first line"

    first = lines[0].strip().split()
    if len(first) != 2:
        return False, "FORMAT_INVALID: first line must contain exactly two integers"

    if not all(_is_int_token(x) for x in first):
        return False, "FORMAT_INVALID: first line contains a non-integer token"

    n, m = map(int, first)

    if n < 1:
        return False, "SPEC_INVALID: number of vertices must be positive"
    if m < 0:
        return False, "SPEC_INVALID: number of edges must be non-negative"

    expected_lines = 1 + m
    if len(lines) != expected_lines:
        return (
            False,
            f"FORMAT_INVALID: expected {m} edge lines, found {len(lines) - 1}",
        )

    for i in range(m):
        line_no = i + 2
        parts = lines[i + 1].strip().split()

        if len(parts) != 3:
            return (
                False,
                f"FORMAT_INVALID: edge line {line_no} must contain exactly three integers",
            )

        if not all(_is_int_token(x) for x in parts):
            return (
                False,
                f"FORMAT_INVALID: edge line {line_no} contains a non-integer token",
            )

        a, b, c = map(int, parts)

        if not (1 <= a <= n):
            return (
                False,
                f"SPEC_INVALID: edge line {line_no} has vertex {a} outside 1..{n}",
            )
        if not (1 <= b <= n):
            return (
                False,
                f"SPEC_INVALID: edge line {line_no} has vertex {b} outside 1..{n}",
            )
        if a == b:
            return (
                False,
                f"SPEC_INVALID: edge line {line_no} is a self-loop",
            )
        if c <= 0:
            return (
                False,
                f"SPEC_INVALID: edge line {line_no} has non-positive weight",
            )

    return True, "OK"

