import sys

def main():
    s = sys.stdin.readline().rstrip("\n")
    t = sys.stdin.readline().rstrip("\n")

    # Determine if s is a subsequence of t or t is a subsequence of s.
    def is_subseq(a: str, b: str) -> bool:
        i = 0
        for ch in b:
            if i < len(a) and a[i] == ch:
                i += 1
        return i == len(a)

    ans = "Yes" if (is_subseq(s, t) or is_subseq(t, s)) else "No"
    print(ans)

if __name__ == "__main__":
    main()

