import re
from typing import Tuple

_ALLOWED_RE = re.compile(r'^[A-Za-z0-9]+$')


def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validate input for AOJ p02250 Multiple String Matching.

    Returns:
        (ok, reason)
        ok=True  -> reason="OK"
        ok=False -> reason starts with "FORMAT_INVALID" or "SPEC_INVALID"
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    # Normalize newlines; keep possible trailing newline harmless
    s = inp.replace("\r\n", "\n").replace("\r", "\n")

    lines = s.split("\n")
    # Tolerate trailing empty lines (common when input ends with newline)
    while lines and lines[-1] == "":
        lines.pop()

    if len(lines) < 2:
        return False, "FORMAT_INVALID: expected at least 2 lines (T and Q)"

    T = lines[0]
    if T == "":
        return False, "SPEC_INVALID: T must have length >= 1"
    if not _ALLOWED_RE.fullmatch(T):
        return False, "FORMAT_INVALID: T contains non-alphanumeric characters"
    if len(T) > 1_000_000:
        return False, "SPEC_INVALID: length of T exceeds 1000000"

    q_line = lines[1].strip()
    if q_line == "":
        return False, "FORMAT_INVALID: missing Q"
    if not re.fullmatch(r"[0-9]+", q_line):
        return False, "FORMAT_INVALID: Q must be a non-negative integer"
    Q = int(q_line)

    if Q < 1 or Q > 10_000:
        return False, "SPEC_INVALID: Q out of range (1..10000)"

    expected_total = 2 + Q
    if len(lines) != expected_total:
        return False, (
            f"FORMAT_INVALID: expected exactly {expected_total} non-empty-trimmed lines "
            f"(2 + Q), got {len(lines)}"
        )

    # Validate patterns
    for i in range(Q):
        P = lines[2 + i]
        if P == "":
            return False, f"SPEC_INVALID: P_{i+1} must have length >= 1"
        if not _ALLOWED_RE.fullmatch(P):
            return False, f"FORMAT_INVALID: P_{i+1} contains non-alphanumeric characters"
        if len(P) > 1000:
            return False, f"SPEC_INVALID: length of P_{i+1} exceeds 1000"

    return True, "OK"

