import sys

def selection_sort(a):
    n = len(a)
    swaps = 0
    for i in range(n):
        mini = i
        for j in range(i, n):
            if a[j] < a[mini]:
                mini = j
        if mini != i:
            a[i], a[mini] = a[mini], a[i]
            swaps += 1
    return swaps

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    swaps = selection_sort(a)

    print(" ".join(map(str, a)))
    print(swaps)

if __name__ == "__main__":
    main()

