import sys

def main() -> None:
    it = iter(sys.stdin.buffer.read().split())
    try:
        N = int(next(it))
    except StopIteration:
        return
    W = int(next(it))

    items = []
    total_value = 0
    for _ in range(N):
        v = int(next(it))
        w = int(next(it))
        items.append((v, w))
        total_value += v

    INF = 10**30
    # dp[val] = minimum total weight to achieve total value 'val'
    dp = [INF] * (total_value + 1)
    dp[0] = 0

    for v, w in items:
        for val in range(total_value - v, -1, -1):
            if dp[val] != INF:
                nw = dp[val] + w
                if nw < dp[val + v]:
                    dp[val + v] = nw

    ans = 0
    for val in range(total_value, -1, -1):
        if dp[val] <= W:
            ans = val
            break

    sys.stdout.write(str(ans) + "\n")

if __name__ == "__main__":
    main()

