        return False, "SPEC_INVALID: H and W must be >= 1"
    if H > 1400 or W > 1400:
        return False, "SPEC_INVALID: H and W must be <= 1400"

    expected_cells = H * W
    remaining = tokens[2:]
    if len(remaining) != expected_cells:
        return False, (
            "FORMAT_INVALID: expected exactly "
            f"{expected_cells} matrix entries, got {len(remaining)}"
        )

    # Validate matrix entries are 0/1 integers
    for i, t in enumerate(remaining):
        try:
            v = int(t)
        except Exception:
            r = i // W + 1
            c = i % W + 1
            return False, f"FORMAT_INVALID: non-integer at row {r}, col {c}"
        if v not in (0, 1):
            r = i // W + 1
            c = i % W + 1
            return False, f"SPEC_INVALID: value must be 0 or 1 at row {r}, col {c}"

    return True, "OK"

