                        None,
                    )
                vals.append(int(tok))
                idx += 1
            triples.append((vals[0], vals[1], vals[2]))

        cases.append(Case(n=n, triples=triples))

    if idx != len(toks):
        return False, "FORMAT_INVALID: extra tokens after reading all test cases", None

    return True, "ok", ParsedInput(t=t, cases=cases)


