def parse_format(input_str: str) -> Tuple[bool, Any]:
    if input_str is None:
        return False, "FORMAT_INVALID: input is None"
    if input_str.strip() == "":
        return False, "FORMAT_INVALID: empty input"

    tokens = input_str.split()
    if len(tokens) == 0:
        return False, "FORMAT_INVALID: empty input"

    # Parse N
    try:
        n = int(tokens[0])
    except ValueError:
        return False, "FORMAT_INVALID: N is not an integer"

    if n < 0:
        return False, f"FORMAT_INVALID: N must be non-negative integer, got {n}"

    expected_total = 1 + n
    if len(tokens) != expected_total:
        if len(tokens) < expected_total:
            return False, f"FORMAT_INVALID: expected {n} integers for p, got {len(tokens) - 1}"
        else:
            return False, f"FORMAT_INVALID: expected exactly {expected_total} tokens total, got {len(tokens)}"

    p: List[int] = []
    for i in range(n):
        t = tokens[1 + i]
        try:
            val = int(t)
        except ValueError:
            return False, f"FORMAT_INVALID: p[{i+1}] is not an integer"
        p.append(val)

    return True, {"N": n, "p": p}


def check_constraints(parsed: Dict[str, Any]) -> Tuple[bool, str]:
    n = parsed.get("N")
    p = parsed.get("p")

    if not isinstance(n, int):
        return False, "FORMAT_INVALID: N missing or not an integer"
    if not isinstance(p, list):
        return False, "FORMAT_INVALID: p missing"

    if not (2 <= n <= 100000):
        return False, f"SPEC_INVALID: N out of bounds (2..100000), got {n}"

    if len(p) != n:
        return False, f"SPEC_INVALID: p length must be N={n}, got {len(p)}"

    # Validate permutation: all integers in [1..n] and all distinct.
    # Use a set to avoid any potential indexing/aliasing issues.
    seen = set()
    for i, x in enumerate(p, start=1):
        if not isinstance(x, int):
            return False, f"FORMAT_INVALID: p[{i}] is not an integer"
        if x < 1 or x > n:
            return False, f"SPEC_INVALID: p[{i}] out of range 1..N, got {x}"
        if x in seen:
            return False, f"SPEC_INVALID: p is not a permutation (duplicate value {x})"
        seen.add(x)

    # Since len(p)=n and all values are distinct within 1..n, it's a permutation.
    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, res = parse_format(input_str)
    if not ok:
        return False, res
    ok2, msg = check_constraints(res)
    if not ok2:
        return False, msg
    return True, "ok"

