import sys
from collections import deque

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    header_idx = 0
    while header_idx < len(lines) and not lines[header_idx].strip():
        header_idx += 1

    H, W, K = map(int, lines[header_idx].split())
    raw = lines[header_idx + 1:]

    A = []
    for line in raw:
        if len(A) >= H:
            break
        s = line.strip()
        if len(s) < W:
            s = "#" * (W - len(s)) + s
        elif len(s) > W:
            s = s[:W]
        A.append(s)

    while len(A) < H:
        A.append("#" * W)

    sr = sc = -1
    for i in range(H):
        for j in range(W):
            if A[i][j] == "S":
                sr, sc = i, j
                break
        if sr != -1:
            break

    start = sr * W + sc
    dist = [-1] * (H * W)
    dist[start] = 0
    q = deque([start])

    ans = 10 ** 18

    while q:
        v = q.popleft()
        r, c = divmod(v, W)
        d = dist[v]

        to_exit = min(r, c, H - 1 - r, W - 1 - c)
        ans = min(ans, 1 + (to_exit + K - 1) // K)

        if d == K:
            continue

        nd = d + 1

        if r > 0:
            nv = v - W
            if dist[nv] == -1 and A[r - 1][c] != "#":
                dist[nv] = nd
                q.append(nv)

        if r + 1 < H:
            nv = v + W
            if dist[nv] == -1 and A[r + 1][c] != "#":
                dist[nv] = nd
                q.append(nv)

        if c > 0:
            nv = v - 1
            if dist[nv] == -1 and A[r][c - 1] != "#":
                dist[nv] = nd
                q.append(nv)

        if c + 1 < W:
            nv = v + 1
            if dist[nv] == -1 and A[r][c + 1] != "#":
                dist[nv] = nd
                q.append(nv)

    print(ans)

if __name__ == "__main__":
    solve()

