    try:
        n = int(tokens[0])
    except Exception:
        return False, "FORMAT_INVALID: first token is not an integer (n)"

    if not (1 <= n <= 2000):
        return False, f"SPEC_INVALID: n out of range [1, 2000], got {n}"

    # Need exactly n integers after n
    if len(tokens) != 1 + n:
        return (
            False,
            f"FORMAT_INVALID: expected {1+n} tokens total (n + n numbers), got {len(tokens)}"
        )

    # Parse array values and check bounds
    for i in range(n):
        t = tokens[1 + i]
        try:
