import re
from typing import Tuple

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validates input for Codeforces 114B - PFAST Inc.

    Expected format (from original CF problem):
      n m
      name1
      name2
      ...
      namen
      a1 b1
      ...
      am bm

    Constraints (typical for this problem):
      1 <= n <= 16
      0 <= m <= n*(n-1)/2
      names are strings (usually lowercase latin letters) and unique
      each pair ai bi are names among the n volunteers, ai != bi
    (If the official statement you use differs in allowed name charset,
     this validator accepts [A-Za-z0-9_]+ to be tolerant.)
    """
    # Normalize newlines, keep all lines
    s = inp.replace("\r\n", "\n").replace("\r", "\n")

    # Split into lines; allow trailing whitespace/newline
    lines = s.split("\n")
    # Drop trailing completely empty lines
    while lines and lines[-1].strip() == "":
        lines.pop()

    if not lines:
        return (False, "FORMAT_INVALID: empty input")

    # Parse first line: n m
    first = lines[0].strip()
    parts = first.split()
    if len(parts) != 2:
        return (False, "FORMAT_INVALID: first line must contain exactly two integers n m")
    try:
        n = int(parts[0])
        m = int(parts[1])
    except ValueError:
        return (False, "FORMAT_INVALID: n and m must be integers")

    if n < 1:
        return (False, "SPEC_INVALID: n must be >= 1")
    if n > 16:
        return (False, "SPEC_INVALID: n must be <= 16")
    if m < 0:
        return (False, "SPEC_INVALID: m must be >= 0")
    max_m = n * (n - 1) // 2
    if m > max_m:
        return (False, "SPEC_INVALID: m exceeds n*(n-1)/2")

    expected_lines = 1 + n + m
    if len(lines) != expected_lines:
        return (False, f"FORMAT_INVALID: expected {expected_lines} non-empty lines, got {len(lines)}")

    name_re = re.compile(r"^[A-Za-z0-9_]+$")

    names = []
    name_set = set()
    # Read n names
    for i in range(n):
        line = lines[1 + i].strip()
        if line == "":
            return (False, f"FORMAT_INVALID: empty name at line {2+i}")
        if not name_re.fullmatch(line):
            return (False, f"FORMAT_INVALID: invalid name token '{line}' at line {2+i}")
        if line in name_set:
            return (False, f"SPEC_INVALID: duplicate name '{line}'")
        name_set.add(line)
        names.append(line)

    # Read m pairs
    seen_pairs = set()
    for j in range(m):
        idx = 1 + n + j
        pair_line = lines[idx].strip()
        tokens = pair_line.split()
        if len(tokens) != 2:
            return (False, f"FORMAT_INVALID: pair line {idx+1} must contain exactly two names")
        a, b = tokens
        if not name_re.fullmatch(a) or not name_re.fullmatch(b):
            return (False, f"FORMAT_INVALID: invalid name token(s) in pair at line {idx+1}")
        if a not in name_set or b not in name_set:
            return (False, f"SPEC_INVALID: pair references unknown name(s) at line {idx+1}")
        if a == b:
            return (False, f"SPEC_INVALID: self-pair '{a} {b}' at line {idx+1}")
        # Undirected edge; disallow duplicates
        u, v = (a, b) if a < b else (b, a)
        if (u, v) in seen_pairs:
            return (False, f"SPEC_INVALID: duplicate pair '{a} {b}' (or reversed) at line {idx+1}")
        seen_pairs.add((u, v))

    return (True, "OK")

from __future__ import annotations

def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validates input for CF 1152A - Neko Finds Grapes.

    Returns:
      (True, "OK") on acceptance
      (False, "<PREFIX>: ...") on rejection, where PREFIX is FORMAT_INVALID or SPEC_INVALID
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    toks = s.split()
    # Need at minimum: n m + n a_i + m b_j
    if len(toks) < 2:
        return False, "FORMAT_INVALID: missing n and m"

    def parse_int(tok: str) -> int | None:
        # Strict int parsing: allow leading '+' or '-' (though spec uses positive),
        # reject non-integers.
        try:
            # Prevent floats like "1.0"
            if any(c in tok for c in ".eE"):
                return None
            return int(tok)
        except Exception:
            return None

    n = parse_int(toks[0])
    m = parse_int(toks[1])
    if n is None or m is None:
        return False, "FORMAT_INVALID: n or m is not an integer"

    if n < 1 or m < 1 or n > 10**5 or m > 10**5:
        return False, "SPEC_INVALID: n and m must satisfy 1 <= n,m <= 1e5"

    expected = 2 + n + m
    if len(toks) != expected:
        if len(toks) < expected:
            return False, f"FORMAT_INVALID: expected {expected} integers total, got {len(toks)}"
        else:
            return False, f"FORMAT_INVALID: extra tokens (expected {expected} integers total, got {len(toks)})"

    a = []
    for i in range(n):
        v = parse_int(toks[2 + i])
        if v is None:
            return False, f"FORMAT_INVALID: a_{i+1} is not an integer"
        if v < 1 or v > 10**9:
            return False, f"SPEC_INVALID: a_{i+1} must satisfy 1 <= a_i <= 1e9"
        a.append(v)

    b = []
    base = 2 + n
    for j in range(m):
        v = parse_int(toks[base + j])
        if v is None:
            return False, f"FORMAT_INVALID: b_{j+1} is not an integer"
        if v < 1 or v > 10**9:
            return False, f"SPEC_INVALID: b_{j+1} must satisfy 1 <= b_j <= 1e9"
        b.append(v)

    return True, "OK"

