import sys

def solve():
    it = iter(sys.stdin.read().strip().split())
    try:
        n = int(next(it))
    except StopIteration:
        return
    m = int(next(it))

    if m == 1:
        # Elevator always on floor 1
        out = []
        for _ in range(n):
            s = int(next(it)); f = int(next(it)); t = int(next(it))
            out.append(str(t))  # s==f==1
        sys.stdout.write("\n".join(out))
        return

    period = 2 * (m - 1)

    def floor_at(time):
        """Elevator floor at integer time 'time' (at that moment)."""
        x = time % period
        if x <= m - 1:
            return 1 + x
        else:
            return m - (x - (m - 1))

    def next_stop_time_at_or_after(t, s):
        """Smallest time >= t when elevator is on floor s."""
        x = t % period
        f = floor_at(t)
        if f == s:
            return t

        if x <= m - 1:
            # Going up: floor = 1 + x, x in [0..m-1]
            if s > f:
                dt = s - f
            else:
                # Finish up to m, then go down to s
                dt = (m - f) + (m - s)
        else:
            # Going down: floor = m - (x-(m-1))
            if s < f:
                dt = f - s
            else:
                # Finish down to 1, then go up to s
                dt = (f - 1) + (s - 1)
        return t + dt

    def travel_time_from_s_to_f_when_boarding(x, s, f):
        """
        Minimal time needed to go from s to f when elevator is at floor s at time x.
        Determined by the elevator direction at that time.
        """
        if s == f:
            return 0
        r = x % period
        if r <= m - 1:
            # direction up, except at top turnaround moment r==m-1 where it is at m
            dir_up = True
        else:
            dir_up = False

        if dir_up:
            if f >= s:
                return f - s
            else:
                # go to top then down
                return (m - s) + (m - f)
        else:
            if f <= s:
                return s - f
            else:
                # go to bottom then up
                return (s - 1) + (f - 1)

    out_lines = []
    for _ in range(n):
        s = int(next(it))
        f = int(next(it))
        t = int(next(it))
        if s == f:
            out_lines.append(str(t))
            continue

        board_time = next_stop_time_at_or_after(t, s)
        ride = travel_time_from_s_to_f_when_boarding(board_time, s, f)
        out_lines.append(str(board_time + ride))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

