        return False, "SPEC_INVALID: must satisfy 2 <= k <= n <= m <= 250"
    if not (1 <= t <= 1000):
        return False, "SPEC_INVALID: must satisfy 1 <= t <= 1000"

    # Must have exactly t operation lines
    if len(lines) != 1 + t:
        return False, f"FORMAT_INVALID: expected {t} operation lines, got {len(lines) - 1}"

    l = n
    cur_k = k

    for idx in range(t):
        raw = lines[1 + idx].strip()
        parts = raw.split()
        if len(parts) != 2:
            return False, f"FORMAT_INVALID: operation line {idx+1} must have exactly 2 tokens"

