            if i <= cur_k:
                cur_k += 1
            l += 1

        else:
            # break link i in [1, l-1]; l>=2 guaranteed by range
            if not (1 <= i <= l - 1):
                return False, f"SPEC_INVALID: break index out of range on line {idx+1}"

            # After breaking between i and i+1:
            # left segment size = i, right segment size = l - i.
            # Keep segment containing doctor (position cur_k).
            if cur_k <= i:
                # keep left
                l = i
                # cur_k unchanged
            else:
