def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validates input for CF 1189_D1 (Add on a Tree).

    Returns:
        (True, "OK") if input is valid
        (False, "<PREFIX>: <reason>") otherwise, where PREFIX is FORMAT_INVALID or SPEC_INVALID
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    toks = s.split()
    if not toks:
        return False, "FORMAT_INVALID: no tokens"

    # Parse n
    try:
        n = int(toks[0])
    except Exception:
        return False, "FORMAT_INVALID: first token is not an integer (n)"

    if n < 2 or n > 10**5:
        return False, f"SPEC_INVALID: n out of range [2, 1e5], got {n}"

    m = n - 1
    expected = 1 + 2 * m
    if len(toks) != expected:
        return False, f"FORMAT_INVALID: expected {expected} tokens total, got {len(toks)}"

    edges = []
    idx = 1
    for i in range(m):
        try:
            u = int(toks[idx]); v = int(toks[idx + 1])
        except Exception:
            return False, f"FORMAT_INVALID: edge {i+1} endpoints are not integers"
        idx += 2

        if not (1 <= u <= n) or not (1 <= v <= n):
            return False, f"SPEC_INVALID: edge {i+1} endpoint out of range 1..n (u={u}, v={v})"
        if u == v:
            return False, f"SPEC_INVALID: self-loop at node {u} on edge {i+1}"

        edges.append((u, v))

    # Check that edges form a tree: connected and acyclic.
    # Since m = n-1, it suffices to check connectedness with DSU; also detect cycles.
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(a: int) -> int:
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a: int, b: int) -> bool:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False  # cycle (or duplicate edge creating cycle in simple graph sense)
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    for i, (u, v) in enumerate(edges, 1):
        if not union(u, v):
            return False, f"SPEC_INVALID: edges do not form a tree (cycle detected at edge {i}: {u} {v})"

    root = find(1)
    for node in range(2, n + 1):
        if find(node) != root:
            return False, "SPEC_INVALID: edges do not form a tree (graph is disconnected)"

    return True, "OK"

