        n = vals[idx]
        idx += 1

        if not (1 <= n <= 200):
            return False, f"SPEC_INVALID: n out of range (1..200) in query {qi}, got {n}"

        ok, msg = need(n, f"permutation p of length {n} for query {qi}")
        if not ok:
            return False, msg
        p = vals[idx:idx + n]
        idx += n

        # Spec: permutation of 1..n
        # Range check
        for x in p:
            if not (1 <= x <= n):
                return False, (
                    f"SPEC_INVALID: permutation value out of range (1..{n}) "
                    f"in query {qi}, got {x}"
                )
        # Distinctness / permutation check
        if len(set(p)) != n:
            return False, f"SPEC_INVALID: p is not a permutation (duplicates) in query {qi}"

    # No extra tokens beyond the q queries
    if idx != len(vals):
        return False, f"FORMAT_INVALID: extra trailing tokens starting at position {idx+1}"

