            return False, f"FORMAT_INVALID: query {qi+1} missing n and r"
        n = vals[idx]
        r = vals[idx + 1]
        idx += 2

        if not (1 <= n <= 10**5):
            return False, f"SPEC_INVALID: query {qi+1} has n out of range [1, 1e5]"
        if not (1 <= r <= 10**5):
            return False, f"SPEC_INVALID: query {qi+1} has r out of range [1, 1e5]"

        total_n += n
        if total_n > 10**5:
            return False, "SPEC_INVALID: sum of n over all queries exceeds 1e5"

        if idx + n > len(vals):
            return False, f"FORMAT_INVALID: query {qi+1} missing x_i values (need {n})"

        xs = vals[idx:idx + n]
        idx += n

        for j, x in enumerate(xs, start=1):
            if not (1 <= x <= 10**5):
