_TAG_RE = re.compile(r"<(/?)([a-z])>")

MAX_LEN = 1000


def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 125B - Simple XML.

    Expected input:
      - exactly one non-empty line containing a valid XML-text
      - the line may optionally end with a single '\\n' or '\\r\\n'
      - payload consists only of tags of the form <x> and </x>, where x is [a-z]
      - tags must be properly nested
      - payload length must not exceed 1000 characters

    Returns:
      (True, "OK") on success
      (False, "...") with prefix FORMAT_INVALID or SPEC_INVALID on failure
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"
    if not isinstance(inp, str):
        return False, "FORMAT_INVALID: input is not a string"

    # Strip at most one conventional trailing line ending.
    if inp.endswith("\r\n"):
        payload = inp[:-2]
    elif inp.endswith("\n"):
        payload = inp[:-1]
    else:
        payload = inp

    # No other newline/carriage-return characters are allowed.
    if "\n" in payload or "\r" in payload:
        return False, "FORMAT_INVALID: input must contain exactly one line"

    # Although the formal XML grammar defines an empty XML-text, the actual
    # problem input is read as a single string and must be present/non-empty.
    if payload == "":
        return False, "FORMAT_INVALID: missing XML string"

    if len(payload) > MAX_LEN:
        return False, f"SPEC_INVALID: XML string length exceeds {MAX_LEN}"

    s = payload

    # Whitespace and arbitrary text are not part of this simplified XML format.
    for i, ch in enumerate(s):
        if ch.isspace():
            return False, f"FORMAT_INVALID: whitespace in XML string at index {i}"

    stack = []
    pos = 0
    token_index = 0
    n = len(s)

    while pos < n:
        m = _TAG_RE.match(s, pos)
        if not m:
            ctx = s[pos:pos + 32]
            return False, f"FORMAT_INVALID: invalid tag at index {pos}, context={ctx!r}"

        slash, letter = m.group(1), m.group(2)

        if slash == "":
            stack.append(letter)
        else:
            if not stack:
                return False, (
                    f"FORMAT_INVALID: closing tag </{letter}> at token "
                    f"{token_index} without matching opener"
                )
            expected = stack.pop()
            if expected != letter:
                return False, (
                    f"FORMAT_INVALID: mismatched closing tag </{letter}> at token "
                    f"{token_index}, expected </{expected}>"
                )

        pos = m.end()
        token_index += 1

    if stack:
        return False, f"FORMAT_INVALID: unclosed tag(s) remain: {''.join(stack)!r}"

    return True, "OK"

