def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validate input for Codeforces 1269E (K Integers).

    Returns:
      (True, "OK") if accepted
      (False, "<PREFIX>: <reason>") otherwise, where PREFIX is FORMAT_INVALID or SPEC_INVALID.
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    parts = s.split()
    # Need at least n and then n integers.
    if len(parts) < 2:
        return False, "FORMAT_INVALID: expected n and permutation line"

    # Parse n
    try:
        n = int(parts[0])
    except Exception:
        return False, "FORMAT_INVALID: n is not an integer"

    if n < 1 or n > 200000:
        return False, "SPEC_INVALID: n out of range [1, 200000]"

    # Must have exactly n permutation values after n (no less, no more).
    if len(parts) != 1 + n:
        if len(parts) < 1 + n:
            return False, f"FORMAT_INVALID: expected {n} permutation integers, got {len(parts)-1}"
        else:
            return False, f"FORMAT_INVALID: expected exactly {n} permutation integers, got {len(parts)-1}"

    # Parse permutation
    p = []
    for i in range(n):
        tok = parts[1 + i]
        try:
            val = int(tok)
        except Exception:
            return False, f"FORMAT_INVALID: p[{i+1}] is not an integer"
        p.append(val)

    # Spec checks: range and permutation property
    seen = [False] * (n + 1)
    for i, val in enumerate(p, start=1):
        if val < 1 or val > n:
            return False, f"SPEC_INVALID: p[{i}]={val} out of range [1, {n}]"
        if seen[val]:
            return False, f"SPEC_INVALID: duplicate value {val} in permutation"
        seen[val] = True

    # Ensure all values 1..n are present (redundant if no duplicates and all in range, but explicit)
    # If some number missing, then necessarily some duplicate existed; still, keep for clarity.
    for v in range(1, n + 1):
        if not seen[v]:
            return False, f"SPEC_INVALID: missing value {v} in permutation"

    return True, "OK"

