import sys

def count_fib_decompositions(n: int) -> int:
    # Generate Fibonacci numbers up to n (including 1,2,3,5,... as in examples)
    fib = [1, 2]
    while fib[-1] + fib[-2] <= n:
        fib.append(fib[-1] + fib[-2])

    # dp[s] = number of subsets of fib summing to s (each fib can be used at most once)
    dp = [0] * (n + 1)
    dp[0] = 1
    for f in fib:
        for s in range(n, f - 1, -1):
            dp[s] += dp[s - f]
    return dp[n]

