def solve() -> None:
    input = sys.stdin.readline
    n = int(input().strip())
    p = list(map(int, input().split()))

    total_odd = (n + 1) // 2
    total_even = n // 2

    used_odd = sum(1 for x in p if x != 0 and (x % 2 == 1))
    used_even = sum(1 for x in p if x != 0 and (x % 2 == 0))

    rem_odd = total_odd - used_odd
    rem_even = total_even - used_even

    INF = 10**9
    # dp[i][o][e][last] = min complexity for first i positions,
    # using o odds and e evens among the filled zeros so far,
    # where last is parity of position i (0 even, 1 odd), only defined for i>=1.
    dp = [[[[INF] * 2 for _ in range(rem_even + 1)]
           for __ in range(rem_odd + 1)]
          for ___ in range(n + 1)]

    # Initialize for position 1
    if n >= 1:
        if p[0] != 0:
            par = p[0] & 1
            dp[1][0][0][par] = 0
        else:
            if rem_odd > 0:
                dp[1][1][0][1] = 0
            if rem_even > 0:
                dp[1][0][1][0] = 0

    for i in range(1, n):
        val = p[i]
        for o in range(rem_odd + 1):
            for e in range(rem_even + 1):
                for last in (0, 1):
                    cur = dp[i][o][e][last]
                    if cur >= INF:
                        continue

                    if val != 0:
                        par = val & 1
                        add = 1 if par != last else 0
                        if cur + add < dp[i + 1][o][e][par]:
                            dp[i + 1][o][e][par] = cur + add
                    else:
                        # place odd
                        if o < rem_odd:
                            par = 1
                            add = 1 if par != last else 0
