import sys

def format_integer_with_commas(s: str) -> str:
    # s contains only digits (possibly empty -> treat as "0")
    if not s:
        s = "0"
    groups = []
    i = len(s)
    while i > 0:
        j = max(0, i - 3)
        groups.append(s[j:i])
        i = j
    return ",".join(reversed(groups))

def solve():
    s = sys.stdin.readline().strip()
    if not s:
        return

    neg = s[0] == '-'
    if neg:
        s = s[1:]

    if '.' in s:
        int_part, frac_part = s.split('.', 1)
    else:
        int_part, frac_part = s, ""

    # integer part
    int_part = int_part if int_part != "" else "0"
    int_part_formatted = format_integer_with_commas(int_part)

    # fractional part: exactly two digits, truncate without rounding
    frac_part = (frac_part + "00")[:2]

    out = f"${int_part_formatted}.{frac_part}"
    if neg:
        out = f"({out})"

    sys.stdout.write(out)

if __name__ == "__main__":
    solve()

