def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validates input for Codeforces 1450B - Balls of Steel.

    Returns (ok, reason). reason starts with:
      - "OK" if valid
      - "FORMAT_INVALID: ..." for parse/structure issues
      - "SPEC_INVALID: ..." for spec constraint violations
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    # Only allow whitespace and (optionally signed) integers.
    # (We still enforce non-negativity where required by spec.)
    tokens = re.findall(r"-?\d+", s)
    # Check for any non-whitespace junk by removing all integers and whitespace.
    junk = re.sub(r"-?\d+", " ", s)
    if re.sub(r"\s+", "", junk) != "":
        return False, "FORMAT_INVALID: contains non-integer tokens"

    if not tokens:
        return False, "FORMAT_INVALID: no integers found"

    idx = 0
    def need_int(name: str):
        nonlocal idx
        if idx >= len(tokens):
            return None, f"FORMAT_INVALID: missing integer for {name}"
        try:
            v = int(tokens[idx])
        except Exception:
            return None, f"FORMAT_INVALID: cannot parse integer for {name}"
        idx += 1
        return v, None

    t, err = need_int("t")
    if err:
        return False, err
    if t is None:
        return False, "FORMAT_INVALID: missing t"
    if not (1 <= t <= 100):
        return False, f"SPEC_INVALID: t out of range (1..100), got {t}"

    for case in range(1, t + 1):
        n, err = need_int(f"n (case {case})")
        if err:
            return False, err
        k, err = need_int(f"k (case {case})")
        if err:
            return False, err

        if not (2 <= n <= 100):
            return False, f"SPEC_INVALID: n out of range (2..100) in case {case}, got {n}"
        if not (0 <= k <= 10**6):
            return False, f"SPEC_INVALID: k out of range (0..1e6) in case {case}, got {k}"

        seen = set()
        for i in range(1, n + 1):
            x, err = need_int(f"x_{i} (case {case})")
            if err:
                return False, err
            y, err = need_int(f"y_{i} (case {case})")
            if err:
                return False, err

            if not (0 <= x <= 10**5):
                return False, f"SPEC_INVALID: x_{i} out of range (0..1e5) in case {case}, got {x}"
            if not (0 <= y <= 10**5):
                return False, f"SPEC_INVALID: y_{i} out of range (0..1e5) in case {case}, got {y}"

            if (x, y) in seen:
                return False, f"SPEC_INVALID: duplicate point ({x}, {y}) in case {case}"
            seen.add((x, y))

    # No extra integers allowed beyond the spec.
    if idx != len(tokens):
        return False, f"FORMAT_INVALID: extra trailing integers starting at token {idx+1}"

    return True, "OK"

