        total_n += n
        if total_n > 300_000:
            return False, f"SPEC_INVALID: sum of n exceeds 300000 (at test case {tc}, sum={total_n})"

        if idx + n > len(vals):
            return False, f"FORMAT_INVALID: not enough a_i values in test case {tc} (need {n})"

