import sys

MOD = 1000000007

def is_lucky(x: int) -> bool:
    if x <= 0:
        return False
    while x:
        d = x % 10
        if d != 4 and d != 7:
            return False
        x //= 10
    return True

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:2+n]

    # Count occurrences of each distinct lucky value, and count total non-lucky items.
    lucky_counts = {}
    non_lucky = 0
    for v in a:
        if is_lucky(v):
            lucky_counts[v] = lucky_counts.get(v, 0) + 1
        else:
            non_lucky += 1

    # Number of ways to pick any multiset of non-lucky elements is by indices,
    # hence: choose t indices among non_lucky => C(non_lucky, t)
    # We'll combine with lucky distinct picks via DP.
    m = len(lucky_counts)

    # Precompute factorials up to non_lucky for combinations.
    # If k can be large (up to n), we still only need combinations up to min(k, non_lucky).
    maxN = non_lucky
    fact = [1] * (maxN + 1)
    invfact = [1] * (maxN + 1)
    for i in range(1, maxN + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact[maxN] = pow(fact[maxN], MOD - 2, MOD)
    for i in range(maxN, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def nCk(N, R):
        if R < 0 or R > N:
            return 0
        return fact[N] * invfact[R] % MOD * invfact[N - R] % MOD

    # DP over distinct lucky values:
    # dp[j] = number of ways to pick j distinct lucky numbers,
    # where for each selected lucky value with count c, we choose exactly one occurrence (c ways).
    dp = [0] * (m + 1)
    dp[0] = 1
    for c in lucky_counts.values():
        # update backwards
        for j in range(m, 0, -1):
            dp[j] = (dp[j] + dp[j - 1] * c) % MOD

    # Combine: choose i lucky distinct, and k-i non-lucky indices
    ans = 0
    max_lucky_take = min(m, k)
    for i in range(max_lucky_take + 1):
        t = k - i
        if 0 <= t <= non_lucky:
            ans = (ans + dp[i] * nCk(non_lucky, t)) % MOD

    print(ans)

if __name__ == "__main__":
    solve()

