class disjointset:
    def __init__(self, n):
        self.rank, self.parent= [0] * (n + 1), [i for i in range(n + 1)]

    def find(self, x):
        xcopy = x
        while x != self.parent[x]:
            x = self.parent[x]

        while xcopy != x:
            self.parent[xcopy], xcopy = x, self.parent[xcopy]

        return x

    def union(self, x, y):
        xpar, ypar = self.find(x), self.find(y)

        # already union
        if xpar == ypar:
            return
        # perform union by rank
        par, child = xpar, ypar
        if self.rank[xpar] < self.rank[ypar]:
            par, child = ypar, xpar

        elif self.rank[xpar] == self.rank[ypar]:
            self.rank[xpar] += 1

        self.parent[child] = par

    # find min total weight tree
    def kruskal(self, edges):
        result, all, rem = 0, [], []

        # loop over v-1
        for u, v, w in edges:
            upar, vpar = self.find(u), self.find(v)

            # no cycle
            if upar != vpar:
                all.append(w)
                self.union(upar, vpar)
                result += max(0, w - k)
