import sys

def parse_in_base(s: str, base: int):
    """Return integer value of s in given base, or None if invalid digit for base."""
    val = 0
    for ch in s:
        if '0' <= ch <= '9':
            d = ord(ch) - ord('0')
        else:
            d = ord(ch) - ord('A') + 10
        if d >= base:
            return None
        val = val * base + d
    return val

def main():
    t = sys.stdin.readline().strip()
    if not t:
        return
    a, b = t.split(':')

    digits = a + b
    max_digit = 0
    for ch in digits:
        if '0' <= ch <= '9':
            d = ord(ch) - ord('0')
        else:
            d = ord(ch) - ord('A') + 10
        if d > max_digit:
            max_digit = d

    # Minimal possible radix is max_digit+1, but at least 2
    min_base = max(2, max_digit + 1)

    ans = []
    # Digits are 0-9, A-Z => max digit 35 => max base 36
    for base in range(min_base, 37):
        ha = parse_in_base(a, base)
        if ha is None or ha > 23:
            continue
        mb = parse_in_base(b, base)
        if mb is None or mb > 59:
            continue
        ans.append(str(base))

    if ans:
        sys.stdout.write(" ".join(ans) + "\n")
    else:
        sys.stdout.write("0\n")

if __name__ == "__main__":
    main()

