    n = int(data[0])
    t = int(data[1])

    # y_i in {1,2,3,4}, and adjacent y's must differ (no horizontal segment).
    # "Humps": local maxima count = t, local minima count = t-1.
    # For sequences with no equal neighbors:
    # Let turns = count of i (2..n-1) with (y[i-1] < y[i] > y[i+1]) or (y[i-1] > y[i] < y[i+1]).
    # Then maxima+minima = turns.
    # If first turn is a maximum then maxima = ceil(turns/2), minima = floor(turns/2).
    # If first turn is a minimum then maxima = floor(turns/2), minima = ceil(turns/2).
    # Need maxima=t, minima=t-1 => turns = 2t-1 and first turn must be a maximum.
    turns_needed = 2 * t - 1
    if turns_needed < 0:
        print(0)
        return
    if n < 2:
        print(0)
        return
    if turns_needed > n - 2:  # turns occur at internal vertices only
        print(0)
        return

    # DP over positions with last two y-values and number of turns so far.
    # Determine turn at position i-1 when choosing y_i based on y_{i-2}, y_{i-1}, y_i.
    # Also track whether the first turn (if any) was a maximum.
    # Since y in 1..4, last two values -> 4*4=16, turns up to n.
    maxk = turns_needed

    # dp[a][b][k][f]:
    # a = y_{i-1}, b = y_i (as we process i), but we'll store last two after adding new.
    # f: 0 = no turn seen yet; 1 = first turn was max; 2 = first turn was min (invalid ultimately)
    # We'll keep dict-like arrays for speed.
    # We'll initialize with length 2 sequences.
    dp = [[[[0]*3 for _ in range(maxk+1)] for _ in range(5)] for _ in range(5)]
    for y1 in range(1,5):
        for y2 in range(1,5):
            if y1 != y2:
                dp[y1][y2][0][0] = (dp[y1][y2][0][0] + 1) % MOD

    # Process positions 3..n
    for _pos in range(3, n+1):
        ndp = [[[[0]*3 for _ in range(maxk+1)] for _ in range(5)] for _ in range(5)]
        for yprevprev in range(1,5):
            for yprev in range(1,5):
                for k in range(maxk+1):
                    row = dp[yprevprev][yprev][k]
                    if row[0][0] == 0 and row[0][1] == 0 and row[0][2] == 0:
                        pass
                # (we won't use this shortcut; keep simple loops)

        for a in range(1,5):
            for b in range(1,5):
                if a == b:
                    continue
                for k in range(maxk+1):
                    for f in range(3):
                        cur = dp[a][b][k][f]
                        if not cur:
                            continue
                        for c in range(1,5):
                            if c == b:
                                continue
                            nk = k
                            nf = f
                            # Check if b is a local extremum given (a,b,c)
                            is_turn = False
                            is_max = False
                            if a < b > c:
                                is_turn = True
                                is_max = True
                            elif a > b < c:
                                is_turn = True
                                is_max = False

                            if is_turn:
                                if k == maxk:
                                    continue
                                nk = k + 1
                                if f == 0:
                                    nf = 1 if is_max else 2

