        # from (r1, c1) to (r2, c2) is possible iff:
        #   r2 >= r1 and c1 <= c2 <= c1 + (r2 - r1)
        # Therefore the only possible visiting order is by increasing layer r.
        points.sort()

        cur_r, cur_c = 1, 1
        for pr, pc in points:
            if pr < cur_r:
                return False, (
                    f"SPEC_INVALID: traversal impossible in test case {case_idx}"
                )
            if not (cur_c <= pc <= cur_c + (pr - cur_r)):
                return False, (
                    f"SPEC_INVALID: traversal impossible in test case {case_idx}"
                )
            cur_r, cur_c = pr, pc

    if idx != len(vals):
        return False, "FORMAT_INVALID: extra tokens after all test cases"

    return True, "OK"

import re
from typing import Tuple

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validate input for Codeforces 1512G - Short Task.

    Returns:
        (True, "OK") if valid
        (False, "<PREFIX>: <reason>") otherwise, where PREFIX is FORMAT_INVALID or SPEC_INVALID
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if s == "":
        return False, "FORMAT_INVALID: empty input"

    # Only allow whitespace and optional leading minus for tokens; we'll validate ranges later.
    # Safer: parse all integer tokens and ensure they match the full content.
    tokens = re.findall(r"[+-]?\d+", s)
    if not tokens:
        return False, "FORMAT_INVALID: no integers found"

    # Ensure there are no non-whitespace, non-integer characters
    remainder = re.sub(r"[+-]?\d+", " ", s)
    if remainder.strip() != "":
        return False, "FORMAT_INVALID: contains non-integer tokens/characters"

    try:
        vals = list(map(int, tokens))
    except Exception:
        return False, "FORMAT_INVALID: failed to parse integers"

    if len(vals) < 1:
        return False, "FORMAT_INVALID: missing t"

    t = vals[0]
    if t < 1 or t > 10**4:
        return False, f"SPEC_INVALID: t out of range (1..1e4), got {t}"

    if len(vals) != 1 + t:
        return False, f"FORMAT_INVALID: expected {1+t} integers (t plus t cases), got {len(vals)}"

    for i in range(t):
        c = vals[1 + i]
        if c < 1 or c > 10**7:
            return False, f"SPEC_INVALID: c out of range (1..1e7) at case {i+1}, got {c}"

    return True, "OK"

