def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validates input for Codeforces 1525D - Armchairs.

    Returns:
      (True, "OK") if valid
      (False, "<PREFIX>: <reason>") otherwise
    Prefixes:
      FORMAT_INVALID - tokenization/structure issues
      SPEC_INVALID   - violates constraints
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    s = inp.strip()
    if not s:
        return (False, "FORMAT_INVALID: empty input")

    tokens = s.split()
    # Need at least n and n numbers
    if len(tokens) < 2:
        return (False, "FORMAT_INVALID: not enough tokens")

    # Parse n
    try:
        n = int(tokens[0])
    except Exception:
        return (False, "FORMAT_INVALID: first token is not an integer (n)")

    if n < 2 or n > 5000:
        return (False, "SPEC_INVALID: n out of range [2, 5000]")

    expected = 1 + n
    if len(tokens) != expected:
        return (False, f"FORMAT_INVALID: expected {expected} tokens (n plus n values), got {len(tokens)}")

    # Parse array a
    ones = 0
    for i in range(n):
        t = tokens[1 + i]
        try:
            v = int(t)
        except Exception:
            return (False, f"FORMAT_INVALID: a[{i+1}] is not an integer")
        if v not in (0, 1):
            return (False, f"SPEC_INVALID: a[{i+1}] must be 0 or 1")
        ones += v

    if ones > n // 2:
        return (False, "SPEC_INVALID: number of occupied armchairs exceeds n/2")

    return (True, "OK")

