import re

_INT_RE = re.compile(r"^[+-]?\d+$")


def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validator for Codeforces 152B - Steps.

    Expected input format:
      line 1: n m
      line 2: xc yc
      line 3: k
      next k lines: dxi dyi

    Constraints:
      1 <= n, m <= 10^9
      1 <= xc <= n
      1 <= yc <= m
      1 <= k <= 2 * 10^5
      -10^9 <= dxi, dyi <= 10^9
      (dxi, dyi) != (0, 0)
    """

    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    # Allow trailing whitespace/newlines, but not an entirely empty input.
    data = inp.rstrip()
    if data == "":
        return False, "FORMAT_INVALID: empty input"

    lines = data.splitlines()

    def parse_line(line_no: int, expected_count: int) -> tuple[bool, str, list[int]]:
        if line_no > len(lines):
            return False, f"FORMAT_INVALID: missing line {line_no}", []

        parts = lines[line_no - 1].split()
        if len(parts) != expected_count:
            return (
                False,
                f"FORMAT_INVALID: line {line_no} must contain exactly "
                f"{expected_count} integer(s), got {len(parts)}",
                [],
            )

        values: list[int] = []
        for tok in parts:
            if not _INT_RE.fullmatch(tok):
                return False, f"FORMAT_INVALID: non-integer token '{tok}' on line {line_no}", []
            try:
                values.append(int(tok))
            except Exception:
                return False, f"FORMAT_INVALID: invalid integer token '{tok}' on line {line_no}", []

        return True, "OK", values

    if len(lines) < 3:
        return False, "FORMAT_INVALID: expected at least 3 lines"

    ok, msg, vals = parse_line(1, 2)
    if not ok:
        return False, msg
    n, m = vals

    ok, msg, vals = parse_line(2, 2)
    if not ok:
        return False, msg
    xc, yc = vals

    ok, msg, vals = parse_line(3, 1)
    if not ok:
        return False, msg
    k = vals[0]

    if not (1 <= n <= 10**9):
        return False, "SPEC_INVALID: n out of range (1..1e9)"
    if not (1 <= m <= 10**9):
        return False, "SPEC_INVALID: m out of range (1..1e9)"
    if not (1 <= xc <= n):
        return False, "SPEC_INVALID: xc out of range (1..n)"
    if not (1 <= yc <= m):
        return False, "SPEC_INVALID: yc out of range (1..m)"
    if not (1 <= k <= 2 * 10**5):
        return False, "SPEC_INVALID: k out of range (1..2e5)"

    expected_lines = 3 + k
    if len(lines) < expected_lines:
        return False, f"FORMAT_INVALID: expected {expected_lines} lines, got {len(lines)}"
    if len(lines) > expected_lines:
        return False, f"FORMAT_INVALID: extra data after {expected_lines} expected lines"

    for i in range(k):
        line_no = 4 + i
        ok, msg, vals = parse_line(line_no, 2)
        if not ok:
            return False, msg

        dx, dy = vals

        if not (-10**9 <= dx <= 10**9):
            return False, f"SPEC_INVALID: dx of vector {i + 1} out of range (-1e9..1e9)"
        if not (-10**9 <= dy <= 10**9):
            return False, f"SPEC_INVALID: dy of vector {i + 1} out of range (-1e9..1e9)"
        if dx == 0 and dy == 0:
            return False, f"SPEC_INVALID: vector {i + 1} has zero length (0,0)"

    return True, "OK"

