        total_n += n
        if total_n > 2 * 10**5:
            return False, "SPEC_INVALID: sum of n over all test cases exceeds 200000"

        if idx + n > len(tokens):
            return False, f"FORMAT_INVALID: missing array values in test case {case}"

        for i in range(n):
