    ok, q, err = need_int()
    if not ok:
        return False, err
    if not (1 <= q <= 2 * 10**5):
        return False, f"SPEC_INVALID: q out of range (got {q})"

    seen_type3 = 0

    # Read queries
    for qi in range(q):
        ok, t, err = need_int()
        if not ok:
            return False, err

        if t == 3:
            seen_type3 += 1
            # No extra tokens for this query
        elif t == 1 or t == 2:
            ok, u, err = need_int()
            if not ok:
                return False, err
            ok, v, err = need_int()
            if not ok:
                return False, err

            if not (1 <= u <= n) or not (1 <= v <= n):
                return False, f"SPEC_INVALID: query {qi+1} endpoint out of range"
            if u == v:
                return False, f"SPEC_INVALID: query {qi+1} has self-loop"

            p = norm_pair(u, v)
            if t == 1:
                # guaranteed not friends at this moment
                if p in edges:
                    return False, f"SPEC_INVALID: query {qi+1} adds existing friendship ({u}, {v})"
                edges.add(p)
            else:
                # t == 2, guaranteed friends at this moment
                if p not in edges:
                    return False, f"SPEC_INVALID: query {qi+1} removes non-existing friendship ({u}, {v})"
                edges.remove(p)
        else:
            return False, f"FORMAT_INVALID: unknown query type {t} at query {qi+1}"

    if k != len(toks):
        return False, "FORMAT_INVALID: extra tokens after reading all queries"

    if seen_type3 == 0:
        return False, "SPEC_INVALID: no type 3 query present (but at least one is required)"

    return True, "OK"

import re
from typing import Tuple

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validates input for Codeforces 154A - Hometask.

    Expected format (per CF problem):
      n m
      s
      then m lines: a b   (each is a lowercase letter, a != b)

    Constraints (from typical CF statement for this problem):
      1 <= n <= 10^5
      0 <= m <= 26
      s is lowercase letters, length == n
      Each letter appears in at most one forbidden pair (across all m pairs).
      (Order doesn't matter; pair is undirected.)
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    # Normalize newlines but do not strip internal spaces.
    text = inp.replace("\r\n", "\n").replace("\r", "\n")

    # Disallow leading/trailing junk lines consisting only of whitespace
    # (CF input usually doesn't care, but validator should be strict-ish).
    # We'll allow trailing whitespace overall, but not extra non-empty lines.
    lines = text.split("\n")
    # Drop final empty line if input ends with newline
    if lines and lines[-1] == "":
        lines.pop()

    if not lines:
        return (False, "FORMAT_INVALID: empty input")

    # First line: n m
    first = lines[0].strip()
    if not first:
        return (False, "FORMAT_INVALID: missing 'n m' line")

    parts = first.split()
    if len(parts) != 2:
        return (False, "FORMAT_INVALID: first line must contain exactly two integers 'n m'")
    try:
        n = int(parts[0])
        m = int(parts[1])
    except ValueError:
        return (False, "FORMAT_INVALID: n and m must be integers")

    # Spec constraints
    if n < 1:
        return (False, "SPEC_INVALID: n must be >= 1")
    if n > 100000:
        return (False, "SPEC_INVALID: n must be <= 100000")
    if m < 0:
        return (False, "SPEC_INVALID: m must be >= 0")
    if m > 26:
        return (False, "SPEC_INVALID: m must be <= 26")

    # Need at least line for s
    if len(lines) < 2:
        return (False, "FORMAT_INVALID: missing string s line")

    s = lines[1].strip()
    if len(s) != n:
        return (False, f"SPEC_INVALID: length of s must be exactly n={n}")
    if not re.fullmatch(r"[a-z]+", s):
        return (False, "FORMAT_INVALID: s must contain only lowercase Latin letters a-z")

    # Now expect exactly m pair-lines
    expected_total_lines = 2 + m
    if len(lines) != expected_total_lines:
        if len(lines) < expected_total_lines:
            return (False, f"FORMAT_INVALID: expected {m} forbidden-pair lines, got {max(0, len(lines)-2)}")
        else:
            return (False, f"FORMAT_INVALID: extra lines present (expected {expected_total_lines} lines total)")

    used_letters = set()
    pairs_seen = set()  # normalized (min(a,b), max(a,b))
    for i in range(m):
        line = lines[2 + i].strip()
        if not line:
            return (False, f"FORMAT_INVALID: forbidden pair line {i+1} is empty")

        p = line.split()
        if len(p) != 2:
            return (False, f"FORMAT_INVALID: forbidden pair line {i+1} must contain exactly two tokens")
        a, b = p[0], p[1]

        if len(a) != 1 or len(b) != 1:
            return (False, f"FORMAT_INVALID: forbidden pair line {i+1} tokens must be single letters")
        if not ("a" <= a <= "z") or not ("a" <= b <= "z"):
            return (False, f"FORMAT_INVALID: forbidden pair line {i+1} letters must be lowercase a-z")
        if a == b:
            return (False, f"SPEC_INVALID: forbidden pair line {i+1} must contain two different letters")

        # Each letter occurs in no more than one forbidden pair
        if a in used_letters:
            return (False, f"SPEC_INVALID: letter '{a}' appears in more than one forbidden pair")
        if b in used_letters:
            return (False, f"SPEC_INVALID: letter '{b}' appears in more than one forbidden pair")

        norm = (a, b) if a < b else (b, a)
        if norm in pairs_seen:
            return (False, f"SPEC_INVALID: duplicate forbidden pair '{norm[0]} {norm[1]}'")
        pairs_seen.add(norm)

        used_letters.add(a)
        used_letters.add(b)

    return (True, "OK")

