    if len(tokens) != expected:
        if len(tokens) < expected:
            return False, f"FORMAT_INVALID: not enough integers (expected {expected}, got {len(tokens)})"
        else:
            return False, f"FORMAT_INVALID: too many integers (expected {expected}, got {len(tokens)})"

