def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validates input for Codeforces 1553C "Penalty".

    Returns:
        (True, "OK") if valid
        (False, "<PREFIX>: <reason>") otherwise
    Prefix is one of: FORMAT_INVALID, SPEC_INVALID.
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp

    # Be tolerant of trailing whitespace/newlines, but not of leading junk before t.
    s_stripped = s.strip()
    if s_stripped == "":
        return False, "FORMAT_INVALID: empty input"

    lines = s.splitlines()
    if not lines:
        return False, "FORMAT_INVALID: no lines found"

    # Allow leading/trailing blank lines, but ignore them carefully
    # Find first non-empty line for t
    idx = 0
    while idx < len(lines) and lines[idx].strip() == "":
        idx += 1
    if idx == len(lines):
        return False, "FORMAT_INVALID: no non-empty lines"

    first = lines[idx].strip()
    if not re.fullmatch(r"[+-]?\d+", first):
        return False, "FORMAT_INVALID: first non-empty line must be an integer t"
    try:
        t = int(first)
    except Exception:
        return False, "FORMAT_INVALID: cannot parse t as integer"

    if not (1 <= t <= 1000):
        return False, f"SPEC_INVALID: t out of range (1..1000), got {t}"

    # Collect next non-empty lines as test cases; in CF input there are no empty
    # lines, but we can treat empty lines as ignorable.
    cases = []
    j = idx + 1
    while j < len(lines) and len(cases) < t:
        line = lines[j].strip()
        if line != "":
            cases.append(line)
        j += 1

    if len(cases) < t:
        return False, f"FORMAT_INVALID: expected {t} test case lines, got {len(cases)}"

    # After reading t cases, remaining non-empty content is invalid (extra tokens/lines)
    while j < len(lines):
        if lines[j].strip() != "":
            return False, "FORMAT_INVALID: extra non-empty lines after last test case"
        j += 1

    allowed = set("10?")
    for ci, case in enumerate(cases, start=1):
        if len(case) != 10:
            return False, f"SPEC_INVALID: test case {ci} length must be 10, got {len(case)}"
        bad = [ch for ch in case if ch not in allowed]
        if bad:
            return False, (
                f"SPEC_INVALID: test case {ci} contains invalid characters "
                f"(allowed only '1','0','?'), got {sorted(set(bad))}"
            )

    return True, "OK"

