    if len(tokens) != expected:
        if len(tokens) < expected:
            return False, f"FORMAT_INVALID: expected {t} testcases but only found {len(tokens)-1}"
        else:
            return False, f"FORMAT_INVALID: expected exactly {expected} integers, found {len(tokens)}"

