def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validate input for Codeforces 1561B: Charmed by the Game.

    Returns:
      (True, "OK") if valid
      (False, "<PREFIX>: <reason>") otherwise, where PREFIX is FORMAT_INVALID or SPEC_INVALID
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if s == "":
        return False, "FORMAT_INVALID: empty input"

    # Only allow whitespace-separated integers (typical CF input).
    # Reject any other tokens.
    tokens = re.findall(r"[+-]?\d+|\S", s)
    if any(not re.fullmatch(r"[+-]?\d+", tok) for tok in tokens):
        bad = next(tok for tok in tokens if not re.fullmatch(r"[+-]?\d+", tok))
        return False, f"FORMAT_INVALID: non-integer token '{bad}'"

    try:
        nums = list(map(int, tokens))
    except Exception:
        return False, "FORMAT_INVALID: failed to parse integers"

    if len(nums) < 1:
        return False, "FORMAT_INVALID: missing t"

    t = nums[0]
    if t <= 0:
        return False, "SPEC_INVALID: t must be >= 1"
    if t > 10**3:
        return False, "SPEC_INVALID: t must be <= 1e3"

    expected = 1 + 2 * t
    if len(nums) != expected:
        if len(nums) < expected:
            return False, f"FORMAT_INVALID: expected {expected} integers total, got {len(nums)} (missing a/b pairs)"
        else:
            return False, f"FORMAT_INVALID: expected {expected} integers total, got {len(nums)} (extra data)"

    total_sum = 0
    idx = 1
    for case in range(1, t + 1):
        a = nums[idx]
        b = nums[idx + 1]
