        if a + b <= 0:
            return False, f"SPEC_INVALID: a+b must be > 0 (case {case})"

        total_sum += a + b

    if total_sum > 2 * 10**5:
        return False, "SPEC_INVALID: sum over test cases of (a+b) must be <= 2e5"

    return True, "OK"

