    try:
        vals = list(map(int, toks))
    except Exception as e:
        return (False, f"FORMAT_INVALID: integer conversion failed: {e}")

    idx = 0
    if idx >= m:
        return (False, "FORMAT_INVALID: missing t")
    t = vals[idx]; idx += 1

