                return (False, f"FORMAT_INVALID: missing k_i for test case {tc}, cave {cave}")
            k = vals[idx]; idx += 1
            if not (1 <= k <= 10**5):
                return (False, f"SPEC_INVALID: k_i out of range (1..1e5) in test case {tc}, cave {cave}, got {k}")

            total_k += k
            if total_k > 10**5:
                return (False, f"SPEC_INVALID: sum of k_i exceeds 1e5 (got {total_k})")

            if idx + k > m:
                return (False, f"FORMAT_INVALID: not enough armor values for test case {tc}, cave {cave} (need {k})")

