import sys

def solve():
    it = iter(sys.stdin.buffer.read().split())
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it)); q = int(next(it))
        s = next(it).decode()

        # pref[i] = sum_{k=1..i} ((-1)^(k-1) * a_k), where a_k = +1 for '+', -1 for '-'
        pref = [0] * (n + 1)
        for i, ch in enumerate(s, 1):
            a = 1 if ch == '+' else -1
            if i & 1:
                pref[i] = pref[i - 1] + a
            else:
                pref[i] = pref[i - 1] - a

        for _q in range(q):
            l = int(next(it)); r = int(next(it))
            val = pref[r] - pref[l - 1]
            if l % 2 == 0:
                val = -val  # normalize so that segment starts with '+' sign in alternating sum
            if val == 0:
                out_lines.append("0")
            else:
                if (r - l + 1) % 2 == 1:
                    out_lines.append("1")
                else:
                    out_lines.append("2")

    sys.stdout.write("\n".join(out_lines))

