    Returns: (ok: bool, reason: str)
      - If ok is True, reason is "OK".
      - If ok is False, reason starts with "FORMAT_INVALID" or "SPEC_INVALID".
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp
    n = len(s)

    i = 0

    def skip_ws(idx: int) -> int:
        while idx < n and s[idx].isspace():
            idx += 1
        return idx

    def read_int(idx: int):
        idx = skip_ws(idx)
        if idx >= n:
            return None, idx, "FORMAT_INVALID: missing integer"
        sign = 1
        if s[idx] in "+-":
            if s[idx] == "-":
                sign = -1
            idx += 1
        start = idx
        while idx < n and s[idx].isdigit():
            idx += 1
        if idx == start:
            return None, idx, "FORMAT_INVALID: invalid integer token"
        try:
            val = int(s[start:idx]) * sign
        except Exception:
            return None, idx, "FORMAT_INVALID: integer parse error"
        return val, idx, None

    def read_token(idx: int):
        idx = skip_ws(idx)
        if idx >= n:
            return None, idx, "FORMAT_INVALID: missing token"
        start = idx
        while idx < n and not s[idx].isspace():
            idx += 1
        return s[start:idx], idx, None

    # Read t
    t, i, err = read_int(i)
    if err:
        return False, err
    if t is None:
        return False, "FORMAT_INVALID: missing t"
    if not (1 <= t <= 10**4):
        return False, f"SPEC_INVALID: t out of range (got {t}, expected 1..1e4)"

    total_len = 0

    for case in range(1, t + 1):
        tok, i, err = read_token(i)
        if err:
            return False, f"{err} (at test case {case})"
        if tok is None:
            return False, f"FORMAT_INVALID: missing string for test case {case}"

        # Token must be a binary string only (no embedded spaces by construction)
        if not re.fullmatch(r"[01]+", tok or ""):
            return False, f"FORMAT_INVALID: non-binary or empty string at test case {case}"

        L = len(tok)
        if not (1 <= L <= 10**5):
            return False, f"SPEC_INVALID: |s| out of range at test case {case} (got {L}, expected 1..1e5)"

