    n_total = len(s)
    i = 0

    def skip_ws(idx: int) -> int:
        while idx < n_total and s[idx].isspace():
            idx += 1
        return idx

    def read_int(idx: int):
        idx = skip_ws(idx)
        if idx >= n_total:
            return None, idx, "FORMAT_INVALID: unexpected EOF while reading integer"
        sign = 1
        if s[idx] in "+-":
            if s[idx] == "-":
                sign = -1
            idx += 1
        if idx >= n_total or not s[idx].isdigit():
            return None, idx, "FORMAT_INVALID: expected integer"
        val = 0
        while idx < n_total and s[idx].isdigit():
            val = val * 10 + (ord(s[idx]) - 48)
            idx += 1
        return sign * val, idx, None

    def read_bin_string(idx: int):
        idx = skip_ws(idx)
        if idx >= n_total:
            return None, idx, "FORMAT_INVALID: unexpected EOF while reading binary string"
        start = idx
        # read until whitespace
        while idx < n_total and not s[idx].isspace():
            idx += 1
        token = s[start:idx]
        if token == "":
            return None, idx, "FORMAT_INVALID: expected binary string"
        if re.fullmatch(r"[01]+", token) is None:
            return None, idx, "FORMAT_INVALID: binary string must contain only '0' and '1'"
        return token, idx, None

    # Read t
    t, i, err = read_int(i)
    if err:
        return False, err
    if t is None:
        return False, "FORMAT_INVALID: missing t"
    if t < 1 or t > 10**4:
        return False, f"SPEC_INVALID: t out of range [1, 1e4], got {t}"

    sum_n = 0

    for tc in range(1, t + 1):
        n, i, err = read_int(i)
        if err:
            return False, err + f" (at test case {tc})"
        if n is None:
            return False, f"FORMAT_INVALID: missing n (at test case {tc})"
        if n < 1 or n > 10**5:
            return False, f"SPEC_INVALID: n out of range [1, 1e5] at test case {tc}, got {n}"
        sum_n += n
        if sum_n > 10**5:
            return False, f"SPEC_INVALID: sum of n exceeds 1e5 (exceeded at test case {tc})"

        a, i, err = read_bin_string(i)
        if err:
            return False, err + f" (at test case {tc}, row 1)"
        b, i, err = read_bin_string(i)
        if err:
            return False, err + f" (at test case {tc}, row 2)"

        if len(a) != n:
            return False, f"SPEC_INVALID: row 1 length != n at test case {tc} (len={len(a)}, n={n})"
        if len(b) != n:
            return False, f"SPEC_INVALID: row 2 length != n at test case {tc} (len={len(b)}, n={n})"

    # No extra non-whitespace tokens
    i = skip_ws(i)
    if i != n_total:
        # There is some non-whitespace trailing garbage
        # Find the next token for a helpful message
        start = i
        while i < n_total and not s[i].isspace():
            i += 1
        tok = s[start:i]
        return False, f"FORMAT_INVALID: extra trailing token(s) after last test case: {tok!r}"

    return True, "OK"

