            return None, "FORMAT_INVALID: unexpected end of input"
        tok = tokens[idx]
        idx += 1
        try:
            return int(tok), None
        except ValueError:
            return None, f"FORMAT_INVALID: expected integer, got {tok!r}"

    t, err = next_int()
    if err:
        return False, err

    if not (1 <= t <= 10_000):
        return False, "SPEC_INVALID: t out of range"

    total_n = 0

    class DSU:
        def __init__(self, n: int):
            self.parent = list(range(n + 1))
            self.size = [1] * (n + 1)
            self.components = n

        def find(self, x: int) -> int:
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x

        def union(self, a: int, b: int) -> bool:
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                return False
            if self.size[ra] < self.size[rb]:
                ra, rb = rb, ra
            self.parent[rb] = ra
            self.size[ra] += self.size[rb]
            self.components -= 1
            return True

    for case_idx in range(1, t + 1):
        n, err = next_int()
        if err:
            return False, err

