import sys

def xor_upto(n: int) -> int:
    # XOR of [0, 1, ..., n]
    r = n & 3
    if r == 0:
        return n
    if r == 1:
        return 1
    if r == 2:
        return n + 1
    return 0

def solve():
    it = iter(sys.stdin.buffer.read().split())
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        a = int(next(it))
        b = int(next(it))

        x = xor_upto(a - 1)  # XOR of 0..a-1
        if x == b:
            out_lines.append(str(a))
            continue

        y = x ^ b
        # We must keep MEX = a, so elements 0..a-1 must be present and 'a' must be absent.
        # If adding one element y doesn't break MEX (i.e., y != a), length is a+1.
        if y != a:
            out_lines.append(str(a + 1))
        else:
            # If y == a, we can't add 'a' (it would make MEX > a), so need two extra elements.
            out_lines.append(str(a + 2))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

