from collections import defaultdict, deque

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    friends = [[] for _ in range(n)]
    dislikes = [[] for _ in range(n)]

    for _ in range(m):
        t = int(next(it))
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        if t == 1:
            friends[a].append(b)
            friends[b].append(a)
        else:
            dislikes[a].append(b)
            dislikes[b].append(a)

    # Find connected components in the friendship graph.
    comp_id = [-1] * n
    comps = []
    for i in range(n):
        if comp_id[i] != -1:
            continue
        q = deque([i])
        comp_id[i] = len(comps)
        nodes = []
        while q:
            v = q.popleft()
            nodes.append(v)
            for u in friends[v]:
                if comp_id[u] == -1:
                    comp_id[u] = comp_id[i]
                    q.append(u)
        comps.append(nodes)

