        for u in dislikes[v]:
            if comp_id[u] == cv:
                valid[cv] = False
                break

    ans = 0
    for cid, nodes in enumerate(comps):
        if valid[cid]:
            ans = max(ans, len(nodes))

    sys.stdout.write(str(ans))

