def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    s0 = data[2].strip()
    s1 = data[3].strip()

    # visited[wall][pos], pos in [0..n] where pos is 1-based in problem, we store 0..n-1
    visited0 = [False] * n
    visited1 = [False] * n

    # Start at left wall, position 1 => index 0, time 0
    if s0[0] == 'X':
        print("NO")
        return

    q = deque()
    q.append((0, 0, 0))  # wall, idx, time
    visited0[0] = True

    def is_safe(wall: int, idx: int) -> bool:
        if idx < 0 or idx >= n:
            return False
        if wall == 0:
            return s0[idx] != 'X'
        else:
            return s1[idx] != 'X'

    while q:
        wall, idx, t = q.popleft()

        # If current position is already flooded at the start of time t, it is invalid.
        # Water level after t seconds is at height t (covers cells 1..t),
        # so ninja must have position (1-based) > t => idx >= t.
        if idx < t:
            continue

        nt = t + 1
        other = wall ^ 1

        # Move up: idx + 1
        ni = idx + 1
        if ni >= n:
            print("YES")
            return
        if ni >= nt and is_safe(wall, ni):
            if wall == 0:
                if not visited0[ni]:
                    visited0[ni] = True
                    q.append((wall, ni, nt))
            else:
                if not visited1[ni]:
                    visited1[ni] = True
                    q.append((wall, ni, nt))

        # Move down: idx - 1
        ni = idx - 1
        if ni >= n:
            print("YES")
            return
        if ni >= 0 and ni >= nt and is_safe(wall, ni):
            if wall == 0:
                if not visited0[ni]:
                    visited0[ni] = True
                    q.append((wall, ni, nt))
            else:
                if not visited1[ni]:
                    visited1[ni] = True
                    q.append((wall, ni, nt))

        # Jump: idx + k to other wall
        ni = idx + k
        if ni >= n:
            print("YES")
            return
        if ni >= nt and is_safe(other, ni):
            if other == 0:
                if not visited0[ni]:
                    visited0[ni] = True
                    q.append((other, ni, nt))
            else:
                if not visited1[ni]:
                    visited1[ni] = True
                    q.append((other, ni, nt))

    print("NO")


