def parse_format(input_str: str) -> Tuple[bool, Any]:
    s = input_str
    if s is None:
        return False, "FORMAT_INVALID: input is None"
    s = s.strip()
    if s == "":
        return False, "FORMAT_INVALID: empty input"

    lines = s.splitlines()
    if len(lines) < 1:
        return False, "FORMAT_INVALID: missing first line"

    # First line: n m
    first = lines[0].strip()
    if first == "":
        return False, "FORMAT_INVALID: first line is empty"
    t0 = first.split()
    if len(t0) != 2:
        return False, f"FORMAT_INVALID: first line must have exactly 2 integers (n m), got {len(t0)} token(s)"
    try:
        n = int(t0[0])
        m = int(t0[1])
    except ValueError:
        return False, "FORMAT_INVALID: n and m must be integers"

    # Next m lines: a b w
    if len(lines) != 1 + m:
        return False, f"FORMAT_INVALID: expected exactly {1 + m} line(s) (1 header + m edges), got {len(lines)}"

    edges: List[Tuple[int, int, int]] = []
    for i in range(m):
        line = lines[1 + i].strip()
        if line == "":
            return False, f"FORMAT_INVALID: edge line {i+1} is empty"
        toks = line.split()
        if len(toks) != 3:
            return False, f"FORMAT_INVALID: edge line {i+1} must have exactly 3 integers (a b w), got {len(toks)} token(s)"
        try:
            a = int(toks[0])
            b = int(toks[1])
            w = int(toks[2])
        except ValueError:
            return False, f"FORMAT_INVALID: edge line {i+1} must contain integers (a b w)"
        edges.append((a, b, w))

    return True, {"n": n, "m": m, "edges": edges}


