        return False, f"SPEC_INVALID: m out of bounds (0..100000), got {m}"
    if len(edges) != m:
        return False, f"SPEC_INVALID: expected {m} edges, parsed {len(edges)}"

    for idx, (a, b, w) in enumerate(edges, start=1):
        if not (1 <= a <= n):
            return False, f"SPEC_INVALID: edge {idx} has a out of range (1..n), got {a} with n={n}"
        if not (1 <= b <= n):
            return False, f"SPEC_INVALID: edge {idx} has b out of range (1..n), got {b} with n={n}"
        if not (1 <= w <= 1000000):
            return False, f"SPEC_INVALID: edge {idx} has weight out of bounds (1..1000000), got {w}"

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, res = parse_format(input_str)
    if not ok:
