def solve():
    sys.setrecursionlimit(1_000_000)
    input = sys.stdin.readline

    n = int(input().strip())
    a = [[0]*(n+1)]
    for _ in range(n):
        a.append([0] + list(map(int, input().split())))

    # dp arrays: best sum from one corner to (i,j), moving only in allowed directions
    dp1 = [[0]*(n+2) for _ in range(n+2)]  # from (1,1) to (i,j) (down/right)
    dp2 = [[0]*(n+2) for _ in range(n+2)]  # from (n,n) to (i,j) (up/left)
    dp3 = [[0]*(n+2) for _ in range(n+2)]  # from (1,n) to (i,j) (down/left)
    dp4 = [[0]*(n+2) for _ in range(n+2)]  # from (n,1) to (i,j) (up/right)

    # dp1
    for i in range(1, n+1):
        for j in range(1, n+1):
            dp1[i][j] = a[i][j] + max(dp1[i-1][j], dp1[i][j-1])

    # dp2
    for i in range(n, 0, -1):
        for j in range(n, 0, -1):
            dp2[i][j] = a[i][j] + max(dp2[i+1][j], dp2[i][j+1])

    # dp3 (from (1,n) -> (i,j) using down/left)
    for i in range(1, n+1):
        for j in range(n, 0, -1):
            dp3[i][j] = a[i][j] + max(dp3[i-1][j], dp3[i][j+1])

    # dp4 (from (n,1) -> (i,j) using up/right)
    for i in range(n, 0, -1):
        for j in range(1, n+1):
            dp4[i][j] = a[i][j] + max(dp4[i+1][j], dp4[i][j-1])

    ans = 0
    # Internal cells as crossing vicinity; two possible non-overlapping configurations
    for i in range(2, n):
        for j in range(2, n):
            # Case 1:
            # Path A (1,1)->...->(i,j-1)->(i,j)->(i,j+1)->...->(n,n)
            # Path B (1,n)->...->(i-1,j)->(i,j)->(i+1,j)->...->(n,1)
            # Meeting at (i,j) is avoided by taking neighbors:
            v1 = dp1[i][j-1] + dp2[i][j+1] + dp3[i-1][j] + dp4[i+1][j]

            # Case 2 (swap crossing):
            v2 = dp1[i-1][j] + dp2[i+1][j] + dp3[i][j+1] + dp4[i][j-1]

            if v1 > ans:
                ans = v1
            if v2 > ans:
                ans = v2

    print(ans)

