from typing import Tuple

_INT_RE = re.compile(r"^[+-]?\d+$")

# Codeforces 216D constraints, as used by the original statement.
MIN_N = 3
MAX_N = 100_000
MAX_TOTAL_BRIDGES = 100_000
MIN_DISTANCE = 1
MAX_DISTANCE = 1_000_000_000


def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validate input for Codeforces 216D - Spider's Web.

    Expected format:
      n
      k_1 a_1,1 a_1,2 ... a_1,k1
      ...
      k_n a_n,1 a_n,2 ... a_n,kn

    Distances in each sector must be strictly increasing.
    Sum of all k_i must not exceed 100000.
    No two bridges may have a common attachment point, so adjacent sectors
    must not contain bridges at the same distance, including sectors n and 1.
    """
    if not isinstance(inp, str):
        return False, "FORMAT_INVALID: input is not a string"

    tokens = inp.split()
    if not tokens:
        return False, "FORMAT_INVALID: empty input"

    for t in tokens:
        if not _INT_RE.match(t):
            return False, f"FORMAT_INVALID: non-integer token {t!r}"

    pos = 0

    try:
        n = int(tokens[pos])
    except Exception:
        return False, "FORMAT_INVALID: cannot parse n"
    pos += 1

    if not (MIN_N <= n <= MAX_N):
        return False, f"SPEC_INVALID: n must be between {MIN_N} and {MAX_N}"

    sectors = []
    total_bridges = 0

    for i in range(n):
        if pos >= len(tokens):
            return False, f"FORMAT_INVALID: missing k_{i + 1}"

        k = int(tokens[pos])
        pos += 1

        if not (0 <= k <= MAX_TOTAL_BRIDGES):
            return False, f"SPEC_INVALID: k_{i + 1} is out of range"

        total_bridges += k
        if total_bridges > MAX_TOTAL_BRIDGES:
            return False, "SPEC_INVALID: total number of bridges exceeds limit"

        if pos + k > len(tokens):
            return False, f"FORMAT_INVALID: sector {i + 1} has fewer distances than declared"

        arr = []
        prev = None

        for j in range(k):
            d = int(tokens[pos])
            pos += 1

            if not (MIN_DISTANCE <= d <= MAX_DISTANCE):
                return False, (
                    f"SPEC_INVALID: distance in sector {i + 1}, "
                    f"position {j + 1} is out of range"
                )

            if prev is not None and d <= prev:
                return False, (
                    f"SPEC_INVALID: distances in sector {i + 1} "
                    "must be strictly increasing"
                )

            arr.append(d)
            prev = d

        sectors.append(arr)

    if pos != len(tokens):
        return False, "FORMAT_INVALID: extra tokens after sector descriptions"

    # Adjacent sectors cannot contain bridges at the same distance, otherwise
    # those bridges share an attachment point on their common main thread.
    sector_sets = [set(arr) for arr in sectors]

    for i in range(n):
        j = (i + 1) % n
        if len(sector_sets[i]) <= len(sector_sets[j]):
            common = sector_sets[i].intersection(sector_sets[j])
        else:
            common = sector_sets[j].intersection(sector_sets[i])

        if common:
            d = next(iter(common))
            return False, (
                "SPEC_INVALID: adjacent sectors "
                f"{i + 1} and {j + 1} both contain distance {d}"
            )

    return True, "OK"

