# - exact line/token structure: first line "n m"; then m lines "u v w"; then for i=1..n one line "k t1..tk"
# - numeric bounds: enforce Codeforces 229B typical bounds: 2<=n<=200000, 0<=m<=200000, 1<=u,v<=n, u!=v, 1<=w<=1e9,
#   0<=k<=200000, 0<=t<=1e9, total forbidden times sum(k)<=200000
# - array/string lengths: each planet line has exactly 1+k integers
# - graph constraints: undirected edges, no further constraints (duplicates allowed), but endpoints in range and no self-loops
# - special constraints: forbidden times for each planet must be strictly increasing (as per standard statement), and distinct


@dataclass
class Parsed:
    n: int
    m: int
    edges: List[Tuple[int, int, int]]
    forb: List[List[int]]  # 1-indexed via padding at index 0


def parse_format(input_str: str) -> Tuple[bool, str, Parsed | None]:
    if input_str is None:
        return False, "FORMAT_INVALID: input is None", None

    s = input_str
    # Keep strict: allow trailing whitespace/newline, but not empty.
    if s.strip() == "":
        return False, "FORMAT_INVALID: empty input", None

    # Tokenize by whitespace; then parse by expected structure.
    tokens = s.split()
    idx = 0

    def need_int(context: str) -> Tuple[bool, str, int | None]:
        nonlocal idx
        if idx >= len(tokens):
            return False, f"FORMAT_INVALID: missing integer for {context}", None
        tok = tokens[idx]
        idx += 1
        try:
            val = int(tok)
        except Exception:
            return False, f"FORMAT_INVALID: non-integer token '{tok}' for {context}", None
        return True, "ok", val

    ok, msg, n = need_int("n")
    if not ok:
        return False, msg, None
    ok, msg, m = need_int("m")
    if not ok:
        return False, msg, None

    edges: List[Tuple[int, int, int]] = []
    for ei in range(m):
        ok, msg, u = need_int(f"edge[{ei}].u")
        if not ok:
            return False, msg, None
        ok, msg, v = need_int(f"edge[{ei}].v")
        if not ok:
            return False, msg, None
        ok, msg, w = need_int(f"edge[{ei}].w")
        if not ok:
            return False, msg, None
        edges.append((u, v, w))

    forb: List[List[int]] = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        ok, msg, k = need_int(f"planet[{i}].k")
        if not ok:
            return False, msg, None
        if k is None:
            return False, "FORMAT_INVALID: internal parse error", None
        times: List[int] = []
        for j in range(k):
            ok, msg, t = need_int(f"planet[{i}].t[{j}]")
            if not ok:
                return False, msg, None
            times.append(t)
        forb[i] = times

    if idx != len(tokens):
        extra = len(tokens) - idx
        return False, f"FORMAT_INVALID: extra tokens at end ({extra} extra)", None

    return True, "ok", Parsed(n=n, m=m, edges=edges, forb=forb)


def check_constraints(parsed: Parsed) -> Tuple[bool, str]:
    n, m = parsed.n, parsed.m

    # Constraints are from standard CF 229B:
    # 2 <= n <= 2e5, 0 <= m <= 2e5, sum k <= 2e5
    # w positive, times nonnegative, times increasing.
    if not (2 <= n <= 200000):
        return False, f"SPEC_INVALID: n out of bounds (2..200000), got {n}"
    if not (0 <= m <= 200000):
        return False, f"SPEC_INVALID: m out of bounds (0..200000), got {m}"
    if len(parsed.edges) != m:
        return False, "SPEC_INVALID: edge count mismatch"

    for i, (u, v, w) in enumerate(parsed.edges):
        if not (1 <= u <= n):
            return False, f"SPEC_INVALID: edge[{i}].u out of range 1..n, got {u}"
        if not (1 <= v <= n):
            return False, f"SPEC_INVALID: edge[{i}].v out of range 1..n, got {v}"
        if u == v:
            return False, f"SPEC_INVALID: edge[{i}] is a self-loop at node {u}"
        if not (1 <= w <= 10**9):
            return False, f"SPEC_INVALID: edge[{i}].w out of bounds (1..1e9), got {w}"

    if len(parsed.forb) != n + 1:
        return False, "SPEC_INVALID: forbidden-times list size mismatch"

    total_k = 0
    for i in range(1, n + 1):
        times = parsed.forb[i]
        k = len(times)
        total_k += k
        if total_k > 200000:
            return False, "SPEC_INVALID: total number of forbidden times exceeds 200000"
        # per-planet k bound implied by total; still enforce nonnegative and reasonable token counts
        if k < 0:
            return False, f"SPEC_INVALID: planet[{i}].k negative"
        prev = None
        for j, t in enumerate(times):
            if not (0 <= t <= 10**9):
                return False, f"SPEC_INVALID: planet[{i}].t[{j}] out of bounds (0..1e9), got {t}"
            if prev is not None and t <= prev:
                return False, f"SPEC_INVALID: planet[{i}] forbidden times not strictly increasing"
            prev = t

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, msg, parsed = parse_format(input_str)
    if not ok:
        return False, msg
    assert parsed is not None
    ok2, msg2 = check_constraints(parsed)
    if not ok2:
        return False, msg2
    return True, "ok"

