import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        n = int(next(it))
    except StopIteration:
        return
    m = int(next(it))
    grid = [list(next(it).strip()) for _ in range(n)]

    # Build prefix sum of occupied cells ('X')
    ps = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n):
        row_ps = ps[i + 1]
        prev_ps = ps[i]
        s = 0
        for j in range(m):
            s += 1 if grid[i][j] == 'X' else 0
            row_ps[j + 1] = prev_ps[j + 1] + s

    def rect_sum(r1, c1, r2, c2):
        # inclusive r1..r2, c1..c2
        return ps[r2 + 1][c2 + 1] - ps[r1][c2 + 1] - ps[r2 + 1][c1] + ps[r1][c1]

    best = 0

    # For each pair of rows, treat each column as "good" if all cells between rows are free.
    # Then find longest contiguous segment of good columns -> maximal width.
    for top in range(n):
        good = [1] * m  # whether column is free for current [top..bottom]
        for bottom in range(top, n):
            height = bottom - top + 1
            for col in range(m):
                if good[col]:
                    # check the newly added cell at (bottom, col)
                    if grid[bottom][col] == 'X':
                        good[col] = 0

            # find maximum width of consecutive 1s in good
            maxw = 0
            cur = 0
            for v in good:
                if v:
                    cur += 1
                    if cur > maxw:
                        maxw = cur
                else:
                    cur = 0

            if maxw > 0:
                per = 2 * (height + maxw)
                if per > best:
                    best = per

    print(best)

if __name__ == "__main__":
    solve()

