import sys

def count_undoubtedly_lucky(n: int) -> int:
    s = str(n)
    L = len(s)
    ans = 0

    # Single-digit numbers: for any digit d, choose x=y=d.
    ans += min(n, 9)

    # For length >= 2, count numbers consisting of exactly two distinct digits {a,b}
    # (a < b), with no leading zeros, and value <= n.
    for a in range(10):
        for b in range(a + 1, 10):
            for length in range(2, L + 1):
                if length < L:
                    # Count all valid strings of this length over {a,b} with first digit != 0.
                    if a == 0:
                        # first digit must be b, remaining (length-1) are free
                        ans += 1 << (length - 1)
                    else:
                        # first digit can be a or b, remaining are free
                        ans += 1 << length
                else:
                    # length == L: count those <= n using digit-DP over the two digits
                    digits = [int(c) for c in s]
                    dp_tight = 1  # number of ways so far that match prefix of n
                    dp_loose = 0  # number of ways so far that are already smaller
                    for i, nd in enumerate(digits):
                        new_tight = 0
                        new_loose = 0
                        for d in (a, b):
                            if i == 0 and d == 0:
                                continue  # no leading zeros
                            if d < nd:
                                new_loose += dp_tight
                            elif d == nd:
                                new_tight += dp_tight
                            else:
                                # d > nd cannot come from tight
                                pass
                            # from loose, any digit stays loose
                            new_loose += dp_loose
                        dp_tight, dp_loose = new_tight, new_loose
                    ans += dp_tight + dp_loose

    return ans

