def factor_distinct_primes(x: int):
    """Return list of distinct prime factors of x (x>=1)."""
    res = []
    if x % 2 == 0:
        res.append(2)
        while x % 2 == 0:
            x //= 2
    p = 3
    while p * p <= x:
        if x % p == 0:
            res.append(p)
            while x % p == 0:
                x //= p
        p += 2
    if x > 1:
        res.append(x)
