            return None
    else:
        whole, frac = tok, ""

    whole_val = int(whole) if whole else 0
    frac_val = int(frac) if frac else 0
    frac_val *= 10 ** (6 - len(frac))

    return sign * (whole_val * 1_000_000 + frac_val)


