    while lines and lines[0].strip() == "":
        lines.pop(0)
    while lines and lines[-1].strip() == "":
        lines.pop()
    if not lines:
        return False, "FORMAT_INVALID: empty input", None

    idx = 0

    # Line 1: n
    if idx >= len(lines):
        return False, "FORMAT_INVALID: missing n line", None
    t = lines[idx].strip().split()
    if len(t) != 1:
        return False, "FORMAT_INVALID: line 1 must contain exactly one integer n", None
    if not _is_int_token(t[0]):
        return False, "FORMAT_INVALID: n is not an integer", None
    n = int(t[0])
