    # Statement shows one line; enforce exactly one line with n integers for strictness.
    if idx >= len(lines):
        return False, "FORMAT_INVALID: missing a_i line", None
    t = lines[idx].strip().split()
    if len(t) != n:
        return False, f"FORMAT_INVALID: a_i line must contain exactly n={n} integers", None
    a: List[int] = []
    for j, tok in enumerate(t):
        if not _is_int_token(tok):
            return False, f"FORMAT_INVALID: a[{j+1}] is not an integer", None
        a.append(int(tok))
    idx += 1

    # Line 3: m
    if idx >= len(lines):
        return False, "FORMAT_INVALID: missing m line", None
    t = lines[idx].strip().split()
    if len(t) != 1:
        return False, "FORMAT_INVALID: m line must contain exactly one integer", None
    if not _is_int_token(t[0]):
        return False, "FORMAT_INVALID: m is not an integer", None
    m = int(t[0])
    idx += 1

    # Next m lines: shots
