import sys

MOD = 1000000007

def is_good_number(x: int, a: int, b: int) -> bool:
    # positive integer in statement, but sum can be 0 only if n=0 (not possible here)
    while x > 0:
        d = x % 10
        if d != a and d != b:
            return False
        x //= 10
    return True

def modinv(x: int) -> int:
    return pow(x, MOD - 2, MOD)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, b, n = map(int, data)

    # Precompute factorials up to n for combinations
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (n + 1)
    invfact[n] = modinv(fact[n])
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def nCk(N, K):
        if K < 0 or K > N:
            return 0
        return fact[N] * invfact[K] % MOD * invfact[N - K] % MOD

    ans = 0
    # Numbers of length n consisting of digits a/b: choose count of a's = i, b's = n-i
    # Sum of digits = i*a + (n-i)*b
    for i in range(n + 1):
        s = i * a + (n - i) * b
        if is_good_number(s, a, b):
            ans = (ans + nCk(n, i)) % MOD

    sys.stdout.write(str(ans))

