import sys

def is_leap(y: int) -> bool:
    return (y % 400 == 0) or (y % 4 == 0 and y % 100 != 0)

def days_before_year(y: int) -> int:
    # Days in years [1 .. y-1] in Gregorian calendar
    y1 = y - 1
    return 365 * y1 + y1 // 4 - y1 // 100 + y1 // 400

def days_before_month(y: int, m: int) -> int:
    # Days in months [1 .. m-1] within year y
    mdays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if is_leap(y):
        mdays[1] = 29
    return sum(mdays[:m-1])

def day_number(y: int, m: int, d: int) -> int:
    # Absolute day index starting from 1/1/1 as day 1
    return days_before_year(y) + days_before_month(y, m) + d

