    # Accept both "yyyy mm dd" and "dd mm yyyy" by trying to detect.
    # Codeforces 304B uses year-month-day format in tests; we still add robustness.
    a, b, c = map(int, tokens)
    # Heuristic: if first is clearly a year (>= 1000) use y m d
    if a >= 1000:
        return a, b, c
    # else if last looks like a year, use d m y
    if c >= 1000:
        return c, b, a
    # fallback to y m d
    return a, b, c

