def min_steps_to_zero(n: int) -> int:
    if n == 0:
        return 0

    dist = {n: 0}
    q = deque([n])

    while q:
        x = q.popleft()
        d = dist[x]
        if x == 0:
            return d

        # Digits that occur in x; subtract one of them (if non-zero).
        y = x
        digits = set()
        while y > 0:
            digits.add(y % 10)
            y //= 10

