from collections import deque

def min_steps_to_zero(n: int) -> int:
    # BFS on numbers 0..n, edges: x -> x - d for any digit d in x (d>0)
    dist = [-1] * (n + 1)
    dist[n] = 0
    q = deque([n])

    while q:
        x = q.popleft()
        if x == 0:
            return dist[0]

        # extract digits of x
        t = x
        used = set()
        while t > 0:
            d = t % 10
            t //= 10
            if d != 0:
                used.add(d)

        for d in used:
            y = x - d
            if dist[y] == -1:
                dist[y] = dist[x] + 1
                q.append(y)

    return dist[0]

