# - special constraints: reject empty strings; reject extra non-whitespace tokens beyond n rule lines

LOWER_RE = re.compile(r"^[a-z]+$")
INT_RE = re.compile(r"^[+-]?\d+$")


def parse_format(input_str: str) -> Tuple[bool, Any]:
