            return False, f"FORMAT_INVALID: rule line {i+1} is empty"
        parts = rl.split()
        if len(parts) != 3:
            return False, f"FORMAT_INVALID: rule line {i+1} must have exactly 3 tokens"
        a, b, w_str = parts
