            return False, f"FORMAT_INVALID: rule line {i+1} first two tokens must be single characters"
        if not ("a" <= a <= "z") or not ("a" <= b <= "z"):
            return False, f"FORMAT_INVALID: rule line {i+1} characters must be lowercase Latin letters"
        if not INT_RE.fullmatch(w_str):
            return False, f"FORMAT_INVALID: rule line {i+1} third token must be an integer weight"
        try:
            w = int(w_str)
        except Exception:
            return False, f"FORMAT_INVALID: rule line {i+1} cannot parse weight as integer"
        rules.append((a, b, w))

    # Any extra lines beyond n must be whitespace-only (typically just trailing newlines).
    for j in range(n, len(remaining)):
        if remaining[j].strip() != "":
            return False, f"FORMAT_INVALID: extra non-empty line after {n} rule lines"

