import sys

def digits(n: int) -> int:
    return len(str(n))

def cost_len(m: int, k: int, length: int) -> int:
    """Total cost to take numbers m, m+1, ..., m+length-1."""
    if length <= 0:
        return 0
    start = m
    end = m + length - 1
    res = 0

    d = digits(start)
    while True:
        # last number with d digits
        lim = 10**d - 1
        r = min(end, lim)
        cnt = r - start + 1
        res += cnt * d * k
        if r == end:
            break
        start = r + 1
        d += 1
    return res

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    w, m, k = map(int, data)

    # Upper bound for length: cannot exceed w // (digits(m) * k) roughly,
    # but use doubling to be safe.
    lo, hi = 0, 1
    while cost_len(m, k, hi) <= w:
        hi *= 2

    # Binary search maximum feasible length
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if cost_len(m, k, mid) <= w:
            lo = mid
        else:
            hi = mid

    sys.stdout.write(str(lo))

if __name__ == "__main__":
    solve()

