import sys
import math

def solve():
    data = list(map(int, sys.stdin.read().strip().split()))
    if len(data) != 6:
        return
    n, m, i, j, a, b = data

    # If you can't move at all
    if a == 0 and b == 0:
        # already at a corner?
        if (i, j) in [(1, 1), (1, m), (n, 1), (n, m)]:
            print(0)
        else:
            print(-1)
        return

    corners = [(1, 1), (1, m), (n, 1), (n, m)]

    def min_steps_to_corner(x2, y2):
        dx = abs(i - x2)
        dy = abs(j - y2)

        # Need to satisfy parity / divisibility constraints:
        # x changes by +/- a each move => dx must be multiple of a (unless a==0)
        # y changes by +/- b each move => dy must be multiple of b (unless b==0)
        if a == 0:
            if dx != 0:
                return None
            kx = 0
        else:
            if dx % a != 0:
                return None
            kx = dx // a

        if b == 0:
            if dy != 0:
                return None
            ky = 0
        else:
            if dy % b != 0:
                return None
            ky = dy // b

        # In each move, both coordinates change (by +/-a and +/-b),
        # so the number of moves k must be the same for x and y.
        if kx != ky:
            return None
        return kx

    best = None
    for x2, y2 in corners:
        k = min_steps_to_corner(x2, y2)
        if k is not None:
            if best is None or k < best:
                best = k

    print(-1 if best is None else best)

if __name__ == "__main__":
    solve()

