import sys
import math

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    if n % 3 == 0:
        return n == 3
    r = int(math.isqrt(n))
    f = 5
    step = 2
    while f <= r:
        if n % f == 0:
            return False
        f += step
        step = 6 - step
    return True

def prev_prime(n: int) -> int:
    x = n
    while x >= 2 and not is_prime(x):
        x -= 1
    return x  # for n>=2, always returns a prime

def next_prime(n: int) -> int:
    x = n + 1
    while not is_prime(x):
        x += 1
    return x

