        v = 2
        u = 3
    else:
        v = prev_prime(n)
        u = next_prime(n)

    num = v + u
    den = v * u
    g = math.gcd(num, den)
    num //= g
    den //= g
    sys.stdout.write(f"{num}/{den}")

