def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 396B - On Sum of Fractions.

    The original CF task input is a single integer n.

    We accept:
      - optional leading/trailing whitespace
      - one integer token
      - newline(s) around it

    We reject:
      - empty input
      - extra tokens / non-integer tokens
      - numbers outside typical CF constraints (conservatively enforced)

    Returns: (ok, reason)
      - ok=True  => ("OK")
      - ok=False => reason starts with FORMAT_INVALID or SPEC_INVALID
