    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    s = inp.strip()
    if not s:
        return (False, "FORMAT_INVALID: empty input")

    # Split on any whitespace; CF inputs are whitespace-separated tokens.
    tokens = s.split()
    if len(tokens) != 1:
        return (False, "FORMAT_INVALID: expected exactly one integer token")

    tok = tokens[0]
    if not re.fullmatch(r"[+-]?\d+", tok):
        return (False, "FORMAT_INVALID: token is not a valid integer")

    try:
        n = int(tok)
    except Exception:
        return (False, "FORMAT_INVALID: cannot parse integer")

    # Spec/CF constraints: the problem uses primes around n; n is positive.
    # CF 396B typically has n up to around 1e7 (common for sieve-based tasks),
    # but constraints can vary; we'll enforce a safe, conventional range.
    if n <= 0:
        return (False, "SPEC_INVALID: n must be positive")

    # Conservative upper bound to avoid absurd inputs; adjust if you know exact bound.
    # This is not about solution feasibility but about staying within typical CF spec.
    if n > 10**7:
        return (False, "SPEC_INVALID: n exceeds 1e7 (typical constraint)")

    return (True, "OK")

