        return (False, "FORMAT_INVALID: input is None")

    # Keep line structure; allow trailing newlines/spaces overall.
    raw = inp
    lines = raw.splitlines()

    # Remove leading/trailing completely-empty lines
    while lines and lines[0].strip() == "":
        lines.pop(0)
    while lines and lines[-1].strip() == "":
        lines.pop()

    if not lines:
        return (False, "FORMAT_INVALID: empty input")

    # Parse first line: two integers
    first = lines[0].strip()
    parts = first.split()
    if len(parts) != 2:
        return (False, "FORMAT_INVALID: first line must contain exactly two integers n m")
    try:
        n = int(parts[0])
        m = int(parts[1])
    except ValueError:
        return (False, "FORMAT_INVALID: n and m must be integers")

    if n <= 0 or m <= 0:
        return (False, "SPEC_INVALID: n and m must be positive")
    if n > 100 or m > 100:
        return (False, "SPEC_INVALID: n and m must be <= 100")

    if len(lines) != 1 + n:
        return (False, f"FORMAT_INVALID: expected {n} grid lines, found {len(lines)-1}")

    allowed = {'.', 'G', 'S'}

    for i in range(n):
        row = lines[1 + i]
        # Do not allow leading/trailing spaces in grid lines (common CF format requirement)
        if row.strip() != row:
            return (False, f"FORMAT_INVALID: row {i+1} has leading/trailing whitespace")
        if len(row) != m:
            return (False, f"FORMAT_INVALID: row {i+1} length {len(row)} != m ({m})")
        if any(ch not in allowed for ch in row):
            return (False, f"FORMAT_INVALID: row {i+1} contains invalid characters")

        g_count = row.count('G')
        s_count = row.count('S')
        if g_count != 1 or s_count != 1:
            return (False, f"SPEC_INVALID: row {i+1} must contain exactly one 'G' and one 'S'")

        g_pos = row.index('G')
        s_pos = row.index('S')
        if g_pos > s_pos:
            return (False, f"SPEC_INVALID: row {i+1} has 'G' to the right of 'S' (unsolvable)")

    return (True, "OK")

