MIN_VALUE = 1
MAX_VALUE = 1_000_000


def _parse_small_int_token(tok: str) -> int:
    """
    Parse an already format-validated ASCII integer token.

    Avoids converting arbitrarily long strings with int(), while still handling
    leading zeroes correctly.
    """
    sign = -1 if tok.startswith("-") else 1
    if tok[0] in "+-":
        digits = tok[1:]
    else:
        digits = tok

    significant = digits.lstrip("0") or "0"

    # The validator only needs values up to MAX_VALUE and below MIN_VALUE.
    # If a positive number has more significant digits than MAX_VALUE, it is
    # certainly too large; if a negative number is non-zero, it is too small.
    if sign < 0:
        if significant == "0":
            return 0
        return MIN_VALUE - 1

    max_s = str(MAX_VALUE)
    if len(significant) > len(max_s):
        return MAX_VALUE + 1
    if len(significant) == len(max_s) and significant > max_s:
        return MAX_VALUE + 1

    return int(significant)


def validate_input(inp: str) -> Tuple[bool, str]:
