import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    n, q = map(int, input().split())
    grid = [list(input().strip()) for _ in range(2)]

    # bad[i] indicates there is at least one blocking pair between columns i and i+1
    # Specifically, if any of the 4 pairs (r,c=i) adjacent to (1-r, c=i+1) or (1-r, c=i)
    # But in 2-row case, an obstacle at (r, i) conflicts with obstacle at (1-r, i-1/i/i+1) (only side adjacency across rows)
    # Standard approach: count conflicts between rows across neighboring columns.
    bad = [0] * n
    total_bad = 0

    def add_bad(col, delta):
        nonlocal total_bad
        if 0 <= col < n:
            was = bad[col]
            bad[col] += delta
            if was == 0 and bad[col] > 0:
                total_bad += 1
            elif was > 0 and bad[col] == 0:
                total_bad -= 1

    # Initialize conflicts
    # For each obstacle at (r, c), check (1-r, c-1), (1-r, c), (1-r, c+1)
    # Each such conflict contributes to a specific "boundary" position c' where we store it as bad[c']
    # Common implementation stores per column boundary between i and i+1; but easiest is store by column index of left cell in pair:
    # For conflict between (r, c) and (1-r, c+dc):
    # if dc in {-1,0,1}, the pair blocks passing through around columns min(c, c+dc).
    # We'll just count each pair into bad[min(c, c+dc)].
    def conflict_index(c1, c2):
        return min(c1, c2)

    for r in range(2):
        for c in range(n):
            if grid[r][c] == '#':
                orow = 1 - r
                for dc in (-1, 0, 1):
                    cc = c + dc
                    if 0 <= cc < n and grid[orow][cc] == '#':
                        add_bad(conflict_index(c, cc), 1)

    def toggle(r, c):
        # Remove old conflicts if currently obstacle, otherwise will add after toggling
        nonlocal grid
        orow = 1 - r
        if grid[r][c] == '#':
            for dc in (-1, 0, 1):
                cc = c + dc
                if 0 <= cc < n and grid[orow][cc] == '#':
                    add_bad(conflict_index(c, cc), -1)
            grid[r][c] = '.'
        else:
            for dc in (-1, 0, 1):
                cc = c + dc
                if 0 <= cc < n and grid[orow][cc] == '#':
                    add_bad(conflict_index(c, cc), 1)
            grid[r][c] = '#'

    out = []
    for _ in range(q):
        r, c = map(int, input().split())
        r -= 1
        c -= 1
        toggle(r, c)
        out.append("Yes" if total_bad == 0 else "No")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

