from typing import Tuple

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 413E (Maze 2D).

    Expected format (as in the original CF problem):
      n m
      <n lines of length m consisting of '.' and '#'>
      q
      x1 y1 x2 y2   (q lines, 1-based coordinates)

    Common constraints from the problem:
      2 <= n, m <= 2000
      1 <= q <= 200000
      Queries are within bounds; start and end cells must be free ('.').

    Returns:
      (True, "OK") on acceptance
      (False, "<PREFIX>: ...") on rejection, where PREFIX is FORMAT_INVALID or SPEC_INVALID.
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    # Preserve lines; allow trailing whitespace/newlines
    lines = inp.splitlines()
    # Allow leading empty lines? CF inputs don't have them; treat leading empties as format invalid.
    if lines and lines[0].strip() == "":
        return False, "FORMAT_INVALID: leading empty line"

    idx = 0

    def fail(prefix: str, msg: str) -> Tuple[bool, str]:
        return False, f"{prefix}: {msg}"

    def need_line() -> str:
        nonlocal idx
        if idx >= len(lines):
            raise IndexError
        s = lines[idx]
        idx += 1
        return s

    # Parse n m
    try:
        first = need_line().strip()
    except IndexError:
        return fail("FORMAT_INVALID", "missing 'n m' line")

    parts = first.split()
    if len(parts) != 2:
        return fail("FORMAT_INVALID", "first line must contain exactly two integers: n m")
    if not all(re.fullmatch(r"[+-]?\d+", p) for p in parts):
        return fail("FORMAT_INVALID", "n and m must be integers")

    n = int(parts[0])
    m = int(parts[1])

    # Spec checks for n, m (based on problem; treat out-of-range as SPEC_INVALID)
    if n < 2 or m < 2:
        return fail("SPEC_INVALID", "n and m must be >= 2")
    # Known CF constraints: up to 2000
    if n > 2000 or m > 2000:
        return fail("SPEC_INVALID", "n and m exceed maximum allowed (2000)")

    # Read grid
    grid = []
    for r in range(n):
        if idx >= len(lines):
            return fail("FORMAT_INVALID", f"missing grid row {r+1} of {n}")
        row = lines[idx].rstrip("\n")
        idx += 1

        # Row should be exactly length m, consisting only of '.' and '#'
        # (Do not strip spaces; spaces would change length -> format invalid)
        if len(row) != m:
            return fail("FORMAT_INVALID", f"grid row {r+1} length is {len(row)} but expected {m}")
        if any(c not in ".#" for c in row):
            return fail("FORMAT_INVALID", f"grid row {r+1} contains invalid characters (allowed: '.' '#')")
        grid.append(row)

