def inside(x, y):
    return 0 <= x < 8 and 0 <= y < 8

def rook_attacks(rx, ry, tx, ty, occ):
    if rx == tx:
        step = 1 if ty > ry else -1
        y = ry + step
        while y != ty:
            if (rx, y) in occ:
                return False
            y += step
        return True
    if ry == ty:
        step = 1 if tx > rx else -1
        x = rx + step
        while x != tx:
            if (x, ry) in occ:
                return False
            x += step
        return True
    return False

def square_attacked_by_white(x, y, wk, r1, r2, occ):
    wx, wy = wk
    if max(abs(wx - x), abs(wy - y)) == 1:
        return True
    for rx, ry in (r1, r2):
        if rook_attacks(rx, ry, x, y, occ):
            return True
    return False

