    lines = data.split("\n")
    while lines and lines[-1] == "":
        lines.pop()

    if len(lines) != 2:
        return (False, f"FORMAT_INVALID: expected exactly 2 non-empty lines (s, k), got {len(lines)}")

    s = lines[0]
    k_str = lines[1].strip()

