        return

    # incL[i]: length of strictly increasing contiguous segment ending at i
    incL = [1] * n
    for i in range(1, n):
        if a[i] > a[i - 1]:
            incL[i] = incL[i - 1] + 1

    # incR[i]: length of strictly increasing contiguous segment starting at i
    incR = [1] * n
    for i in range(n - 2, -1, -1):
        if a[i] < a[i + 1]:
            incR[i] = incR[i + 1] + 1

    ans = 1
    # Change one element at position i (or none), best segment around it:
    for i in range(n):
        best_left = incL[i - 1] if i - 1 >= 0 else 0
        best_right = incR[i + 1] if i + 1 < n else 0

        # By changing a[i], we can always connect left and right unless
        # the gap between a[i-1] and a[i+1] is too small.
        cur = 1 + best_left + best_right
