            return None, f"FORMAT_INVALID: {name} is not a valid integer"
        # Valid values are small; this prevents pathological huge integer strings.
        digits = tok[1:] if tok.startswith("-") else tok
        if len(digits) > 30:
            return None, f"SPEC_INVALID: {name} is outside allowed range"
        return int(tok), None

    if len(tokens) < 2:
        return False, "FORMAT_INVALID: expected at least two integers n and s"

    n, err = parse_int(tokens[0], "n")
    if err:
        return False, err

    s, err = parse_int(tokens[1], "s")
    if err:
        return False, err

    if not (1 <= n <= 20):
        return False, "SPEC_INVALID: n must satisfy 1 <= n <= 20"

    if not (0 <= s <= 10**14):
        return False, "SPEC_INVALID: s must satisfy 0 <= s <= 10^14"

    expected = 2 + n
    if len(tokens) != expected:
        return False, (
            f"FORMAT_INVALID: expected exactly {expected} integers, "
            f"got {len(tokens)}"
        )

    for i in range(n):
