import sys

def compare_golden(a: str, b: str) -> int:
    # Trim leading zeros: they don't affect value.
    a = a.lstrip('0')
    b = b.lstrip('0')
    if not a:
        a = "0"
    if not b:
        b = "0"

    # Handle zero quickly
    if a == "0" and b == "0":
        return 0
    if a == "0":
        return -1
    if b == "0":
        return 1

    # Let q = (1+sqrt(5))/2. Value of bitstring s is sum s[i]*q^(n-1-i).
    # Key fact: for q>1, the dominant term is the highest power.
    # For two strings, compare by length first; longer length means higher max power.
    if len(a) != len(b):
        return 1 if len(a) > len(b) else -1

    # Same length: compare lexicographically because weights decrease monotonically,
    # and digits are 0/1. The first differing digit decides.
    if a == b:
        return 0
    return 1 if a > b else -1


