    a = data[3:3 + n]

    lo = min(a)
    hi = lo + m + 1  # exclusive upper bound

    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if can_make(mid, a, n, m, w):
            lo = mid
        else:
            hi = mid

    sys.stdout.write(str(lo))


