def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    perms = []
    for _ in range(k):
        perms.append([int(next(it)) for _ in range(n)])

    # Position arrays: pos[j][value] = index in permutation j (0-based)
    pos = [[0] * (n + 1) for _ in range(k)]
    for j in range(k):
        for idx, val in enumerate(perms[j]):
            pos[j][val] = idx

    base = perms[0]  # We will compute LIS-like DP over this order
    dp = [0] * (n + 1)  # dp[val] = best length ending at value val in base order

    # For each element in base order, consider previous elements in base order.
    # Transition allowed if element order is increasing in all permutations.
    for i in range(n):
        x = base[i]
        best = 1
        for j in range(i):
            y = base[j]
            ok = True
            for t in range(1, k):
                if pos[t][y] >= pos[t][x]:
                    ok = False
                    break
            if ok:
                cand = dp[y] + 1
                if cand > best:
                    best = cand
        dp[x] = best

    ans = max(dp)
    sys.stdout.write(str(ans))


