import sys
from collections import deque

INF = 10**15

class SegTree:
    def __init__(self, n):
        self.n = 1
        while self.n < n:
            self.n <<= 1
        self.seg = [INF] * (2 * self.n)

    def build(self, arr):
        # arr length <= n
        for i, v in enumerate(arr):
            self.seg[self.n + i] = v
        for i in range(self.n - 1, 0, -1):
            self.seg[i] = self.seg[i << 1] if self.seg[i << 1] < self.seg[i << 1 | 1] else self.seg[i << 1 | 1]

    def update(self, idx, val):
        i = self.n + idx
        self.seg[i] = val
        i >>= 1
        while i:
            left = self.seg[i << 1]
            right = self.seg[i << 1 | 1]
            self.seg[i] = left if left < right else right
            i >>= 1

    def query(self, l, r):
        # inclusive
        if l > r:
            return INF
        l += self.n
        r += self.n
        res = INF
        while l <= r:
            if (l & 1) == 1:
                if self.seg[l] < res:
                    res = self.seg[l]
                l += 1
            if (r & 1) == 0:
                if self.seg[r] < res:
                    res = self.seg[r]
                r -= 1
            l >>= 1
            r >>= 1
        return res

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    s = int(next(it))
    l = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    # Two monotonic deques for sliding window [left..right]
    maxdq = deque()
    mindq = deque()
    left = 0

    # dp[i] = minimal pieces to cover first i elements (i from 0..n)
    dp = [INF] * (n + 1)
    dp[0] = 0

    st = SegTree(n + 1)
    st.build(dp)

    # We'll query dp[j] for j in [left, i-l] to form piece (j..i-1)
    for right in range(n):
        x = a[right]
        while maxdq and a[maxdq[-1]] <= x:
            maxdq.pop()
        maxdq.append(right)
        while mindq and a[mindq[-1]] >= x:
            mindq.pop()
        mindq.append(right)

        # shrink left until condition holds
        while maxdq and mindq and a[maxdq[0]] - a[mindq[0]] > s:
            if maxdq[0] == left:
                maxdq.popleft()
            if mindq[0] == left:
                mindq.popleft()
            left += 1

        i = right + 1  # dp index after including right
        if i >= l:
            lo = left
            hi = i - l
            best = st.query(lo, hi)
            if best < INF:
                dp[i] = best + 1
            else:
                dp[i] = INF
        # update segment tree at position i
        st.update(i, dp[i])

    ans = dp[n]
    if ans >= INF:
        print(-1)
    else:
