import sys

def construct_largest(m, s):
    digits = []
    for _ in range(m):
        d = min(9, s)
        digits.append(str(d))
        s -= d
    return ''.join(digits)

def construct_smallest(m, s):
    # Build from most significant to least with greedy minimal digit
    # ensuring remaining sum fits in remaining positions.
    digits = []
    for i in range(m):
        remaining_positions = m - i - 1
        # Minimum digit at this position
        start = 0
        if i == 0 and m > 1:
            start = 1  # no leading zero for multi-digit numbers
        for d in range(start, 10):
            rem = s - d
            if 0 <= rem <= 9 * remaining_positions:
                digits.append(str(d))
                s = rem
                break
        else:
            return None
    return ''.join(digits)

