        return False, "FORMAT_INVALID: input is None", None
    if input_str.strip() == "":
        return False, "FORMAT_INVALID: empty input", None

    # Token-based parsing to be robust to line wrapping while still enforcing exact token count.
    toks = input_str.split()
    if len(toks) < 3:
        return False, "FORMAT_INVALID: expected at least 3 integers (n m k)", None
    if not (_is_int_token(toks[0]) and _is_int_token(toks[1]) and _is_int_token(toks[2])):
        return False, "FORMAT_INVALID: first three tokens must be integers (n m k)", None

    n, m, k = int(toks[0]), int(toks[1]), int(toks[2])

    if len(toks) != 3 + 2 * k:
        return (
            False,
            f"FORMAT_INVALID: expected exactly {3 + 2 * k} tokens total (3 header + 2*k), got {len(toks)}",
            None,
        )

    moves: List[Tuple[int, int]] = []
    idx = 3
    for t in range(1, k + 1):
        a, b = toks[idx], toks[idx + 1]
        if not (_is_int_token(a) and _is_int_token(b)):
            return False, f"FORMAT_INVALID: move {t} must contain 2 integers (i j)", None
        moves.append((int(a), int(b)))
        idx += 2

    return True, "ok", Parsed(n=n, m=m, k=k, moves=moves)


