    parent = [[(-1, -1)] * m for _ in range(n)]

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(sr, sc):
        stack = [(sr, sc, 0)]  # (r, c, next_dir_index)
        visited[sr][sc] = True
        parent[sr][sc] = (-1, -1)
        color = grid[sr][sc]

