class FormatError(Exception):
    pass


class SpecError(Exception):
    pass


def parse_format(input_str: str) -> Dict[str, Any]:
    if input_str is None:
        raise FormatError("input is None")

    # Preserve line structure; allow trailing newline but no extra non-empty lines beyond expected.
    lines = input_str.splitlines()
    if len(lines) == 0:
        raise FormatError("empty input")

    # First line: n m
    first = lines[0].strip()
    if first == "":
        raise FormatError("first line is empty")
    parts = first.split()
    if len(parts) != 2:
        raise FormatError(f"first line must contain exactly 2 integers, got {len(parts)} tokens")
    try:
        n = int(parts[0])
        m = int(parts[1])
    except ValueError:
        raise FormatError("n and m must be integers")

    # Expect exactly n additional lines for grid. No extra non-empty lines afterward.
    if len(lines) < 1 + n:
        raise FormatError(f"expected {n} grid lines, got {max(0, len(lines) - 1)}")
    if len(lines) > 1 + n:
        # If extra lines exist, they must all be empty/whitespace
        extra = lines[1 + n :]
        for idx, ln in enumerate(extra, start=1 + n + 1):
            if ln.strip() != "":
                raise FormatError(f"extra non-empty line at line {idx}")
