        if row_raw.strip() == "" and m != 0:
            # m is never 0 per constraints, but keep format strict
            raise FormatError(f"grid row {i+1} is empty")
        # Do not strip spaces inside; spaces are not allowed in row.
        if row_raw.strip() != row_raw:
            # leading/trailing spaces would change length/meaning; treat as format error
