# - exact line/token structure: 1 line with n, then exactly 3 lines with lengths n, n-1, n-2 (space-separated integers), no extra tokens/lines
# - numeric bounds: n in [2, 1e5]; all error codes are positive integers (>=1)
# - array/string lengths: exactly n, n-1, n-2 integers on the respective lines
# - graph constraints: none
# - special constraints: second list must be obtainable from first by deleting exactly one element; third from second by deleting exactly one element (multiset containment)


def parse_format(input_str: str) -> Tuple[bool, Any]:
