        return False, "FORMAT_INVALID: blank/empty line detected"
    if len(lines) != 4:
        return False, f"FORMAT_INVALID: expected exactly 4 lines, got {len(lines)}"

    def parse_int_token(tok: str) -> Tuple[bool, int]:
