    ok2, a2 = parse_int_list(a2_toks, 3)
    if not ok2:
        return False, a2
    ok3, a3 = parse_int_list(a3_toks, 4)
    if not ok3:
        return False, a3

    parsed: Dict[str, Any] = {"n": n, "a1": a1, "a2": a2, "a3": a3}
    return True, parsed


