        return False, "SPEC_INVALID: second->third must remove exactly one error (multiset difference not 1)"

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, parsed_or_err = parse_format(input_str)
    if not ok:
