import sys

MOD = 10**9 + 7

def mod_pow(a, e, mod=MOD):
    res = 1
    while e:
        if e & 1:
            res = res * a % mod
        a = a * a % mod
        e >>= 1
    return res

def prepare_fact(n, mod=MOD):
    fact = [1] * (n + 1)
    invfact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % mod
    invfact[n] = mod_pow(fact[n], mod - 2, mod)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % mod
    return fact, invfact

def nCk(n, k, fact, invfact, mod=MOD):
    if k < 0 or k > n:
        return 0
    return fact[n] * invfact[k] % mod * invfact[n - k] % mod

def ways(a, b, fact, invfact):
    # number of paths from (1,1) to (a,b) with only down/right
    return nCk((a - 1) + (b - 1), a - 1, fact, invfact)

def ways_between(x1, y1, x2, y2, fact, invfact):
    # paths from (x1,y1) to (x2,y2) if x1<=x2, y1<=y2
    dx = x2 - x1
    dy = y2 - y1
    if dx < 0 or dy < 0:
        return 0
    return nCk(dx + dy, dx, fact, invfact)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    h = int(next(it))
    w = int(next(it))
    n = int(next(it))
    blocks = []
    for _ in range(n):
        r = int(next(it)); c = int(next(it))
        blocks.append((r, c))
    blocks.sort()
    # include destination as last "point"
    points = blocks + [(h, w)]

    # factorial size up to (h+w)
    fact, invfact = prepare_fact(h + w + 5)

    dp = [0] * len(points)
    for i, (r, c) in enumerate(points):
        total = ways(r, c, fact, invfact)
        # subtract paths that pass through any earlier blocked cell
        for j in range(i):
            br, bc = points[j]
            if br <= r and bc <= c:
                total -= dp[j] * ways_between(br, bc, r, c, fact, invfact)
                total %= MOD
        dp[i] = total % MOD

    # answer is ways to reach (h,w) avoiding all blocks
    print(dp[-1] % MOD)

if __name__ == "__main__":
    solve()

