def solve() -> None:
    input = sys.stdin.readline
    n = int(input().strip())
    arr = list(map(int, input().split()))
    if n == 0:
        print(0)
        return

    maxA = max(arr)
    freq = [0] * (maxA + 1)
    for x in arr:
        freq[x] += 1

    # dp[v] = maximum clique size in divisibility graph using numbers from A,
    # ending at value v (as the largest value in the chain), counting multiplicities.
    # A clique here corresponds to a chain under divisibility.
    dp = [0] * (maxA + 1)
    ans = 0

    for v in range(1, maxA + 1):
        if freq[v] == 0:
            continue
        best_prev = 0
        # consider all proper divisors d of v
        d = 1
        while d * d <= v:
            if v % d == 0:
                d1 = d
                d2 = v // d
                if d1 != v:
                    if dp[d1] > best_prev:
                        best_prev = dp[d1]
                if d2 != v and d2 != d1:
                    if dp[d2] > best_prev:
                        best_prev = dp[d2]
            d += 1

        dp[v] = best_prev + freq[v]
        if dp[v] > ans:
            ans = dp[v]

    print(ans)


