import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        n = int(next(it))
    except StopIteration:
        return

    inside = set()
    left_without_entry = set()  # people who "left" before any seen "enter"
    cur = 0
    ans = 0

    for _ in range(n):
        op = next(it)
        x = int(next(it))
        if op == '+':
            # If earlier we saw "- x" without a prior "+ x" in the log,
            # it means x was already inside at the start. Entering now cancels that.
            if x in left_without_entry:
                left_without_entry.remove(x)
            else:
                inside.add(x)
                cur += 1
                if cur > ans:
                    ans = cur
        else:  # '-'
            if x in inside:
                inside.remove(x)
                cur -= 1
            else:
                # Must have been inside at the start; count it in initial capacity.
                left_without_entry.add(x)

    # Initial visitors are those who left without being seen entering.
    # Capacity must accommodate them plus peak additional visitors.
    sys.stdout.write(str(ans + len(left_without_entry)))

