    a, b = map(float, data)

    eps = 1e-12

    # If b is outside possible y-range for x>0, impossible
    if b < -eps:
        print(-1)
        return

    # If b == 0, point lies on x-axis at multiples of 2x
    # Need x = a / (2k) for some integer k >= 1, and x > 0.
    if abs(b) <= eps:
        if a <= eps:
            # a == 0 implies any x works, but need minimal positive -> tends to 0, not allowed.
            # In the original CF problem, a and b are integers and a>0 for this case.
            print(-1)
            return
        # We need minimal positive x => choose largest possible k with integer constraint.
        # For real input, we'd have no discrete constraint; but problem uses integers.
        A = int(round(a))
        if abs(a - A) > 1e-9:
            print(-1)
            return
        best = None
        for d in range(1, int(math.isqrt(A)) + 1):
            if A % d == 0:
                for k in (d, A // d):
                    if k >= 1:
                        x = A / (2.0 * k)
                        if x > 0 and (best is None or x < best):
                            best = x
        if best is None:
            print(-1)
        else:
            # Print without trailing .0 when integer/half-integer doesn't matter; CF accepts float.
            print(best)
        return

    # Now b > 0
    if a <= eps:
        print(-1)
        return

    # Derivation:
    # In each segment, y = x - |t| where t = a - (2k+1)x for some integer k,
    # so b = x - |a - (2k+1)x| implies |a - (2k+1)x| = x - b, requiring x >= b.
    # Two possibilities:
    # (1) a - (2k+1)x =  x - b  => a + b = (2k+2)x => x = (a+b)/(2m), m=k+1 >=1
    # (2) a - (2k+1)x = -(x - b) => a - b = 2k x        => x = (a-b)/(2k), k>=0
    # Additionally, the point must lie within the corresponding segment:
    # For (1), a in [ (2k+1)x, (2k+2)x ] <=> a in [ (2m-1)x, 2m x ].
    # For (2), a in [ 2k x, (2k+1)x ].

    candidates = []

    # Candidate family (1): x = (a+b)/(2m), m>=1.
    # Condition a in [ (2m-1)x, 2m x ].
    # Using x formula:
    # Lower bound: a >= (2m-1)*(a+b)/(2m)  <=> 2m a >= (2m-1)(a+b)
    # Upper bound: a <= 2m*(a+b)/(2m) = a+b always true since b>0.
    # So only need 2m a >= (2m-1)(a+b) => a >= (2m-1) b.
    # Also x > 0 and x >= b is automatically satisfied if a >= (2m-1)b.
    A = int(round(a))
    B = int(round(b))
    if abs(a - A) < 1e-9 and abs(b - B) < 1e-9:
        # Use integer arithmetic for exact divisor enumeration.
        apb = A + B
