        m = int(math.floor((a / b + 1.0) / 2.0)) if b > 0 else 1
        m = max(1, m)
        x = (a + b) / (2.0 * m)
        if a + 1e-9 >= (2 * m - 1) * b:
            candidates.append(x)

    # Candidate family (2): x = (a-b)/(2k), k>=1 (k=0 only if a==b -> x arbitrary? but b>0 => not).
    # Condition a in [2k x, (2k+1)x] with x as above:
    # 2k x = a-b so lower bound always gives a >= a-b true.
    # Upper bound: a <= (2k+1)x = (2k+1)(a-b)/(2k) => equivalent to 2k a <= (2k+1)(a-b)
