    if t is None:
        return False, "FORMAT_INVALID: missing m", None
    ok, msg, m = parse_int(t, "m")
    if not ok:
        return False, msg, None

    if n is None or m is None:
        return False, "FORMAT_INVALID: internal parse error", None

