        cats.append(v)

    edges: List[Tuple[int, int]] = []
    for i in range(n - 1):
        t = next_token()
        if t is None:
            return False, f"FORMAT_INVALID: missing edge {i+1} endpoint u", None
        ok, msg, u = parse_int(t, f"edge[{i+1}].u")
        if not ok:
            return False, msg, None

        t = next_token()
        if t is None:
            return False, f"FORMAT_INVALID: missing edge {i+1} endpoint v", None
        ok, msg, v = parse_int(t, f"edge[{i+1}].v")
