    # Validate it's a tree (connected + n-1 edges is already, but still check connectivity)
    # Connectivity check via iterative DFS/BFS from node 1
    visited = [False] * (n + 1)
    stack = [1]
    visited[1] = True
    cnt = 0
    while stack:
