            # Send command: "<name>:<message>" (message may be empty, colon must exist)
            colon_pos = line.find(":")
            if colon_pos == -1:
                return False, f"FORMAT_INVALID: invalid command (no '+', '-', or ':') at line {idx}", None
            name = line[:colon_pos]
            msg = line[colon_pos + 1 :]
            if name == "":
                return False, f"FORMAT_INVALID: empty username in send command at line {idx}", None
            cmds.append(Cmd(kind="send", name=name, msg=msg))

    return True, "ok", cmds


def check_constraints(cmds: List[Cmd]) -> Tuple[bool, str]:
    # The original statement does not explicitly give bounds or character constraints.
    # However, for this classic CF problem, usernames are typically assumed to be identifiers without spaces
    # and messages are arbitrary (including spaces) after the colon. We enforce a conservative, commonly-accepted
    # constraint: usernames consist only of [A-Za-z0-9_], non-empty.
    # If a future asset includes other characters, it may conflict with this implied constraint.
    for i, c in enumerate(cmds, start=1):
        if c.name == "":
            return False, f"SPEC_INVALID: empty username at command {i}"
        if any(ch not in ALLOWED_NAME_CHARS for ch in c.name):
            return (
                False,
                f"SPEC_INVALID: username contains invalid character(s) at command {i}",
            )
        # message may be empty; no other explicit constraints.

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, reason, parsed = parse_format(input_str)
    if not ok:
        return False, reason
    assert parsed is not None
    ok2, reason2 = check_constraints(parsed)
    if not ok2:
        return False, reason2
    return True, "ok"

