def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validator for Codeforces 600B - Queries about less or equal elements.

    Expected format:
      n m
      a1 a2 ... an
      b1 b2 ... bm

    Constraints (per CF 600B):
      1 <= n, m <= 200000
      ai, bj are integers (typically within +/-1e9 on CF; we enforce 32-bit-ish safety)

    Returns:
      (True, "OK") if valid
      (False, "FORMAT_INVALID: ...") or (False, "SPEC_INVALID: ...")
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    toks = s.split()
    if len(toks) < 2:
        return False, "FORMAT_INVALID: expected at least two integers (n m)"

    def parse_int(tok: str, where: str) -> tuple[bool, int | None, str]:
        try:
            # Reject non-integer like "1.0"
            if any(c in tok for c in ".eE"):
                return False, None, f"FORMAT_INVALID: non-integer token {tok!r} at {where}"
            v = int(tok)
            return True, v, ""
        except Exception:
            return False, None, f"FORMAT_INVALID: cannot parse int token {tok!r} at {where}"

    ok, n, msg = parse_int(toks[0], "n")
    if not ok:
        return False, msg
    ok, m, msg = parse_int(toks[1], "m")
    if not ok:
        return False, msg

    if n is None or m is None:
        return False, "FORMAT_INVALID: failed to parse n or m"

    # Spec constraints (CF 600B)
    if n < 1 or m < 1:
        return False, "SPEC_INVALID: n and m must be >= 1"
    if n > 200_000 or m > 200_000:
        return False, "SPEC_INVALID: n and m must be <= 200000"

    expected = 2 + n + m
    if len(toks) != expected:
        return False, (
            "FORMAT_INVALID: wrong number of integers; "
            f"expected {expected} (2 + n + m) but got {len(toks)}"
        )

    # Parse arrays; also ensure values are within a reasonable integer range.
    # CF typically uses |ai|,|bi| <= 1e9; we enforce that (SPEC) to catch obvious junk.
    LIM = 10**9

    idx = 2
    for i in range(n):
        ok, v, msg = parse_int(toks[idx], f"a[{i}]")
        if not ok:
            return False, msg
        if v is None:
            return False, f"FORMAT_INVALID: missing a[{i}]"
        if v < -LIM or v > LIM:
            return False, f"SPEC_INVALID: a[{i}] out of range [-1e9,1e9]"
        idx += 1

    for j in range(m):
        ok, v, msg = parse_int(toks[idx], f"b[{j}]")
        if not ok:
            return False, msg
        if v is None:
            return False, f"FORMAT_INVALID: missing b[{j}]"
        if v < -LIM or v > LIM:
            return False, f"SPEC_INVALID: b[{j}] out of range [-1e9,1e9]"
        idx += 1

    return True, "OK"

import re
from decimal import Decimal, InvalidOperation
from typing import Tuple

# Codeforces 600D: Area of Two Circles' Intersection
#
# Input: six numeric values:
#   x1 y1 r1 x2 y2 r2
#
# Constraints:
#   -10^6 <= x1, y1, x2, y2 <= 10^6
#       1 <= r1, r2 <= 10^6
#
# Whitespace may be arbitrary. No extra tokens are allowed.

_WS_SPLIT_RE = re.compile(r"\s+")

_NUM_RE = re.compile(
    r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
)

MIN_COORD = Decimal("-1000000")
MAX_COORD = Decimal("1000000")
MIN_RADIUS = Decimal("1")
MAX_RADIUS = Decimal("1000000")


def _parse_number(tok: str) -> Decimal:
    if _NUM_RE.fullmatch(tok) is None:
        raise ValueError("bad_literal")

    try:
        value = Decimal(tok)
    except InvalidOperation:
        raise ValueError("bad_literal")

    if not value.is_finite():
        raise ValueError("non_finite")

    return value


def validate_input(inp: str) -> Tuple[bool, str]:
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    tokens = _WS_SPLIT_RE.split(s)
    if len(tokens) != 6:
        return False, f"FORMAT_INVALID: expected 6 numbers, got {len(tokens)}"

    values = []
    for i, tok in enumerate(tokens, start=1):
        try:
            values.append(_parse_number(tok))
        except ValueError as exc:
            if str(exc) == "non_finite":
                return False, f"SPEC_INVALID: token {i} is not finite"
            return False, f"FORMAT_INVALID: token {i} is not a valid number"

    x1, y1, r1, x2, y2, r2 = values

    for name, value in (("x1", x1), ("y1", y1), ("x2", x2), ("y2", y2)):
        if value < MIN_COORD or value > MAX_COORD:
            return False, f"SPEC_INVALID: {name} out of range"

    for name, value in (("r1", r1), ("r2", r2)):
        if value < MIN_RADIUS or value > MAX_RADIUS:
            return False, f"SPEC_INVALID: {name} out of range"

    return True, "OK"

