def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validates input for Codeforces 602C - The Two Routes.

    Returns:
      (True, "OK") if valid
      (False, "<PREFIX>: <reason>") otherwise, where PREFIX is FORMAT_INVALID or SPEC_INVALID
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    tokens = s.split()
    # Need at least n, m
    if len(tokens) < 2:
        return False, "FORMAT_INVALID: missing n and m"

    # Parse n, m
    try:
        n = int(tokens[0])
        m = int(tokens[1])
    except Exception:
        return False, "FORMAT_INVALID: n and m must be integers"

    if n < 2 or n > 400:
        return False, "SPEC_INVALID: n out of range [2, 400]"
    max_m = n * (n - 1) // 2
    if m < 0 or m > max_m:
        return False, "SPEC_INVALID: m out of range [0, n(n-1)/2]"

    expected_ints = 2 + 2 * m
    if len(tokens) != expected_ints:
        if len(tokens) < expected_ints:
            return False, "FORMAT_INVALID: not enough integers for m edges"
        else:
            return False, "FORMAT_INVALID: extra trailing tokens"

    # Parse edges
    seen = set()
    idx = 2
    for i in range(m):
        try:
            u = int(tokens[idx]); v = int(tokens[idx + 1])
        except Exception:
            return False, f"FORMAT_INVALID: edge {i+1} endpoints must be integers"
        idx += 2

        if not (1 <= u <= n) or not (1 <= v <= n):
            return False, f"SPEC_INVALID: edge {i+1} endpoint out of range 1..n"
        if u == v:
            return False, f"SPEC_INVALID: self-loop at edge {i+1} (u==v)"

        a, b = (u, v) if u < v else (v, u)
        if (a, b) in seen:
            return False, f"SPEC_INVALID: duplicate railway between {a} and {b}"
        seen.add((a, b))

    return True, "OK"

