    """
    Validator for Codeforces 608A - Saitama Destroys Hotel.

    Expected format (per CF):
      n s
      f1 t1
      ...
      fn tn

    Constraints (typical for this problem):
      1 <= n <= 100
      1 <= s <= 100
      1 <= fi <= s
      0 <= ti <= 10^4  (upper bound not critical for validation; must be int and non-negative)

    We accept extra whitespace, but do not accept extra tokens/lines beyond the required 2+2n integers.
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    # Tokenize by any whitespace
    tokens = inp.split()
    if not tokens:
        return (False, "FORMAT_INVALID: empty input")

    # Must be exactly 2 + 2n integers
    def parse_int(tok: str):
        # disallow things like "01" is fine; disallow non-integers
        try:
            # Python int accepts leading +/-, which is fine syntactically;
            # we'll enforce non-negativity etc. as needed.
            return int(tok)
        except Exception:
            return None

    if len(tokens) < 2:
        return (False, "FORMAT_INVALID: expected at least two integers (n s)")

    n = parse_int(tokens[0])
    s = parse_int(tokens[1])
    if n is None or s is None:
        return (False, "FORMAT_INVALID: n and s must be integers")

    # Basic spec checks
    if n <= 0:
        return (False, "SPEC_INVALID: n must be positive")
    if s < 0:
        return (False, "SPEC_INVALID: s must be non-negative")

    expected_len = 2 + 2 * n
    if len(tokens) != expected_len:
        if len(tokens) < expected_len:
            return (False, f"FORMAT_INVALID: expected {expected_len} integers, got {len(tokens)}")
        else:
            return (False, f"FORMAT_INVALID: extra data after {expected_len} integers")

    # Parse pairs
    pairs = []
    idx = 2
    for i in range(n):
        f = parse_int(tokens[idx]); t = parse_int(tokens[idx + 1])
        if f is None or t is None:
            return (False, f"FORMAT_INVALID: floor/time on line {i+2} must be integers")
        pairs.append((f, t))
        idx += 2

    # Spec validity for pairs
    for i, (f, t) in enumerate(pairs):
        if f < 0:
            return (False, f"SPEC_INVALID: floor fi must be >= 0 (pair {i+1})")
        if f > s:
            return (False, f"SPEC_INVALID: floor fi must be <= s (pair {i+1})")
        # In the original problem, floors are from 0..s and passengers are on some floors;
        # typically fi in [1..s]. We'll allow fi==0 as still meaningful (they're already at 0).
        if t < 0:
            return (False, f"SPEC_INVALID: time ti must be >= 0 (pair {i+1})")

    # Optional: typical CF constraints (non-fatal but enforce as SPEC_INVALID)
    if n > 100:
        return (False, "SPEC_INVALID: n exceeds typical constraint 100")
    if s > 100:
        return (False, "SPEC_INVALID: s exceeds typical constraint 100")

    return (True, "OK")

