def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validates input for Codeforces 609B - The Best Gift.

    Expected format:
      n m
      a1 a2 ... an

    Constraints (per CF problem):
      2 <= n <= 100
      1 <= m <= 100
      1 <= ai <= m

    Also enforces:
      - exactly n integers for the genres list
      - no extra non-whitespace tokens/lines
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if s == "":
        return False, "FORMAT_INVALID: empty input"

