    # (If any other token exists, it's format-invalid.)
    tokens = re.findall(r"[+-]?\d+|\S", s)
    # The regex returns either integers or any non-space single char;
    # we want all tokens to be integers.
    ints = []
    for t in tokens:
        if re.fullmatch(r"[+-]?\d+", t):
            try:
                ints.append(int(t))
            except Exception:
                return False, "FORMAT_INVALID: integer parse error"
        else:
            return False, f"FORMAT_INVALID: non-integer token '{t}'"

    if len(ints) < 2:
        return False, "FORMAT_INVALID: expected at least two integers (n m)"

    n, m = ints[0], ints[1]

    # Basic integer sanity
    if n <= 0 or m <= 0:
        return False, "SPEC_INVALID: n and m must be positive"

    # CF constraints
    if not (2 <= n <= 100):
        return False, f"SPEC_INVALID: n out of range (2..100), got {n}"
    if not (1 <= m <= 100):
        return False, f"SPEC_INVALID: m out of range (1..100), got {m}"

    remaining = ints[2:]
    if len(remaining) != n:
        return False, f"FORMAT_INVALID: expected exactly {n} genre indices, got {len(remaining)}"

    for i, a in enumerate(remaining, 1):
        if not (1 <= a <= m):
