from __future__ import annotations

from dataclasses import dataclass
from typing import List, Tuple


# Checks:
# - exact line/token structure: n on first line; exactly n integers on second line; no extra tokens/lines beyond whitespace
# - numeric bounds: 1 <= n <= 100; 0 <= m_i <= 20000
# - array/string lengths: exactly n task counts
# - graph constraints: none
# - special constraints: none


@dataclass
class Parsed:
    n: int
    m: List[int]


def parse_format(input_str: str) -> Tuple[bool, str, Parsed | None]:
    if input_str is None:
        return False, "FORMAT_INVALID: input is None", None

    s = input_str
    if s.strip() == "":
        return False, "FORMAT_INVALID: empty input", None

    # Enforce no unexpected extra tokens: parse all tokens, then ensure exact count.
    tokens = s.split()
    if len(tokens) < 1:
        return False, "FORMAT_INVALID: missing n", None

    # Parse n
    try:
        n = int(tokens[0])
    except ValueError:
        return False, "FORMAT_INVALID: n is not an integer", None

    # We require exactly 1 + n integers total
    if len(tokens) != 1 + max(n, 0):
        # Provide more specific message when possible
        if n < 0:
            # Token count expectation doesn't make sense if n negative; still format is ok, spec will reject.
            # But here, we can still report structure mismatch only if tokens clearly don't match,
            # however negative n isn't a format issue. We'll defer to spec and only ensure at least 1 token.
            # So accept token count as-is and parse remaining ints (if any) to give better spec error later.
            pass
        else:
            return (
                False,
                f"FORMAT_INVALID: expected exactly {1 + n} integers (n and n task counts), got {len(tokens)}",
                None,
            )

    # Parse m list
    m: List[int] = []
    # If n is negative, still attempt to parse remaining ints and let spec fail on n bound.
    expected_m = max(n, 0)
    if len(tokens) < 1 + expected_m:
        return False, "FORMAT_INVALID: missing task counts", None

    for i in range(expected_m):
        t = tokens[1 + i]
        try:
            val = int(t)
        except ValueError:
            return False, f"FORMAT_INVALID: m[{i+1}] is not an integer", None
        m.append(val)

    # If n negative and there are extra tokens, that's not a format error per se; spec will reject n.
    # But if n >= 0, we already enforced exact token count, so no extras exist.

    return True, "ok", Parsed(n=n, m=m)


def check_constraints(parsed: Parsed) -> Tuple[bool, str]:
    n = parsed.n
    m = parsed.m

    # Official constraints (from CF 609C): 1 <= n <= 100, 0 <= m_i <= 20000
    if not (1 <= n <= 100):
        return False, f"SPEC_INVALID: n out of bounds (1 <= n <= 100), got {n}"

    if len(m) != n:
        # Implied by format; keep as spec check as well.
        return False, f"SPEC_INVALID: expected {n} task counts, got {len(m)}"

    for i, val in enumerate(m, start=1):
        if not (0 <= val <= 20000):
            return False, f"SPEC_INVALID: m[{i}] out of bounds (0 <= m_i <= 20000), got {val}"

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, msg, parsed = parse_format(input_str)
    if not ok:
        return False, msg
    assert parsed is not None
    ok2, msg2 = check_constraints(parsed)
    if not ok2:
        return False, msg2
    return True, "ok"

