def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 609D "Gadgets for dollars and pounds".

    Expected format:
      n m k s
      a1 a2 ... an        (dollar rates)
      b1 b2 ... bn        (pound rates)
      m lines: t c        (t in {1,2}, c positive)

    Returns:
      (True, "OK") on acceptance
      (False, "<PREFIX>: <reason>") on rejection, where PREFIX is one of:
        - FORMAT_INVALID
        - SPEC_INVALID
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    text = inp.strip()
    if text == "":
        return (False, "FORMAT_INVALID: empty input")

    # Tokenize by whitespace; CF inputs are whitespace-separated integers.
    toks = text.split()
    # Quick integer check (allow leading +/- though spec uses positive)
    int_re = re.compile(r"^[+-]?\d+$")
    for i, t in enumerate(toks):
        if not int_re.match(t):
            return (False, f"FORMAT_INVALID: non-integer token at position {i+1}: {t!r}")

    vals = list(map(int, toks))
    idx = 0

    def need(cnt: int, where: str) -> bool:
        nonlocal idx
        if idx + cnt > len(vals):
            return False
        return True

    # Header: n m k s
    if not need(4, "header"):
        return (False, "FORMAT_INVALID: missing header 'n m k s'")
    n, m, k, s = vals[idx], vals[idx+1], vals[idx+2], vals[idx+3]
    idx += 4

    # Spec constraints (from CF 609D)
    # n, m, k up to 2e5, s up to 1e18, rates/costs up to 1e9.
    if n <= 0 or m <= 0 or k < 0:
        return (False, f"SPEC_INVALID: expected n>0, m>0, k>=0, got n={n}, m={m}, k={k}")
    if k > m:
        return (False, f"SPEC_INVALID: k cannot exceed m, got k={k}, m={m}")
    if s < 0:
        return (False, f"SPEC_INVALID: s must be non-negative, got s={s}")
    if n > 200000 or m > 200000:
        return (False, f"SPEC_INVALID: n and m must be <= 200000, got n={n}, m={m}")
    if s > 10**18:
        return (False, f"SPEC_INVALID: s must be <= 1e18, got s={s}")

    # Arrays a and b: length n each
    if not need(n, "a"):
        return (False, f"FORMAT_INVALID: missing {n} dollar rates")
    a = vals[idx:idx+n]
    idx += n
    if not need(n, "b"):
        return (False, f"FORMAT_INVALID: missing {n} pound rates")
    b = vals[idx:idx+n]
    idx += n

    # Validate rates
    for i, x in enumerate(a, start=1):
        if x <= 0:
            return (False, f"SPEC_INVALID: dollar rate a[{i}] must be positive, got {x}")
        if x > 10**9:
            return (False, f"SPEC_INVALID: dollar rate a[{i}] must be <= 1e9, got {x}")
    for i, x in enumerate(b, start=1):
        if x <= 0:
            return (False, f"SPEC_INVALID: pound rate b[{i}] must be positive, got {x}")
        if x > 10**9:
            return (False, f"SPEC_INVALID: pound rate b[{i}] must be <= 1e9, got {x}")

    # m gadget lines: each has t and c
    # Total remaining tokens must be exactly 2*m.
    remaining = len(vals) - idx
    if remaining < 2 * m:
        return (False, f"FORMAT_INVALID: expected {2*m} integers for gadgets, got {remaining}")
    if remaining > 2 * m:
        return (False, f"FORMAT_INVALID: extra trailing tokens: expected {2*m}, got {remaining}")

    for gi in range(1, m + 1):
        t = vals[idx]
        c = vals[idx + 1]
        idx += 2
        if t not in (1, 2):
            return (False, f"SPEC_INVALID: gadget {gi} currency type must be 1 or 2, got {t}")
        if c <= 0:
            return (False, f"SPEC_INVALID: gadget {gi} cost must be positive, got {c}")
        if c > 10**9:
            return (False, f"SPEC_INVALID: gadget {gi} cost must be <= 1e9, got {c}")

    # All consumed exactly
    if idx != len(vals):
        return (False, "FORMAT_INVALID: internal parse error (unconsumed tokens)")

    return (True, "OK")

