def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    left_bound = 1          # possible position interval [left_bound, right_bound]
    right_bound = n

    for line in data[1:]:
        line = line.strip()
        if not line:
            continue
        # Format: "To the left of i" or "To the right of i"
        parts = line.split()
        i = int(parts[-1])
        if parts[2] == "left":
            # Hidden strictly left of i => position <= i-1
            right_bound = min(right_bound, i - 1)
        else:
            # Hidden strictly right of i => position >= i+1
            left_bound = max(left_bound, i + 1)

    if left_bound > right_bound:
        print(-1)
    else:
        print(right_bound - left_bound + 1)

