    if not re.fullmatch(r"[+-]?\d+", m_line or ""):
        return (False, "FORMAT_INVALID: m is not an integer")
    try:
        m = int(m_line)
    except Exception:
        return (False, "FORMAT_INVALID: cannot parse m")

