class Parsed:
    n: int
    kind: str  # "week" or "month"


_LINE_RE = re.compile(r"^([+-]?\d+)\s+of\s+(week|month)$")


def parse_format(input_str: str) -> Tuple[bool, str, Parsed | None]:
    # Disallow empty input
    if input_str is None:
        return False, "FORMAT_INVALID: input is None", None

    # Reject leading/trailing blank lines and multiple lines
    s = input_str
    if s == "":
        return False, "FORMAT_INVALID: empty input", None

    # Split lines preserving possible trailing newline
    lines = s.splitlines()
    if len(lines) != 1:
        return False, f"FORMAT_INVALID: expected exactly 1 line, got {len(lines)}", None

    line = lines[0]
    if line.strip() != line:
        return False, "FORMAT_INVALID: leading/trailing whitespace on the only line is not allowed", None
    if line == "":
