    n, kind = parsed.n, parsed.kind

    # kind is already constrained by regex, but keep defensive check
    if kind not in ("week", "month"):
        return False, 'SPEC_INVALID: kind must be "week" or "month"'

    if kind == "week":
        if not (1 <= n <= 7):
            return False, "SPEC_INVALID: for 'week', n must be in [1, 7]"
    else:  # month
        if not (1 <= n <= 31):
            return False, "SPEC_INVALID: for 'month', n must be in [1, 31]"

