        if u == v:
            return False, f"SPEC_INVALID: self-loop edge ({u}, {v}) not allowed in a tree"
        edges.append((u, v))

    # No duplicate undirected edges in a tree
    seen = set()
    for u, v in edges:
        a, b = (u, v) if u < v else (v, u)
        if (a, b) in seen:
            return False, f"SPEC_INVALID: duplicate edge ({a}, {b})"
        seen.add((a, b))

    # Check it's actually a tree: connected + acyclic.
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(t):
        while parent[t] != t:
            parent[t] = parent[parent[t]]
            t = parent[t]
        return t

