import sys
from functools import lru_cache

MOD = 10**9 + 7

def count_magic_leq(s: str, m: int, d: int) -> int:
    """
    Count d-magic numbers x such that:
      - x has exactly len(s) digits (leading zeros allowed implicitly only via DP but first digit cannot be 0)
      - x <= s (as number with same length)
      - x % m == 0
      - positions are 1-indexed from left:
          even positions => digit must be d
          odd positions  => digit must be != d
    """
    n = len(s)
    digits = list(map(int, s))

    @lru_cache(maxsize=None)
    def dp(pos: int, rem: int, tight: int) -> int:
        if pos == n:
            return 1 if rem == 0 else 0

        limit = digits[pos] if tight else 9
        ans = 0
        position_1_indexed = pos + 1

        if position_1_indexed % 2 == 0:
            # must be digit d
            if d <= limit:
                dig = d
                if pos == 0 and dig == 0:
                    # leading digit cannot be 0
                    pass
                else:
                    ans += dp(pos + 1, (rem * 10 + dig) % m, 1 if tight and dig == limit else 0)
        else:
            # must be digit != d
            for dig in range(0, limit + 1):
                if dig == d:
                    continue
                if pos == 0 and dig == 0:
                    continue  # leading zero not allowed
                ans += dp(pos + 1, (rem * 10 + dig) % m, 1 if tight and dig == limit else 0)

        return ans % MOD

    return dp(0, 0, 1) % MOD

def is_magic_and_multiple(x: str, m: int, d: int) -> bool:
    # x is a decimal string, no leading zeros assumed
    rem = 0
    for i, ch in enumerate(x):
        dig = ord(ch) - 48
        pos = i + 1
        if pos % 2 == 0:
            if dig != d:
                return False
        else:
            if dig == d:
                return False
        rem = (rem * 10 + dig) % m
    return rem == 0

def main() -> None:
