    if not data:
        return
    m = int(data[0])
    d = int(data[1])
    a = data[2].strip()
    b = data[3].strip()

    # a and b have same length in the original problem
    # We'll rely on that; if not, pad/handle would be needed.
    cnt_b = count_magic_leq(b, m, d)
    cnt_a = count_magic_leq(a, m, d)
    ans = (cnt_b - cnt_a) % MOD
    if is_magic_and_multiple(a, m, d):
        ans = (ans + 1) % MOD
    sys.stdout.write(str(ans) + "\n")

