      - Each operation is either:
          1 x   with -n <= x <= n
          2
    """
    if not isinstance(inp, str):
        return False, "FORMAT_INVALID: input is not a string"

    if inp == "":
        return False, "FORMAT_INVALID: empty input"

    lines = inp.splitlines()

    if not lines:
        return False, "FORMAT_INVALID: empty input"

    first = lines[0].split()
    if len(first) != 2:
        return False, "FORMAT_INVALID: first line must contain exactly two integers"

    if not all(_is_int_token(tok) for tok in first):
        return False, "FORMAT_INVALID: n and q must be integers"

    n, q = map(int, first)

    if not (2 <= n <= MAX_N):
        return False, f"SPEC_INVALID: n must satisfy 2 <= n <= {MAX_N}"

    if n % 2 != 0:
        return False, "SPEC_INVALID: n must be even"

    if not (1 <= q <= MAX_Q):
        return False, f"SPEC_INVALID: q must satisfy 1 <= q <= {MAX_Q}"

    if len(lines) != q + 1:
        return False, "FORMAT_INVALID: number of operation lines must be exactly q"

    for i in range(1, q + 1):
        parts = lines[i].split()

        if len(parts) == 0:
            return False, f"FORMAT_INVALID: operation line {i} is empty"

        if not all(_is_int_token(tok) for tok in parts):
            return False, f"FORMAT_INVALID: operation line {i} contains non-integer token"

        t = int(parts[0])

        if t == 1:
            if len(parts) != 2:
                return False, f"FORMAT_INVALID: type 1 operation line {i} must contain exactly two integers"

            x = int(parts[1])
            if not (-n <= x <= n):
                return False, f"SPEC_INVALID: x on operation line {i} must satisfy -n <= x <= n"

        elif t == 2:
            if len(parts) != 1:
                return False, f"FORMAT_INVALID: type 2 operation line {i} must contain exactly one integer"

        else:
            return False, f"SPEC_INVALID: operation type on line {i} must be 1 or 2"

    return True, "OK"

from __future__ import annotations

from dataclasses import dataclass
from typing import List, Tuple


# Checks:
# - exact line/token structure: first line n; then exactly n lines each with exactly 2 integers; no extra tokens
# - numeric bounds: n in [1, 2e5]; xi, yi in [-1e9, 1e9]
# - array/string lengths: exactly n points
# - graph constraints: none
# - special constraints: none (duplicates allowed)


@dataclass
class ParsedInput:
    n: int
    points: List[Tuple[int, int]]


def _is_int_token(tok: str) -> bool:
    # Accept optional leading minus, then digits. Disallow '+' and other forms.
    if tok == "":
        return False
    if tok[0] == "-":
        return tok[1:].isdigit() and len(tok) > 1
    return tok.isdigit()


def parse_format(input_str: str) -> tuple[bool, str, ParsedInput | None]:
    s = input_str
    if s is None:
        return False, "FORMAT_INVALID: input is None", None

    # Disallow empty/whitespace-only input
    if s.strip() == "":
        return False, "FORMAT_INVALID: empty input", None

    # Split into non-empty lines (standard CF inputs do not include empty lines;
    # but tolerate trailing whitespace/newline by stripping line-by-line).
    raw_lines = s.splitlines()
    lines = [ln.strip() for ln in raw_lines if ln.strip() != ""]

    if len(lines) == 0:
        return False, "FORMAT_INVALID: empty input after stripping", None

    # First line: single integer n
    first = lines[0].split()
    if len(first) != 1:
        return False, "FORMAT_INVALID: first line must contain exactly 1 integer n", None
    if not _is_int_token(first[0]):
        return False, "FORMAT_INVALID: n is not a valid integer token", None
    try:
        n = int(first[0])
    except Exception:
        return False, "FORMAT_INVALID: failed to parse n as integer", None

    # Need exactly n following lines with 2 integers each
    expected_total_lines = 1 + n
    if len(lines) != expected_total_lines:
        return (
            False,
            f"FORMAT_INVALID: expected {expected_total_lines} non-empty lines (1+n), got {len(lines)}",
            None,
        )

    points: List[Tuple[int, int]] = []
    for i in range(n):
        toks = lines[1 + i].split()
        if len(toks) != 2:
            return (
                False,
                f"FORMAT_INVALID: line {2+i} must contain exactly 2 integers xi yi",
                None,
            )
        if not _is_int_token(toks[0]) or not _is_int_token(toks[1]):
            return (
                False,
                f"FORMAT_INVALID: line {2+i} contains non-integer token(s)",
                None,
            )
        try:
            x = int(toks[0])
            y = int(toks[1])
        except Exception:
            return False, f"FORMAT_INVALID: failed to parse integers on line {2+i}", None
        points.append((x, y))

    return True, "ok", ParsedInput(n=n, points=points)


def check_constraints(parsed: ParsedInput) -> tuple[bool, str]:
    n = parsed.n
    pts = parsed.points

    # Official constraints for CF 650A (Watchmen):
    # 1 <= n <= 2e5, -1e9 <= xi, yi <= 1e9
    if not (1 <= n <= 200000):
        return False, f"SPEC_INVALID: n={n} out of bounds [1, 200000]"
    if len(pts) != n:
        return False, f"SPEC_INVALID: number of points {len(pts)} != n={n}"

    for idx, (x, y) in enumerate(pts, start=1):
        if x < -10**9 or x > 10**9:
            return False, f"SPEC_INVALID: x_{idx}={x} out of bounds [-1e9, 1e9]"
        if y < -10**9 or y > 10**9:
            return False, f"SPEC_INVALID: y_{idx}={y} out of bounds [-1e9, 1e9]"

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, msg, parsed = parse_format(input_str)
    if not ok:
        return False, msg
    assert parsed is not None
    ok2, msg2 = check_constraints(parsed)
    if not ok2:
        return False, msg2
    return True, "ok"

