from typing import Tuple

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validates input for Codeforces 652D - Nested Segments.

    Expected format:
      n
      l1 r1
      ...
      ln rn

    Spec details (as per typical CF constraints/statement):
    - n is an integer, usually 1..200000 (we enforce this common constraint).
    - li, ri are integers with li < ri.
    - No two endpoints among all 2n endpoints coincide (all li and ri are distinct).
    - No extra tokens/lines beyond the required 2n+1 integers.
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    s = inp.strip()
    if s == "":
        return (False, "FORMAT_INVALID: empty input")

    # Tokenize by whitespace; CF input is whitespace-separated.
    tokens = s.split()
    if not tokens:
        return (False, "FORMAT_INVALID: no tokens found")

    # Parse n
    try:
        n = int(tokens[0])
    except Exception:
        return (False, "FORMAT_INVALID: n is not an integer")

    # Enforce common CF constraint for this problem.
    # If you prefer to be more permissive, relax/adjust this bound.
    if n < 1 or n > 200000:
        return (False, "SPEC_INVALID: n out of allowed range [1, 200000]")

    expected_tokens = 1 + 2 * n
    if len(tokens) != expected_tokens:
        if len(tokens) < expected_tokens:
            return (False, f"FORMAT_INVALID: not enough integers (expected {expected_tokens}, got {len(tokens)})")
        else:
            return (False, f"FORMAT_INVALID: too many integers (expected {expected_tokens}, got {len(tokens)})")

    endpoints = set()

    # Parse segments
    idx = 1
    for i in range(n):
        try:
            l = int(tokens[idx]); r = int(tokens[idx + 1])
        except Exception:
            return (False, f"FORMAT_INVALID: segment {i+1} endpoints are not integers")
        idx += 2

        if l >= r:
            return (False, f"SPEC_INVALID: segment {i+1} violates li < ri (got {l} {r})")

        # No coinciding endpoints across all segments.
        if l in endpoints:
            return (False, f"SPEC_INVALID: endpoint value {l} appears more than once")
        if r in endpoints:
            return (False, f"SPEC_INVALID: endpoint value {r} appears more than once")
        endpoints.add(l)
        endpoints.add(r)

    return (True, "OK")

from __future__ import annotations

def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validator for Codeforces 652F - Ants on a Circle.

    Expected format (from CF):
      n m t
      s1 d1
      s2 d2
      ...
      sn dn

    Constraints (CF):
      1 <= n <= 2e5
      1 <= m <= 1e9
      0 <= t <= 1e9
      0 <= si < m, all distinct
      di in {'L','R'}

    Returns:
      (True, "OK") on acceptance
      (False, "<PREFIX>: ...") on rejection where PREFIX is FORMAT_INVALID or SPEC_INVALID
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    s = inp
    if s.strip() == "":
        return (False, "FORMAT_INVALID: empty input")

    # Tokenize by whitespace (CF standard)
    toks = s.split()
    if len(toks) < 3:
        return (False, "FORMAT_INVALID: expected at least 3 tokens (n m t)")

    def parse_int(tok: str, name: str) -> tuple[bool, int | None, str]:
        try:
            # Allow leading +/-, but CF uses non-negative except n,m.
            v = int(tok, 10)
        except Exception:
            return (False, None, f"FORMAT_INVALID: {name} is not an integer")
        return (True, v, "")

    ok, n, msg = parse_int(toks[0], "n")
    if not ok:
        return (False, msg)
    ok, m, msg = parse_int(toks[1], "m")
    if not ok:
        return (False, msg)
    ok, t, msg = parse_int(toks[2], "t")
    if not ok:
        return (False, msg)

    # Spec checks for first line
    if n is None or m is None or t is None:
        return (False, "FORMAT_INVALID: failed to parse n/m/t")

    if n < 1 or n > 200000:
        return (False, "SPEC_INVALID: n out of range (1..200000)")
    if m < 1 or m > 10**9:
        return (False, "SPEC_INVALID: m out of range (1..1e9)")
    if t < 0 or t > 10**9:
        return (False, "SPEC_INVALID: t out of range (0..1e9)")

    expected_tokens = 3 + 2 * n
    if len(toks) != expected_tokens:
        return (False, f"FORMAT_INVALID: expected {expected_tokens} tokens, got {len(toks)}")

    seen_positions = set()
    idx = 3
    for i in range(1, n + 1):
        tok_s = toks[idx]
        tok_d = toks[idx + 1]
        idx += 2

        ok, si, msg = parse_int(tok_s, f"s{i}")
        if not ok:
            return (False, msg)
        if si is None:
            return (False, f"FORMAT_INVALID: s{i} missing")

        # direction must be exactly 'L' or 'R'
        if tok_d not in ("L", "R"):
            return (False, f"SPEC_INVALID: d{i} must be 'L' or 'R'")

        if si < 0 or si >= m:
            return (False, f"SPEC_INVALID: s{i} out of range (0..m-1)")
        if si in seen_positions:
            return (False, f"SPEC_INVALID: positions must be distinct; duplicate at s{i}={si}")
        seen_positions.add(si)

    return (True, "OK")

