_INT_RE = re.compile(r"^[+-]?\d+$")

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for codeforces__cf_656_E - Out of Controls.

    Expected format:
      n
      a_11 a_12 ... a_1n
      ...
      a_n1 a_n2 ... a_nn

    Complete undirected weighted graph represented by an n x n matrix.
    Diagonal must be 0, matrix must be symmetric, off-diagonal edge lengths
    must be positive integers.
    """

    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    tokens = inp.split()
    if not tokens:
        return False, "FORMAT_INVALID: empty input"

    for tok in tokens:
        if not _INT_RE.fullmatch(tok):
            return False, f"FORMAT_INVALID: non-integer token {tok!r}"

    try:
        vals = [int(tok) for tok in tokens]
    except Exception:
        return False, "FORMAT_INVALID: failed to parse integers"

    n = vals[0]

    # Conservative standard bounds for this problem style.
    if not (1 <= n <= 100):
        return False, "SPEC_INVALID: n must be between 1 and 100"

    expected = 1 + n * n
    if len(vals) != expected:
        return (
            False,
            f"FORMAT_INVALID: expected {expected} integers total for an {n}x{n} matrix, got {len(vals)}",
        )

    mat_vals = vals[1:]
    a = [mat_vals[i * n:(i + 1) * n] for i in range(n)]

    # Edge lengths: use a broad safe upper bound while still rejecting
    # clearly nonsensical values for typical integer-weight graph tasks.
    MAX_W = 10 ** 9

    for i in range(n):
        for j in range(n):
            x = a[i][j]

            if i == j:
                if x != 0:
                    return False, "SPEC_INVALID: diagonal entries must be 0"
            else:
                if not (1 <= x <= MAX_W):
                    return False, "SPEC_INVALID: off-diagonal edge lengths must be in [1, 10^9]"

    for i in range(n):
        for j in range(i + 1, n):
            if a[i][j] != a[j][i]:
                return False, "SPEC_INVALID: matrix must be symmetric for an undirected graph"

    return True, "OK"

