def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validate input for Codeforces 658B - Bear and Displayed Friends.

    Returns:
      (True, "OK") if valid
      (False, "<PREFIX>: <reason>") otherwise, where PREFIX is FORMAT_INVALID or SPEC_INVALID.
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    parts = s.split()
    # Need at least: n k q, then n t-values, then 2*q query integers
    if len(parts) < 3:
        return False, "FORMAT_INVALID: missing n k q"

    def parse_int(tok: str):
        # Disallow non-integers cleanly
        try:
            # int() allows leading +/-, which is ok format-wise, spec will reject negatives.
            return int(tok)
        except Exception:
            return None

    idx = 0
    n = parse_int(parts[idx]); idx += 1
    k = parse_int(parts[idx]); idx += 1
    q = parse_int(parts[idx]); idx += 1
    if n is None or k is None or q is None:
        return False, "FORMAT_INVALID: n/k/q not integers"

    # Spec constraints
    if not (1 <= n <= 150_000):
        return False, f"SPEC_INVALID: n out of range (got {n})"
    if not (1 <= q <= 150_000):
        return False, f"SPEC_INVALID: q out of range (got {q})"
    if not (1 <= k <= min(6, n)):
        return False, f"SPEC_INVALID: k out of range (got {k}, min(6,n)={min(6,n)})"

    # t array
    if len(parts) < idx + n:
        return False, "FORMAT_INVALID: not enough t_i values"
    t = []
    seen_t = set()
    for i in range(n):
        v = parse_int(parts[idx]); idx += 1
        if v is None:
            return False, f"FORMAT_INVALID: t[{i+1}] not an integer"
        if not (1 <= v <= 1_000_000_000):
            return False, f"SPEC_INVALID: t[{i+1}] out of range (got {v})"
        if v in seen_t:
            return False, f"SPEC_INVALID: t values must be unique (duplicate {v})"
        seen_t.add(v)
        t.append(v)

    # Queries
    # Must have exactly 2*q integers remaining; extra tokens => format invalid
    remaining = len(parts) - idx
    need = 2 * q
    if remaining < need:
        return False, f"FORMAT_INVALID: not enough query tokens (need {need}, have {remaining})"
    if remaining > need:
        return False, f"FORMAT_INVALID: extra tokens after reading queries (extra {remaining - need})"

    online = [False] * (n + 1)
    became_online = set()
    saw_type2 = False

    for qi in range(1, q + 1):
        typ = parse_int(parts[idx]); idx += 1
        fid = parse_int(parts[idx]); idx += 1
        if typ is None or fid is None:
            return False, f"FORMAT_INVALID: query {qi} has non-integer fields"
        if typ not in (1, 2):
            return False, f"SPEC_INVALID: query {qi} type must be 1 or 2 (got {typ})"
        if not (1 <= fid <= n):
            return False, f"SPEC_INVALID: query {qi} id out of range (got {fid})"

        if typ == 1:
