            if fid in became_online:
                return False, f"SPEC_INVALID: friend {fid} becomes online more than once"
            if online[fid]:
                # Redundant given became_online check, but keep as spec check.
                return False, f"SPEC_INVALID: friend {fid} was already online before query {qi}"
            became_online.add(fid)
            online[fid] = True
        else:
            saw_type2 = True

    if not saw_type2:
        return False, "SPEC_INVALID: at least one query of type 2 is required"

    return True, "OK"

