def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validator for Codeforces 659D - Bicycle Race.

    Expected format:
      n
      x1 y1
      x2 y2
      ...
      xn yn

    Spec (CF):
      - 4 <= n <= 1000
      - coordinates are integers, typically within [-10000, 10000] (CF constraint)
      - polygonal chain describes a simple orthogonal polygon (axis-aligned edges)
      - consecutive points are distinct and differ in exactly one coordinate
      - last point connects back to first (implicit) and is also orthogonal
      - no immediate backtracking: direction never changes to its opposite between consecutive edges
        (i.e., no N then S, S then N, E then W, W then E)
      - starting point is not required to be first in input; input is just the contour order
        (so we do not validate the "southernmost, then move north" narrative as an input property)

    We accept all trusted valid inputs. We reject malformed or clearly spec-invalid inputs.
    """
    def fmt_err(msg: str) -> tuple[bool, str]:
        return False, "FORMAT_INVALID: " + msg

    def spec_err(msg: str) -> tuple[bool, str]:
        return False, "SPEC_INVALID: " + msg

    if inp is None:
        return fmt_err("input is None")

    s = inp.strip()
    if not s:
        return fmt_err("empty input")

    toks = s.split()
    if len(toks) < 1:
        return fmt_err("missing n")

