    try:
        n = int(toks[0])
    except Exception:
        return fmt_err("n is not an integer")

    if n < 4 or n > 1000:
        return spec_err(f"n out of range: {n} (expected 4..1000)")

    expected = 1 + 2 * n
    if len(toks) != expected:
        return fmt_err(f"expected {expected} tokens (n + 2*n coords), got {len(toks)}")

    pts: list[tuple[int, int]] = []
    idx = 1
    for i in range(n):
        try:
            x = int(toks[idx]); y = int(toks[idx + 1])
        except Exception:
            return fmt_err(f"point {i+1} has non-integer coordinate(s)")
        idx += 2

