    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    s = inp
    # Allow leading/trailing whitespace, including final newline.
    s_stripped = s.strip()
    if s_stripped == "":
        return (False, "FORMAT_INVALID: empty input")

    # Split by whitespace (handles any spaces/newlines)
    toks = re.split(r"\s+", s_stripped)
    if any(t == "" for t in toks):
        return (False, "FORMAT_INVALID: bad tokenization")

    def is_int_token(t: str) -> bool:
        # CF inputs are plain integers; allow optional leading +/-
        return re.fullmatch(r"[+-]?\d+", t) is not None

    for t in toks:
        if not is_int_token(t):
            return (False, f"FORMAT_INVALID: non-integer token '{t}'")

    # Parse
    try:
        vals = list(map(int, toks))
    except Exception:
        return (False, "FORMAT_INVALID: cannot parse integers")

    if len(vals) < 1:
        return (False, "FORMAT_INVALID: missing n")

    n = vals[0]

    # Spec constraints for this problem (CF 690F1):
    # Typical constraints: 2 <= n <= 200000 (easy version still large).
    # We'll enforce a reasonable CF bound; if the platform uses different,
    # this can be relaxed.
    if n < 1:
        return (False, "SPEC_INVALID: n must be >= 1")
    if n > 200000:
        return (False, "SPEC_INVALID: n too large (> 200000)")

    expected_ints = 1 + 2 * max(0, n - 1)
    if len(vals) != expected_ints:
        return (False, f"FORMAT_INVALID: expected {expected_ints} integers total, got {len(vals)}")

    # Extract edges
    edges = []
    idx = 1
    for _ in range(max(0, n - 1)):
        u = vals[idx]
        v = vals[idx + 1]
        idx += 2
        edges.append((u, v))

    # Vertex labels must be in [1..n]
    for i, (u, v) in enumerate(edges, start=1):
        if not (1 <= u <= n) or not (1 <= v <= n):
            return (False, f"SPEC_INVALID: edge {i} has vertex out of range 1..n: ({u},{v})")
        if u == v:
            return (False, f"SPEC_INVALID: self-loop at edge {i}: ({u},{v})")

    # If n==1, there must be 0 edges (already ensured by count)
    if n == 1:
        return (True, "OK")

    # Must form a tree: exactly n-1 edges, connected, acyclic.
    # Check for duplicate undirected edges (not allowed in a simple tree).
    seen = set()
    for i, (u, v) in enumerate(edges, start=1):
        a, b = (u, v) if u < v else (v, u)
        if (a, b) in seen:
            return (False, f"SPEC_INVALID: duplicate edge {a}-{b}")
        seen.add((a, b))

    # DSU to check connectivity / cycles
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> bool:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    for (u, v) in edges:
        if not union(u, v):
            return (False, "SPEC_INVALID: graph contains a cycle (not a tree)")

    root = find(1)
    for v in range(2, n + 1):
        if find(v) != root:
            return (False, "SPEC_INVALID: graph is disconnected (not a tree)")

    return (True, "OK")

