class Parsed:
    n: int
    k: int
    s: int
    t: int
    cars: List[Tuple[int, int]]  # (c, v)
    stations: List[int]


def _is_int_token(tok: str) -> bool:
    if tok == "":
        return False
    if tok[0] == "-":
        return len(tok) > 1 and tok[1:].isdigit()
    return tok.isdigit()


def parse_format(input_str: str) -> tuple[bool, str, Optional[Parsed]]:
