    n, k, road_s, t = map(int, tokens[:4])

    # After that: 2*n tokens for cars and k tokens for stations
    need = 4 + 2 * n + k
    if len(tokens) < need:
        return False, "FORMAT_INVALID: not enough tokens for declared n cars and k stations", None
    if len(tokens) > need:
        return False, "FORMAT_INVALID: extra tokens after reading n cars and k stations", None

    idx = 4
    cars: List[Tuple[int, int]] = []
    for i in range(n):
        if idx + 1 >= len(tokens):
            return False, "FORMAT_INVALID: incomplete car specification", None
        a, b = tokens[idx], tokens[idx + 1]
        if not (_is_int_token(a) and _is_int_token(b)):
            return False, f"FORMAT_INVALID: car {i+1} has non-integer token(s)", None
        c, v = int(a), int(b)
        cars.append((c, v))
        idx += 2

    stations: List[int] = []
    for j in range(k):
        tok = tokens[idx + j]
        if not _is_int_token(tok):
            return False, f"FORMAT_INVALID: station position {j+1} is not an integer", None
        stations.append(int(tok))

    return True, "ok", Parsed(n=n, k=k, s=road_s, t=t, cars=cars, stations=stations)


def check_constraints(parsed: Parsed) -> tuple[bool, str]:
    n, k, s, t = parsed.n, parsed.k, parsed.s, parsed.t

    # Known CF 729C constraints (not written explicitly in prompt, but standard for this problem).
    if not (1 <= n <= 200000):
