        if not (0 < x < s):
            return False, f"SPEC_INVALID: station position {idx} must satisfy 0 < x < s"
        if x in seen:
            return False, "SPEC_INVALID: station positions must be distinct"
        seen.add(x)

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, msg, parsed = parse_format(input_str)
    if not ok:
        return False, msg
    assert parsed is not None
    ok2, msg2 = check_constraints(parsed)
    if not ok2:
        return False, msg2
