import sys

def solve() -> None:
    input = sys.stdin.readline
    n, m = map(int, input().split())
    d = list(map(int, input().split()))
    a = list(map(int, input().split()))

    # last occurrence day (1-indexed) of each subject within prefix
    def can(mid: int) -> bool:
        last = [-1] * (m + 1)
        for i in range(mid):
            subj = d[i]
            if subj != 0:
                last[subj] = i + 1  # day number

        # all subjects must have an exam day within [1..mid]
        for s in range(1, m + 1):
            if last[s] == -1:
                return False

        # schedule: go through days 1..mid, reserve exam days,
        # other days are preparation days we can allocate.
        # We must have, before each exam day, accumulated enough prep for that subject.
        need = [0] * (m + 1)
        for s in range(1, m + 1):
            need[s] = a[s - 1]

        prep_available = 0
        # process days in increasing order; on an exam day of subject s (its last occurrence),
        # we must spend that day on exam, and have already prepared need[s] days before it.
        exam_of_day = [0] * (mid + 1)
        for s in range(1, m + 1):
            exam_of_day[last[s]] = s

        for day in range(1, mid + 1):
            s = exam_of_day[day]
            if s == 0:
                prep_available += 1
            else:
                if prep_available < need[s]:
                    return False
                prep_available -= need[s]
                # exam consumes the day (already accounted by not adding prep)
        return True

    lo, hi = 1, n
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if can(mid):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1

    print(ans)

