import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        n = int(next(it))
    except StopIteration:
        return
    kx, ky = int(next(it)), int(next(it))

    # For each of 8 directions from the king, keep the nearest piece (distance, type)
    # Directions: N, S, E, W, NE, NW, SE, SW
    dirs = {
        (0, 1): None,
        (0, -1): None,
        (1, 0): None,
        (-1, 0): None,
        (1, 1): None,
        (-1, 1): None,
        (1, -1): None,
        (-1, -1): None,
    }

    for _ in range(n):
        t = next(it)
        x, y = int(next(it)), int(next(it))
        dx, dy = x - kx, y - ky

        # Same file
        if dx == 0 and dy != 0:
            step = (0, 1) if dy > 0 else (0, -1)
            dist = abs(dy)
        # Same rank
        elif dy == 0 and dx != 0:
            step = (1, 0) if dx > 0 else (-1, 0)
            dist = abs(dx)
        # Same diagonal
        elif abs(dx) == abs(dy) and dx != 0:
            step = (1 if dx > 0 else -1, 1 if dy > 0 else -1)
            dist = abs(dx)
        else:
            continue

        cur = dirs[step]
        if cur is None or dist < cur[0]:
            dirs[step] = (dist, t)

    # Check if the nearest piece in any direction attacks the king
    for (sx, sy), info in dirs.items():
        if info is None:
            continue
        _, t = info
        if sx == 0 or sy == 0:
            if t == 'R' or t == 'Q':
                sys.stdout.write("YES")
                return
        else:
            if t == 'B' or t == 'Q':
                sys.stdout.write("YES")
                return

    sys.stdout.write("NO")


if __name__ == "__main__":
    solve()

