def solve() -> None:
    input = sys.stdin.readline
    n = int(input().strip())
    s = input().strip()

    r = deque()
    d = deque()
    for i, ch in enumerate(s):
        if ch == 'R':
            r.append(i)
        else:
            d.append(i)

    # Greedy simulation using index queues:
    # At each step, the earlier index acts first and bans one opponent;
    # the acting employee goes to the back with index + n (next round).
    while r and d:
        ri = r.popleft()
        di = d.popleft()
        if ri < di:
            # R acts first, bans that D
            r.append(ri + n)
        else:
            # D acts first, bans that R
            d.append(di + n)

    sys.stdout.write("R" if r else "D")

