import sys

def can_fit(s: str, k: int, w: int) -> bool:
    n = len(s)
    i = 0
    lines = 1
    cur = 0

    while i < n:
        if cur == w:
            # Must break line exactly here
            if s[i] == ' ':
                i += 1  # space stays on previous line
            lines += 1
            cur = 0
            if lines > k:
                return False
            continue

        ch = s[i]
        if ch == ' ':
            if cur + 1 > w:
                lines += 1
                cur = 0
                if lines > k:
                    return False
                # space stays on previous line, so skip it now (it will be at end of previous line)
                i += 1
            else:
                cur += 1
                i += 1
        elif ch == '-':
            # hyphen may be a wrap point: if doesn't fit, we can break BEFORE it (but only if cur>0)
            if cur + 1 <= w:
                cur += 1
                i += 1
                # Optionally break after hyphen, but that's only useful if next can't fit;
                # the greedy mechanism via cur==w will handle forced breaks.
            else:
                if cur == 0:
                    return False
                lines += 1
                cur = 0
                if lines > k:
                    return False
                # do not consume '-', it starts new line now
        else:
            if cur + 1 <= w:
                cur += 1
                i += 1
            else:
                if cur == 0:
                    return False
                lines += 1
                cur = 0
                if lines > k:
                    return False
                # do not consume this char; it starts new line now

    return lines <= k

