def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 812B - Sagheer, the Hausmeister.

    Expected format:
      n m
      row1
      row2
      ...
      rown

    Constraints (per CF statement):
      1 <= n <= 15
      1 <= m <= 100
      Each row length must be m+2, consisting only of '0'/'1'.
      First/last char correspond to stairs but are still given as 0/1.
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    s = inp.strip("\n")
    if not s.strip():
        return (False, "FORMAT_INVALID: empty input")

    lines = s.splitlines()
    if len(lines) < 1:
        return (False, "FORMAT_INVALID: missing header line")

    # Header: n m
    header = lines[0].strip()
    parts = header.split()
    if len(parts) != 2:
        return (False, "FORMAT_INVALID: header must contain exactly two integers 'n m'")
    try:
        n = int(parts[0])
        m = int(parts[1])
    except ValueError:
        return (False, "FORMAT_INVALID: header contains non-integer tokens")

    # Spec constraints
    if not (1 <= n <= 15):
        return (False, f"SPEC_INVALID: n out of range (1..15), got {n}")
    if not (1 <= m <= 100):
        return (False, f"SPEC_INVALID: m out of range (1..100), got {m}")

    # Need exactly n rows following
    if len(lines) != 1 + n:
        return (False, f"FORMAT_INVALID: expected {n} floor lines, got {len(lines)-1}")

    expected_len = m + 2
    for i in range(n):
        row = lines[1 + i].strip()
        if len(row) != expected_len:
            return (False, f"FORMAT_INVALID: line {i+2} length must be {expected_len}, got {len(row)}")
        if not re.fullmatch(r"[01]+", row):
            return (False, f"FORMAT_INVALID: line {i+2} must contain only '0' and '1'")

    # No extra tokens/lines beyond exactly n+1 already checked.
    return (True, "OK")

