            lj = next_int(f"l[{j}]")
            rj = next_int(f"r[{j}]")
            intervals.append((lj, rj))
    except ValueError as e:
        return False, f"FORMAT_INVALID: {e}"

    for j, (lj, rj) in enumerate(intervals):
        if lj < 1 or rj < 1:
