from dataclasses import dataclass
from typing import List, Tuple, Optional

# Checks:
# - exact line/token structure: integer n on first line; exactly n integers on second line; no extra tokens/lines
# - numeric bounds: n within [1, 10^5]; each a_i within [1, 10^9] (as per CF 815B common constraints)
# - array/string lengths: exactly n numbers provided
# - graph constraints: none
# - special constraints: none


@dataclass
class Parsed:
    n: int
    a: List[int]


def _is_int_token(tok: str) -> bool:
    # Accept optional leading minus, though spec may restrict to positive later.
    if tok == "":
        return False
    if tok[0] == "-":
        return tok[1:].isdigit() and len(tok) > 1
    return tok.isdigit()


def parse_format(input_str: str) -> Tuple[Optional[Parsed], Tuple[bool, str]]:
    s = input_str
    if s is None:
        return None, (False, "FORMAT_INVALID: input is None")
    # Do not allow empty/whitespace-only input
    if s.strip() == "":
        return None, (False, "FORMAT_INVALID: empty input")

    # Split into lines, keep exact line count expectations (2 lines).
    # Allow trailing newline(s) but no extra non-empty lines.
    raw_lines = s.splitlines()
    # Remove trailing empty lines caused by ending newline(s)
    while raw_lines and raw_lines[-1].strip() == "":
        raw_lines.pop()

    if len(raw_lines) != 2:
        return None, (False, f"FORMAT_INVALID: expected exactly 2 non-empty lines, got {len(raw_lines)}")

    line1 = raw_lines[0].strip()
    if line1 == "":
        return None, (False, "FORMAT_INVALID: first line is empty")
    t1 = line1.split()
    if len(t1) != 1:
        return None, (False, f"FORMAT_INVALID: first line must contain exactly 1 token, got {len(t1)}")
    if not _is_int_token(t1[0]):
        return None, (False, "FORMAT_INVALID: n is not an integer")
    try:
        n = int(t1[0])
    except Exception:
        return None, (False, "FORMAT_INVALID: failed to parse n as integer")

    line2 = raw_lines[1].strip()
    if line2 == "":
        return None, (False, "FORMAT_INVALID: second line is empty (expected n integers)")
    t2 = line2.split()
    if len(t2) != n:
        return None, (False, f"FORMAT_INVALID: expected exactly {n} integers on second line, got {len(t2)}")

    a: List[int] = []
    for i, tok in enumerate(t2):
        if not _is_int_token(tok):
            return None, (False, f"FORMAT_INVALID: a[{i}] is not an integer")
        try:
            val = int(tok)
        except Exception:
            return None, (False, f"FORMAT_INVALID: failed to parse a[{i}] as integer")
        a.append(val)

    return Parsed(n=n, a=a), (True, "ok")


def check_constraints(parsed: Parsed) -> Tuple[bool, str]:
    # The official CF 815B constraints are:
    # 1 <= n <= 1e5
    # 1 <= a_i <= 1e9
    # (These are standard for this problem; statement text in prompt omitted them.)
    n = parsed.n
    a = parsed.a

    if not (1 <= n <= 100000):
        return False, f"SPEC_INVALID: n out of bounds (1..100000), got {n}"
    if len(a) != n:
        return False, f"SPEC_INVALID: array length {len(a)} does not match n={n}"

    for i, val in enumerate(a):
        if not (1 <= val <= 10**9):
            return False, f"SPEC_INVALID: a[{i}] out of bounds (1..1e9), got {val}"

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    parsed, (ok, msg) = parse_format(input_str)
    if not ok:
        return False, msg
    assert parsed is not None
    ok2, msg2 = check_constraints(parsed)
    if not ok2:
        return False, msg2
    return True, "ok"

