import sys

def digit_sum(x: int) -> int:
    s = 0
    while x:
        s += x % 10
        x //= 10
    return s

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = int(data[1])

    # We need count of x in [1..n] such that x - sumdigits(x) >= s
    # The predicate is monotone: if it holds for x, it holds for all larger x.
    # So find the smallest x that satisfies it via binary search.
    lo, hi = 1, n + 1  # answer position in [1..n+1], n+1 means none
    while lo < hi:
        mid = (lo + hi) // 2
        if mid - digit_sum(mid) >= s:
            hi = mid
        else:
            lo = mid + 1

    first = lo
    if first == n + 1:
        print(0)
    else:
        print(n - first + 1)

