    need_item_after_comma = False
    seen_item = False
    spaces_since_prev_item = False

    while i < n:
        ch = s[i]

        if ch == " ":
            if prev_item is not None:
                spaces_since_prev_item = True
            i += 1
            continue

        if ch == ",":
            if prev_item is None:
                return False, "SPEC_INVALID: comma cannot appear before a sequence item"
            if need_item_after_comma:
                return False, "SPEC_INVALID: comma cannot create an empty sequence item"

            need_item_after_comma = True
            prev_item = None
            spaces_since_prev_item = False
            i += 1
            continue

