            if i + 3 > n or s[i:i + 3] != "...":
                return False, "SPEC_INVALID: dots must appear only as the exact term '...'"
            if i + 3 < n and s[i + 3] == ".":
                return False, "SPEC_INVALID: dots must appear only as groups of exactly three"

