def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validator for Codeforces 825E - Minimal Labels.

    Expected format:
      n m
      v1 u1
      ...
      vm um

    Constraints (from typical CF statement for this problem):
      1 <= n <= 200000
      0 <= m <= 200000
      1 <= vi, ui <= n
      No self-loops
      No multiple edges
      The graph is a DAG (acyclic)

    Returns:
      (True, "OK") if valid, else (False, "<PREFIX>: ...")
      PREFIX is FORMAT_INVALID or SPEC_INVALID.
    """
    s = inp
    if s is None:
        return False, "FORMAT_INVALID: input is None"

    # Allow trailing whitespace; disallow leading garbage? We'll parse tokens.
    tokens = s.split()
    if not tokens:
        return False, "FORMAT_INVALID: empty input"

    def fail_fmt(msg: str):
        return (False, f"FORMAT_INVALID: {msg}")

    def fail_spec(msg: str):
        return (False, f"SPEC_INVALID: {msg}")

    # Need at least n and m
    if len(tokens) < 2:
        return fail_fmt("expected at least two integers n m")

    # Parse n, m
    try:
        n = int(tokens[0])
        m = int(tokens[1])
    except Exception:
        return fail_fmt("n and m must be integers")

    # Basic constraints
    if n <= 0:
        return fail_spec("n must be >= 1")
    if m < 0:
        return fail_spec("m must be >= 0")

    # Common CF constraints; enforce to avoid pathological inputs
    if n > 200000:
        return fail_spec("n exceeds 200000")
    if m > 200000:
        return fail_spec("m exceeds 200000")

    # Edge tokens count must match exactly 2*m after the first 2 tokens
    expected = 2 + 2 * m
    if len(tokens) != expected:
        return fail_fmt(f"expected {expected} integers total (n m plus {m} edges), got {len(tokens)}")

    # Parse edges, check ranges, self-loops, duplicates.
    edges = set()
    # Build adjacency for cycle check
    adj = [[] for _ in range(n + 1)]
    indeg = [0] * (n + 1)

    idx = 2
    for i in range(m):
        try:
            v = int(tokens[idx]); u = int(tokens[idx + 1])
        except Exception:
            return fail_fmt(f"edge {i+1} endpoints must be integers")
        idx += 2

        if not (1 <= v <= n) or not (1 <= u <= n):
            return fail_spec(f"edge {i+1} has endpoint out of range 1..n")
        if v == u:
            return fail_spec(f"self-loop detected at vertex {v}")
        e = (v, u)
        if e in edges:
            return fail_spec(f"multiple edge detected: {v}->{u}")
        edges.add(e)

        adj[v].append(u)
        indeg[u] += 1

    # DAG check via Kahn's algorithm
    # (O(n+m), fine for bounds)
    from collections import deque
