import sys, math, random

def solve():
    input = sys.stdin.readline
    n, x, y = map(int, input().split())
    a = list(map(int, input().split()))

    g = 0
    for v in a:
        g = math.gcd(g, v)
    if g > 1:
        print(0)
        return

    # Candidate primes from values near elements; standard randomized approach.
    # For each candidate prime p, compute minimal cost to make remaining numbers all divisible by p
    # using either delete (cost x) or increment to next multiple (cost y * delta).
    cand_primes = set()

    def add_primes_from(val):
        if val <= 1:
            return
        t = val
        d = 2
        while d * d <= t:
            if t % d == 0:
                cand_primes.add(d)
                while t % d == 0:
                    t //= d
            d += 1 if d == 2 else 2
        if t > 1:
            cand_primes.add(t)

    # Sample some indices (as in known solution)
    m = min(n, 20)
    idxs = [random.randrange(n) for _ in range(m)]
    for i in idxs:
        v = a[i]
        for delta in (-1, 0, 1):
            if v + delta >= 2:
                add_primes_from(v + delta)

    INF = 10**30
    ans = INF

    for p in cand_primes:
        total = 0
        for v in a:
            r = v % p
            if r == 0:
                continue
            inc = (p - r) * y
            # Also allow decreasing by 1 only implicitly via delete; we can increase only.
            total += min(x, inc)
            if total >= ans:
                break
        ans = min(ans, total)

    print(ans)

