# - array/string lengths: exactly n-1 edges
# - graph constraints: tree => connected + acyclic; also no self-loops; no multiple edges
# - special constraints: input must be whitespace-separated integers only


def parse_format(input_str: str) -> Tuple[bool, str, Dict[str, Any]]:
    s = input_str
    if s is None:
        return False, "FORMAT_INVALID: input is None", {}
    s = s.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input", {}

    tokens = s.split()
    # Must be all integers
