            u = ints[idx]
            v = ints[idx + 1]
            edges.append((u, v))
            idx += 2

    return True, "ok", {"n": n, "edges": edges}


def check_constraints(parsed: Dict[str, Any]) -> Tuple[bool, str]:
    n = parsed["n"]
    edges: List[Tuple[int, int]] = parsed["edges"]

    # Constraints from Codeforces 862B: 1 <= n <= 1e5
    if not (1 <= n <= 100000):
        return False, f"SPEC_INVALID: n out of bounds (1..100000), got {n}"

    if len(edges) != n - 1:
        return False, f"SPEC_INVALID: number of edges must be n-1={n-1}, got {len(edges)}"

    seen = set()
    adj: List[List[int]] = [[] for _ in range(n + 1)]

    for i, (u, v) in enumerate(edges, start=1):
        if not (1 <= u <= n) or not (1 <= v <= n):
            return False, f"SPEC_INVALID: edge {i} has endpoint out of range 1..n: ({u},{v})"
        if u == v:
