    vis2[1] = True
    while q:
        x = q.popleft()
        for y in adj[x]:
            if not vis2[y]:
                vis2[y] = True
                parent[y] = x
                q.append(y)
            elif parent[x] != y:
                return False, "SPEC_INVALID: graph contains a cycle (not a tree)"

    return True, "ok"


