import sys

def reflect(n: int) -> int:
    # reflection by digit complement to 9; leading zeros omitted automatically by int()
    return int(''.join(str(9 - (ord(c) - 48)) for c in str(n)))

def weight(n: int) -> int:
    return n * reflect(n)

def solve(l: int, r: int) -> int:
    # Candidate set:
    # - endpoints l, r
    # - numbers of the form 10^k - 1 (all 9s) within [l, r]
    # - numbers obtained by taking r and setting some suffix to 9s (to explore "near r")
    # This is a standard digit-DP boundary trick: maximum often occurs at r or just below
    # a prefix boundary with suffix all 9s.
    cand = {l, r}

    # all-9 numbers
    x = 9
    while x <= r:
        if x >= l:
            cand.add(x)
        x = x * 10 + 9

    # r with suffix replaced by 9s
    s = str(r)
    for i in range(1, len(s)):
        # replace last i digits with '9'
        t = s[:-i] + '9' * i
        v = int(t)
        if l <= v <= r:
            cand.add(v)

    # also consider same construction on l (sometimes beneficial near lower bound)
    s = str(l)
    for i in range(1, len(s)):
        t = s[:-i] + '0' * i  # smallest with that prefix; then clamp to >= l by adding
        v = int(t)
        # try v and v-1 with suffix 9s (closest below l's prefix boundary)
        if l <= v <= r:
            cand.add(v)
        v2 = v - 1
        if l <= v2 <= r:
            cand.add(v2)

    best = 0
    for n in cand:
        if n > 0:
            best = max(best, weight(n))
    return best

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    l, r = map(int, data[:2])
    print(solve(l, r))

if __name__ == "__main__":
    main()

