    idx += n

    # Queries: t lines, each with two ints; we validate by token count (whitespace-separated)
    if t < 0:
        return False, "FORMAT_INVALID: t must be an integer token (got negative t leading to ambiguous structure)", None

    need = 2 * t
    if len(tokens) < idx + need:
        return False, "FORMAT_INVALID: not enough integers for queries (need 2*t integers)", None

    queries: List[Tuple[int, int]] = []
    for qi in range(t):
        tl = tokens[idx + 2 * qi]
        tr = tokens[idx + 2 * qi + 1]
        if not _is_int_token(tl) or not _is_int_token(tr):
            return False, f"FORMAT_INVALID: query {qi+1} must contain two integers l r", None
        try:
            l = int(tl)
            r = int(tr)
        except Exception:
            return False, f"FORMAT_INVALID: failed to parse l/r in query {qi+1}", None
        queries.append((l, r))
    idx += need

    if idx != len(tokens):
        return False, "FORMAT_INVALID: extra tokens after reading n, array, and t queries", None

    return True, "ok", {"n": n, "t": t, "a": a, "queries": queries}


