MOD = 10**9 + 7

def mod_pow(a, e, mod=MOD):
    return pow(a, e, mod)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    x = int(data[0])
    y = int(data[1])

    if y % x != 0:
        print(0)
        return

    n = y // x
    if n == 1:
        # Only possible sequence is [x], gcd is x, lcm is x
        print(1)
        return

    # Factorize n
    factors = []
    tmp = n
    p = 2
    while p * p <= tmp:
        if tmp % p == 0:
            cnt = 0
            while tmp % p == 0:
                tmp //= p
                cnt += 1
            factors.append((p, cnt))
        p += 1 if p == 2 else 2  # small optimization: after 2, only odd
    if tmp > 1:
        factors.append((tmp, 1))

    # Inclusion-exclusion over square-free products of distinct primes in n:
    # Count of sequences for given n equals sum_{d | rad(n)} mu(d) * 2^{(n/d)-1}
    primes = [p for p, _ in factors]
    m = len(primes)

    ans = 0
    for mask in range(1 << m):
        d = 1
        bits = 0
        for i in range(m):
            if mask >> i & 1:
                d *= primes[i]
                bits += 1
        term = mod_pow(2, n // d - 1)
        if bits % 2 == 0:
            ans = (ans + term) % MOD
        else:
            ans = (ans - term) % MOD

    print(ans % MOD)

