import sys

def can_make(x: int, a: int, b: int, n: int) -> bool:
    # With minimum x per plate, cake A can serve at most a//x plates,
    # cake B can serve at most b//x plates. Need total >= n.
    return (a // x) + (b // x) >= n

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, b, n = map(int, data[:3])

    lo, hi = 1, (a + b) // n  # x cannot exceed average pieces per plate
    ans = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_make(mid, a, b, n):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1

    sys.stdout.write(str(ans))

