_NAME_RE = re.compile(r"^[a-z]+$")
_COMMAND_RE = re.compile(r"^[a-z]+$")
_INT_RE = re.compile(r"^[0-9]+$")


def _parse_int(tok: str):
    if not _INT_RE.fullmatch(tok):
        return None
    return int(tok)


def _valid_ip(ip: str) -> bool:
    parts = ip.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        if part == "":
            return False
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        value = int(part)
        if value > 255:
            return False

    return True


def validate_input(inp: str) -> Tuple[bool, str]:
    if not isinstance(inp, str):
        return False, "FORMAT_INVALID: input is not a string"

    tokens = inp.split()
    if len(tokens) < 2:
        return False, "FORMAT_INVALID: missing n and m"

    n = _parse_int(tokens[0])
    m = _parse_int(tokens[1])
    if n is None or m is None:
        return False, "FORMAT_INVALID: n and m must be integers"

    if not (1 <= n <= 1000):
        return False, "SPEC_INVALID: n out of range"
    if not (1 <= m <= 1000):
        return False, "SPEC_INVALID: m out of range"

    expected_tokens = 2 + 2 * n + 2 * m
    if len(tokens) != expected_tokens:
        return False, "FORMAT_INVALID: wrong number of tokens"

    idx = 2
    ips = set()

    for i in range(n):
        name = tokens[idx]
        ip = tokens[idx + 1]
        idx += 2

        if not _NAME_RE.fullmatch(name):
            return False, f"FORMAT_INVALID: invalid server name at entry {i + 1}"

        if not _valid_ip(ip):
            return False, f"FORMAT_INVALID: invalid server ip at entry {i + 1}"

        if ip in ips:
            return False, f"SPEC_INVALID: duplicate server ip at entry {i + 1}"

        ips.add(ip)

    for j in range(m):
        command = tokens[idx]
        ip_semicolon = tokens[idx + 1]
        idx += 2

        if not _COMMAND_RE.fullmatch(command):
            return False, f"FORMAT_INVALID: invalid command at entry {j + 1}"

        if not ip_semicolon.endswith(";"):
            return False, f"FORMAT_INVALID: command ip missing semicolon at entry {j + 1}"

        ip = ip_semicolon[:-1]
        if not _valid_ip(ip):
            return False, f"FORMAT_INVALID: invalid command ip at entry {j + 1}"

        if ip not in ips:
            return False, f"SPEC_INVALID: command ip is not one of the server ips at entry {j + 1}"

    return True, "OK"

from __future__ import annotations

def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validates input for Codeforces 920A - Water The Garden.

    Expected format:
      t
      n k
      x1 x2 ... xk
      (repeat t times)

    Typical CF constraints for this problem:
      1 <= t <= 1000 (commonly)
      1 <= k <= n
      1 <= xi <= n

    We enforce the structural/spec essentials and reasonable CF-style bounds:
      - integers only
      - exactly 2 + k integers per test case after reading n,k
      - 1 <= t
      - 1 <= n
      - 1 <= k <= n
      - each xi in [1, n]
    We do NOT require xi to be distinct or sorted (problem doesn't require it).
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    s = inp.strip()
    if not s:
        return (False, "FORMAT_INVALID: empty input")

    tokens = s.split()
    try:
        vals = [int(tok) for tok in tokens]
    except ValueError:
        return (False, "FORMAT_INVALID: non-integer token present")

    idx = 0
    if idx >= len(vals):
        return (False, "FORMAT_INVALID: missing t")
    t = vals[idx]
    idx += 1

    if t <= 0:
        return (False, "SPEC_INVALID: t must be >= 1")

    # Parse t test cases
    for case in range(1, t + 1):
        if idx + 1 >= len(vals):
            return (False, f"FORMAT_INVALID: missing n k for test case {case}")
        n = vals[idx]
        k = vals[idx + 1]
        idx += 2

        if n <= 0:
            return (False, f"SPEC_INVALID: n must be >= 1 in test case {case}")
        if k <= 0:
            return (False, f"SPEC_INVALID: k must be >= 1 in test case {case}")
        if k > n:
            return (False, f"SPEC_INVALID: k must be <= n in test case {case}")

        if idx + k > len(vals):
            return (False, f"FORMAT_INVALID: missing {k} tap positions in test case {case}")

        xs = vals[idx:idx + k]
        idx += k

        for pos in xs:
            if pos < 1 or pos > n:
                return (False, f"SPEC_INVALID: tap position {pos} out of [1, n]={n} in test case {case}")

    if idx != len(vals):
        return (False, "FORMAT_INVALID: extra trailing tokens after parsing all test cases")

    return (True, "OK")

