import sys
sys.setrecursionlimit(1_000_000)

def build_spf(limit: int):
    spf = list(range(limit + 1))
    for i in range(2, int(limit ** 0.5) + 1):
        if spf[i] == i:
            step = i
            start = i * i
            for j in range(start, limit + 1, step):
                if spf[j] == j:
                    spf[j] = i
    return spf

def num_divisors(x: int, spf):
    if x <= 1:
        return 1
    res = 1
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        res *= (cnt + 1)
    return res

class Fenwick:
    __slots__ = ("n", "bit")
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, delta):
        n = self.n
        bit = self.bit
        while i <= n:
            bit[i] += delta
            i += i & -i

    def sum(self, i):
        s = 0
        bit = self.bit
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    def range_sum(self, l, r):
        return self.sum(r) - self.sum(l - 1)

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [0] * (n + 1)
    maxa = 0
    for i in range(1, n + 1):
        v = int(next(it))
        a[i] = v
        if v > maxa:
            maxa = v

    spf = build_spf(maxa)

    fw = Fenwick(n)
    for i in range(1, n + 1):
        fw.add(i, a[i])

    # DSU "next" pointers to skip stable positions (a[i] <= 2 => D(a[i]) == a[i])
    parent = list(range(n + 2))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i in range(1, n + 1):
        if a[i] <= 2:
            parent[i] = i + 1
    parent[n + 1] = n + 1

    out = []
    for _ in range(m):
        t = next(it).decode()
        l = int(next(it)); r = int(next(it))
        if t[0] == '1':  # REPLACE
            i = find(l)
            while i <= r:
                old = a[i]
                new = num_divisors(old, spf)
                if new != old:
                    a[i] = new
                    fw.add(i, new - old)
                if a[i] <= 2:
                    parent[i] = i + 1
                i = find(i + 1)
        else:  # SUM
            out.append(str(fw.range_sum(l, r)))

    sys.stdout.write("\n".join(out))

