    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    toks = s.split()
    if not toks:
        return False, "FORMAT_INVALID: empty token stream"

    # Parse n
    try:
        n = int(toks[0])
    except Exception:
        return False, "FORMAT_INVALID: n is not an integer"

    if n <= 0:
        return False, "SPEC_INVALID: n must be positive"
    if n > 200000:
        return False, "SPEC_INVALID: n exceeds 200000"

    expected = 1 + 2 * n
    if len(toks) != expected:
        return False, f"FORMAT_INVALID: expected {expected} integers total, got {len(toks)}"

    # Parse arrays
