    T = []
    idx = 1
    try:
        for _ in range(n):
            V.append(int(toks[idx]))
            idx += 1
        for _ in range(n):
            T.append(int(toks[idx]))
            idx += 1
    except Exception:
        return False, "FORMAT_INVALID: failed to parse V/T arrays as integers"

    # Spec checks
    # (CF allows 0 as well; negatives don't make sense)
    for i, v in enumerate(V, 1):
        if v < 0:
            return False, f"SPEC_INVALID: V[{i}] is negative"
        if v > 10**9:
