import re
from typing import Tuple

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces problem "Mystical Mosaic" (cf_924_A).

    Expected format (standard CF):
        n m
        n lines each with a string of length m consisting of '.' and '#'

    Returns:
        (True, "OK") if input is valid
        (False, "FORMAT_INVALID: ...") for parsing/format issues
        (False, "SPEC_INVALID: ...") for out-of-spec values/content
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp
    # Allow trailing whitespace, but don't allow leading garbage before first token.
    s_stripped = s.strip()
    if s_stripped == "":
        return False, "FORMAT_INVALID: empty input"

    tokens = s_stripped.split()
    if len(tokens) < 2:
        return False, "FORMAT_INVALID: expected at least two integers n and m"

    # Parse n, m
    def parse_int(tok: str):
        if not re.fullmatch(r"[+-]?\d+", tok or ""):
            return None
        try:
            return int(tok)
        except Exception:
            return None

    n = parse_int(tokens[0])
    m = parse_int(tokens[1])
    if n is None or m is None:
        return False, "FORMAT_INVALID: n and m must be integers"

    if n <= 0 or m <= 0:
        return False, "SPEC_INVALID: n and m must be positive"

    # CF typical constraints are up to 50/1000 etc; statement embedding omitted.
    # We only enforce basic positivity and consistency with provided grid.
    # Remaining tokens should encode exactly n grid rows as single tokens (no spaces inside).
    grid_tokens = tokens[2:]
    if len(grid_tokens) != n:
        return False, f"FORMAT_INVALID: expected exactly {n} grid rows, got {len(grid_tokens)}"

    allowed = {'.', '#'}
    for i, row in enumerate(grid_tokens, start=1):
        if len(row) != m:
            return False, f"FORMAT_INVALID: row {i} length {len(row)} != m ({m})"
        bad = [ch for ch in row if ch not in allowed]
        if bad:
            return False, f"SPEC_INVALID: row {i} contains invalid characters (allowed '.' and '#')"

    # Ensure there's no extra non-whitespace content beyond parsed tokens.
    # Since we used split() on stripped input, any extra content would be in tokens already.
    return True, "OK"

