import re
from typing import Tuple

_INT_RE = re.compile(r"[+-]?\d+\Z")

MAX_NM = 10**6
MAX_V = 10**6
MAX_TRANSPORT = 10**5
MAX_Q = 10**5


def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 925A - Stairs and Elevators.

    Expected input:
        n m cl ce v
        cl integers: stair positions, strictly increasing
        ce integers: elevator positions, strictly increasing
        q
        q lines/tuples: x1 y1 x2 y2

    Official constraints enforced:
        2 <= n, m <= 1e6
        0 <= cl, ce
        1 <= cl + ce <= 1e5
        1 <= v <= 1e6
        stair/elevator positions are in [1, m]
        positions in each list are strictly increasing
        stairs and elevators do not occupy the same section column
        1 <= q <= 1e5
        query coordinates are in bounds
        queried sections must be rooms, i.e. not occupied by stairs/elevators
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    tokens = inp.split()
    if not tokens:
        return False, "FORMAT_INVALID: empty input"

    for tok in tokens:
        if _INT_RE.fullmatch(tok) is None:
            return False, f"FORMAT_INVALID: non-integer token '{tok}'"

    try:
        vals = [int(tok) for tok in tokens]
    except Exception:
        return False, "FORMAT_INVALID: failed to parse integer token"

    idx = 0

    def remaining() -> int:
        return len(vals) - idx

    def take(name: str) -> int:
        nonlocal idx
        if idx >= len(vals):
            raise IndexError(name)
        x = vals[idx]
        idx += 1
        return x

    if remaining() < 5:
        return False, "FORMAT_INVALID: incomplete header"

    try:
        n = take("n")
        m = take("m")
        cl = take("cl")
        ce = take("ce")
        v = take("v")
    except IndexError:
        return False, "FORMAT_INVALID: incomplete header"

    if not (2 <= n <= MAX_NM):
        return False, "SPEC_INVALID: n out of range [2, 1e6]"
    if not (2 <= m <= MAX_NM):
        return False, "SPEC_INVALID: m out of range [2, 1e6]"
    if cl < 0:
        return False, "SPEC_INVALID: cl must be non-negative"
    if ce < 0:
        return False, "SPEC_INVALID: ce must be non-negative"
    if not (1 <= cl + ce <= MAX_TRANSPORT):
        return False, "SPEC_INVALID: cl + ce out of range [1, 1e5]"
    if not (1 <= v <= MAX_V):
        return False, "SPEC_INVALID: v out of range [1, 1e6]"

    if remaining() < cl:
        return False, "FORMAT_INVALID: not enough stair positions"

    stairs = []
    for _ in range(cl):
        stairs.append(take("stair_position"))

    for i, x in enumerate(stairs):
        if not (1 <= x <= m):
            return False, "SPEC_INVALID: stair position out of range [1, m]"
        if i > 0 and stairs[i - 1] >= x:
            return False, "SPEC_INVALID: stair positions must be strictly increasing"

    if remaining() < ce:
        return False, "FORMAT_INVALID: not enough elevator positions"

    elevators = []
    for _ in range(ce):
        elevators.append(take("elevator_position"))

    for i, x in enumerate(elevators):
        if not (1 <= x <= m):
            return False, "SPEC_INVALID: elevator position out of range [1, m]"
        if i > 0 and elevators[i - 1] >= x:
            return False, "SPEC_INVALID: elevator positions must be strictly increasing"

    occupied = set(stairs)
    for x in elevators:
        if x in occupied:
            return False, "SPEC_INVALID: stair and elevator positions must be disjoint"
        occupied.add(x)

    if remaining() < 1:
        return False, "FORMAT_INVALID: missing q"

    q = take("q")
    if not (1 <= q <= MAX_Q):
        return False, "SPEC_INVALID: q out of range [1, 1e5]"

    needed = 4 * q
    if remaining() < needed:
        return False, "FORMAT_INVALID: not enough query integers"
    if remaining() > needed:
        return False, "FORMAT_INVALID: extra trailing tokens"

    for _ in range(q):
        x1 = take("x1")
        y1 = take("y1")
        x2 = take("x2")
        y2 = take("y2")

        if not (1 <= x1 <= n) or not (1 <= x2 <= n):
            return False, "SPEC_INVALID: query floor out of range [1, n]"
        if not (1 <= y1 <= m) or not (1 <= y2 <= m):
            return False, "SPEC_INVALID: query section out of range [1, m]"
        if y1 in occupied or y2 in occupied:
            return False, "SPEC_INVALID: query endpoint is not a room"

    if idx != len(vals):
        return False, "FORMAT_INVALID: trailing tokens"

    return True, "OK"

