import sys
import bisect

def generate_23_numbers(limit: int):
    nums = set()
    p2 = 1
    while p2 <= limit:
        p3 = 1
        while p2 * p3 <= limit:
            nums.add(p2 * p3)
            p3 *= 3
        p2 *= 2
    return sorted(nums)

def main():
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    l, r = data[0], data[1]
    if l > r:
        l, r = r, l

    arr = generate_23_numbers(r)

    left = bisect.bisect_left(arr, l)
    right = bisect.bisect_right(arr, r)
    print(right - left)

if __name__ == "__main__":
    main()

