import sys


def is_zebra(s: str) -> bool:
    # s is a string of '0'/'1'
    if not s:
        return False

    # Compute lengths of consecutive equal blocks
    runs = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            runs.append(cnt)
            cur = ch
            cnt = 1
    runs.append(cnt)

    # A zebra must have all stripes of equal width
    w = runs[0]
    for r in runs[1:]:
        if r != w:
            return False
    return True


def main() -> None:
    data = sys.stdin.read().split()
    if not data:
        return

    # Codeforces variants: either (n, string) or just string
    if len(data) == 1:
        s = data[0].strip()
    else:
        # most likely: n then s
        s = data[1].strip()

    sys.stdout.write("YES\n" if is_zebra(s) else "NO\n")


if __name__ == "__main__":
    main()

