    # Accept a final newline after the line.
    s = input_str
    if s == "":
        return False, "FORMAT_INVALID: empty input"

    # Normalize line endings
    s = s.replace("\r\n", "\n").replace("\r", "\n")

    lines = s.split("\n")
    # Allow exactly one trailing empty line (common in files ending with newline)
    if len(lines) >= 2 and lines[-1] == "":
        lines = lines[:-1]

    if len(lines) != 1:
        return False, f"FORMAT_INVALID: expected exactly 1 line, got {len(lines)}"

    line = lines[0]
    if line.strip() == "":
        return False, "FORMAT_INVALID: line is empty/whitespace"

    tokens = line.split()
    if len(tokens) != 1:
        return False, f"FORMAT_INVALID: expected exactly 1 token, got {len(tokens)}"

    token = tokens[0]
    return True, {"s": token}


