def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validates input for CF 931B - World Cup.
    Expected format: three integers n a b.
    Spec: n is a power of two (since every round has even #teams until final),
          and 1 <= a,b <= n, a != b.
    """
    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    parts = re.split(r"\s+", s)
    if len(parts) != 3:
        return False, "FORMAT_INVALID: expected exactly 3 integers (n a b)"

