        return False, "SPEC_INVALID: n must be >= 2"
    if a < 1 or a > n or b < 1 or b > n:
        return False, "SPEC_INVALID: a and b must satisfy 1 <= a,b <= n"
    if a == b:
        return False, "SPEC_INVALID: a and b must be distinct"

    # n must be a power of two for a standard knockout bracket as described.
    if n & (n - 1) != 0:
        return False, "SPEC_INVALID: n must be a power of two"

    return True, "OK"

from __future__ import annotations

from typing import Any, Dict, List, Tuple

# Checks:
# - exact line/token structure: first two ints are n m; then exactly n ints for a; exactly m ints for b; no extra tokens
# - numeric bounds: 1 <= n,m <= 50 (CF 934A); element bounds not explicitly given in prompt -> not enforced
# - array/string lengths: exactly n and m values
# - graph constraints: none
# - special constraints: none (although statement narrative shows sorted with <=, official CF input does NOT require sorted;
#   existing tests include unsorted arrays, so enforcing non-decreasing would conflict with official tests)

N_MIN = 1
N_MAX = 50


def parse_format(input_str: str) -> Tuple[bool, Any]:
    if input_str is None:
        return False, "FORMAT_INVALID: input is None"
    if input_str == "":
        return False, "FORMAT_INVALID: empty input"

    # Tokenize by any whitespace; CF inputs allow arbitrary line breaks for arrays.
    tokens = input_str.split()
    if not tokens:
        return False, "FORMAT_INVALID: empty input"

    # Need at least n,m plus one value in each array => at least 4 tokens
    if len(tokens) < 4:
        return False, "FORMAT_INVALID: insufficient tokens; expected at least 4 tokens (n m a.. b..)"

    # Parse n, m
    try:
        n = int(tokens[0])
        m = int(tokens[1])
    except ValueError:
        return False, "FORMAT_INVALID: n and m must be integers"

    idx = 2
    # For format validity, n and m must be positive enough to read arrays
    if n < 0 or m < 0:
        # Negative values are structurally fine integers, but make the remaining structure impossible.
        return False, "FORMAT_INVALID: n and m must be non-negative integers"

    # Check enough tokens for arrays
    if len(tokens) != 2 + n + m:
        return (
            False,
            f"FORMAT_INVALID: expected exactly {2+n+m} tokens total (n m + n a-values + m b-values), got {len(tokens)}",
        )

    a: List[int] = []
    b: List[int] = []

    for i in range(n):
        try:
            a.append(int(tokens[idx + i]))
        except ValueError:
            return False, f"FORMAT_INVALID: a[{i+1}] is not an integer"
    idx += n

    for j in range(m):
        try:
            b.append(int(tokens[idx + j]))
        except ValueError:
            return False, f"FORMAT_INVALID: b[{j+1}] is not an integer"

    parsed: Dict[str, Any] = {"n": n, "m": m, "a": a, "b": b}
    return True, parsed


def check_constraints(parsed: Dict[str, Any]) -> Tuple[bool, str]:
    n = parsed["n"]
    m = parsed["m"]

    if not (N_MIN <= n <= N_MAX):
        return False, f"SPEC_INVALID: n out of bounds, expected {N_MIN}..{N_MAX}, got {n}"
    if not (N_MIN <= m <= N_MAX):
        return False, f"SPEC_INVALID: m out of bounds, expected {N_MIN}..{N_MAX}, got {m}"

    # Note about sortedness:
    # The statement text in the prompt shows "a1<=a2<=...<=an" and "b1<=...<=bm", but CF 934A input does not
    # guarantee sorted arrays; existing official tests include unsorted inputs. Therefore, we must not enforce it.

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, res = parse_format(input_str)
    if not ok:
        return False, res
    ok2, msg = check_constraints(res)
    if not ok2:
        return False, msg if msg.startswith("SPEC_INVALID:") else ("SPEC_INVALID: " + msg)
    return True, "ok"

