from typing import Tuple

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validates input for Codeforces 935B - Fafa and the Gates.

    Expected format:
      n
      S

    Where:
      - n is an integer
      - S is a string of length n consisting only of 'U' and 'R'
    """
    if inp is None:
        return (False, "FORMAT_INVALID: input is None")

    s = inp

    # Allow trailing whitespace/newlines, but not leading junk before first token.
    # We'll parse as whitespace-separated tokens, but also ensure there are exactly 2 tokens.
    tokens = s.split()
    if len(tokens) != 2:
        return (False, "FORMAT_INVALID: expected exactly 2 tokens (n and S)")

    n_str, moves = tokens

    if not re.fullmatch(r"[+-]?\d+", n_str):
        return (False, "FORMAT_INVALID: n is not a valid integer")

    try:
        n = int(n_str)
    except Exception:
        return (False, "FORMAT_INVALID: cannot parse n as int")

    if n < 0:
        return (False, "SPEC_INVALID: n must be non-negative")

    # In the original problem, n is the number of moves; typically n>=1.
    # We'll accept n=0 only if moves is empty, but empty token cannot appear with split().
    # So effectively n should be >= 1 in standard CF format.
    if n == 0:
        return (False, "SPEC_INVALID: n=0 cannot be represented with a moves token")

    if len(moves) != n:
        return (False, "SPEC_INVALID: length of S must equal n")

    # Only U and R are allowed
    bad = set(moves) - {"U", "R"}
    if bad:
        return (False, "SPEC_INVALID: S contains invalid characters (only 'U' and 'R')")

    return (True, "OK")

