import re
from typing import Tuple

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 958B2 (Maximum Control - medium).

    Expected format:
      N
      u1 v1
      u2 v2
      ...
      u_{N-1} v_{N-1}

    Constraints (from statement essence: tree):
      - N is an integer, typically N >= 1
      - Exactly N-1 edges follow if N > 1
      - Vertices are 1..N
      - Edges are undirected; self-loops disallowed
      - Graph must be a tree: connected and acyclic
    """
    s = inp.strip()
    if s == "":
        return False, "FORMAT_INVALID: empty input"

    # Tokenize by whitespace; enforce integers only
    toks = s.split()
    for t in toks:
        if not re.fullmatch(r"-?\d+", t):
            return False, f"FORMAT_INVALID: non-integer token '{t}'"

    vals = list(map(int, toks))
    if len(vals) < 1:
        return False, "FORMAT_INVALID: missing N"

    n = vals[0]
    if n <= 0:
        return False, "SPEC_INVALID: N must be positive"

    # Need exactly 1 + 2*(N-1) integers
    expected = 1 + 2 * max(0, n - 1)
    if len(vals) != expected:
        return (
            False,
            f"FORMAT_INVALID: expected {expected} integers (N plus 2*(N-1) for edges), got {len(vals)}"
        )

    # If N == 1, no edges, always valid.
    if n == 1:
        return True, "OK"

    # Parse edges
    edges = []
    idx = 1
    for i in range(n - 1):
        u = vals[idx]
        v = vals[idx + 1]
        idx += 2

        if not (1 <= u <= n) or not (1 <= v <= n):
            return False, f"SPEC_INVALID: vertex id out of range in edge {i+1}: ({u}, {v})"
        if u == v:
            return False, f"SPEC_INVALID: self-loop at vertex {u}"

        edges.append((u, v))

    # Check tree property: connected + acyclic (for n nodes and n-1 edges, equivalent to connected)
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> bool:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True

    for i, (u, v) in enumerate(edges, 1):
        if not union(u, v):
            return False, f"SPEC_INVALID: cycle detected when adding edge {i}: ({u}, {v})"

    root = find(1)
    for node in range(2, n + 1):
        if find(node) != root:
            return False, "SPEC_INVALID: graph is not connected (not a tree)"

    return True, "OK"

