from typing import Tuple

_INT_RE = re.compile(r'^[+-]?\d+$')

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 960F - Pathwalks.

    Expected format:
      n m
      a_1 b_1 w_1
      ...
      a_m b_m w_m

    Constraints:
      1 <= n, m <= 300000
      1 <= a_i, b_i <= n
      1 <= w_i <= 10^9

    Multiple edges and self-loops are allowed.
    """
    if not isinstance(inp, str):
        return False, "FORMAT_INVALID: input is not a string"

    if inp.strip() == "":
        return False, "FORMAT_INVALID: input is empty"

    tokens = inp.split()

    for i, tok in enumerate(tokens):
        if not _INT_RE.match(tok):
            return False, f"FORMAT_INVALID: token {i + 1} is not an integer"

    if len(tokens) < 2:
        return False, "FORMAT_INVALID: missing n and/or m"

    try:
        n = int(tokens[0])
        m = int(tokens[1])
    except Exception:
        return False, "FORMAT_INVALID: failed to parse n and m"

    if not (1 <= n <= 300000):
        return False, "SPEC_INVALID: n must satisfy 1 <= n <= 300000"

    if not (1 <= m <= 300000):
        return False, "SPEC_INVALID: m must satisfy 1 <= m <= 300000"

    expected_tokens = 2 + 3 * m
    if len(tokens) != expected_tokens:
        return (
            False,
            f"FORMAT_INVALID: expected {expected_tokens} integers, got {len(tokens)}"
        )

    pos = 2
    for edge_idx in range(1, m + 1):
        a = int(tokens[pos])
        b = int(tokens[pos + 1])
        w = int(tokens[pos + 2])
        pos += 3

        if not (1 <= a <= n):
            return False, f"SPEC_INVALID: edge {edge_idx} has vertex a outside [1, n]"

        if not (1 <= b <= n):
            return False, f"SPEC_INVALID: edge {edge_idx} has vertex b outside [1, n]"

        if not (1 <= w <= 10**9):
            return False, f"SPEC_INVALID: edge {edge_idx} has weight outside [1, 10^9]"

    return True, "OK"

