import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = int(data[1])  # programmers
    b = int(data[2])  # athletes
    s = data[3].strip()

    # Greedy: traverse seats left to right.
    # For each empty seat '.', place a student different from previous placed student,
    # choosing the type with larger remaining count to maximize future options.
    prev = 0  # 0 = none/blocked, 1 = programmer, 2 = athlete
    ans = 0

    for ch in s:
        if ch == '*':
            prev = 0
            continue

        # ch == '.'
        if prev == 1:
            # Can't place programmer
            if b > 0:
                b -= 1
                prev = 2
                ans += 1
            else:
                prev = 0
        elif prev == 2:
            # Can't place athlete
            if a > 0:
                a -= 1
                prev = 1
                ans += 1
            else:
                prev = 0
        else:
            # prev == 0, can place either; choose the one with more remaining
            if a >= b:
                if a > 0:
                    a -= 1
                    prev = 1
                    ans += 1
                elif b > 0:
                    b -= 1
                    prev = 2
                    ans += 1
                else:
                    prev = 0
            else:
                if b > 0:
                    b -= 1
                    prev = 2
                    ans += 1
                elif a > 0:
                    a -= 1
                    prev = 1
                    ans += 1
                else:
                    prev = 0

    sys.stdout.write(str(ans))

