    def parse_int(tok: str, name: str) -> Tuple[bool, str, int]:
        try:
            # Disallow things like '01'? CF typically allows, but it's still an int.
            # We'll accept Python int format as long as it's base-10 (no 0x, 1e3).
            if tok.startswith(("+", "-")):
