                {},
            )
        else:
            return (
                False,
                f"FORMAT_INVALID: extra tokens after reading n, K and {n} sizes",
                {},
            )

    a: List[int] = []
    for i in range(n):
        ok, msg, val = parse_int(tokens[2 + i], f"a[{i}]")
        if not ok:
            return False, msg, {}
        a.append(val)

    return True, "ok", {"n": n, "K": K, "a": a}


def check_constraints(parsed: Dict[str, Any]) -> Tuple[bool, str]:
    n = parsed["n"]
    K = parsed["K"]
    a = parsed["a"]

