    if not (1 <= K <= 1_000_000):
        return False, f"SPEC_INVALID: K out of bounds (1..1000000), got {K}"
    if len(a) != n:
        return False, f"SPEC_INVALID: expected array length {n}, got {len(a)}"
    for i, val in enumerate(a):
