    m = read_int()
    if m < 0:
        return False, "SPEC_INVALID: m must be non-negative"

    # Read m pairs
    if not need(2 * m):
        return False, "FORMAT_INVALID: not enough numbers for m pairs"
    for j in range(m):
        c = read_int()
        d = read_int()
        if not (1 <= c <= 9 and 1 <= d <= 9):
            return False, f"SPEC_INVALID: pair {j+1} of second list has numbers not in [1..9]"
        if c == d:
            return False, f"SPEC_INVALID: pair {j+1} of second list has equal numbers"

    # No extra tokens allowed
    if idx != len(tokens):
        return False, "FORMAT_INVALID: extra integer tokens at end"

    return True, "OK"

