from collections import Counter
from typing import Tuple

_INT_RE = re.compile(r"^[+-]?\d+$")

def validate_input(inp: str) -> Tuple[bool, str]:
    """
    Validator for Codeforces 995B - Suit and Tie.

    Expected input:
      n
      a1 a2 ... a(2n)

    Constraints:
      1 <= n <= 100
      each ai is in [1, n]
      every number from 1 to n appears exactly twice
    """
    if not isinstance(inp, str):
        return False, "FORMAT_INVALID: input is not a string"

    tokens = inp.split()
    if not tokens:
        return False, "FORMAT_INVALID: empty input"

    for tok in tokens:
        if not _INT_RE.fullmatch(tok):
            return False, f"FORMAT_INVALID: non-integer token {tok!r}"

    nums = [int(tok) for tok in tokens]
    n = nums[0]

    if not (1 <= n <= 100):
        return False, "SPEC_INVALID: n must satisfy 1 <= n <= 100"

    expected_tokens = 1 + 2 * n
    if len(nums) != expected_tokens:
        return (
            False,
            f"FORMAT_INVALID: expected {expected_tokens} integers, got {len(nums)}"
        )

    arr = nums[1:]

    for x in arr:
        if not (1 <= x <= n):
            return False, "SPEC_INVALID: all person labels must be in range [1, n]"

    cnt = Counter(arr)
    for x in range(1, n + 1):
        if cnt[x] != 2:
            return False, "SPEC_INVALID: each label from 1 to n must appear exactly twice"

    return True, "OK"

