from __future__ import annotations

def validate_input(inp: str) -> tuple[bool, str]:
    """
    Validates input for Codeforces 999A - Mishka and Contest.

    Expected format:
      n k
      a1 a2 ... an

    Constraints (spec):
      1 <= n <= 100
      1 <= k <= 100
      1 <= ai <= 100
    """
    if inp is None:
        return False, "FORMAT_INVALID: input is None"

    s = inp.strip()
    if not s:
        return False, "FORMAT_INVALID: empty input"

    # Tokenize by whitespace; CF accepts arbitrary whitespace/newlines
    toks = s.split()
    if len(toks) < 2:
        return False, "FORMAT_INVALID: expected at least two integers (n k)"

    def parse_int(tok: str, name: str) -> tuple[bool, int, str]:
        try:
            # Disallow non-integer representations (e.g., "1.0")
            if tok.strip() != tok:
                return False, 0, f"FORMAT_INVALID: unexpected whitespace in {name}"
            v = int(tok)
            return True, v, ""
        except Exception:
            return False, 0, f"FORMAT_INVALID: {name} is not an integer"

    ok, n, msg = parse_int(toks[0], "n")
    if not ok:
        return False, msg
    ok, k, msg = parse_int(toks[1], "k")
    if not ok:
        return False, msg

    if n < 1 or n > 100:
        return False, "SPEC_INVALID: n out of range [1, 100]"
    if k < 1 or k > 100:
        return False, "SPEC_INVALID: k out of range [1, 100]"

    # Need exactly n integers for difficulties, but allow extra whitespace only.
    if len(toks) != 2 + n:
        if len(toks) < 2 + n:
            return False, f"FORMAT_INVALID: expected {n} difficulty integers, got {len(toks) - 2}"
        else:
            return False, f"FORMAT_INVALID: too many tokens; expected {2+n}, got {len(toks)}"

    for i in range(n):
        ok, ai, msg = parse_int(toks[2 + i], f"a[{i}]")
        if not ok:
            return False, msg
        if ai < 1 or ai > 100:
            return False, "SPEC_INVALID: difficulty out of range [1, 100]"

    return True, "OK"

from typing import Tuple, List, Dict, Any

# Checks:
# - exact line/token structure: first line "n m s" (3 ints), then exactly m lines each with "u v" (2 ints), no extra tokens/lines
# - numeric bounds: 1<=n<=5000, 0<=m<=10000, 1<=s<=n, 1<=u,v<=n
# - array/string lengths: exactly m edges provided
# - graph constraints: directed edges; no additional constraints (self-loops/duplicates allowed since not forbidden)
# - special constraints: disallow empty input; enforce whitespace-only trailing allowed

def parse_format(input_str: str) -> Tuple[bool, str, Dict[str, Any]]:
    if input_str is None:
        return False, "FORMAT_INVALID: input is None", {}

    s = input_str
    if s.strip() == "":
        return False, "FORMAT_INVALID: empty input", {}

    # Split into lines, tolerate trailing whitespace/newline
    lines = s.splitlines()
    # If there are leading/trailing empty lines, that's still "lines"; format expects meaningful first line.
    # We'll strip only for checking emptiness; parse uses tokenization per line.
    if len(lines) == 0:
        return False, "FORMAT_INVALID: no lines", {}

    # Find first non-empty line? CF inputs won't have blank first line; treat blank as format error.
    if lines[0].strip() == "":
        return False, "FORMAT_INVALID: first line is empty", {}

    first_tokens = lines[0].split()
    if len(first_tokens) != 3:
        return False, f"FORMAT_INVALID: first line must have 3 integers (n m s), got {len(first_tokens)} token(s)", {}
    try:
        n = int(first_tokens[0])
        m = int(first_tokens[1])
        cap = int(first_tokens[2])
    except ValueError:
        return False, "FORMAT_INVALID: first line contains non-integer token(s)", {}

    expected_lines = 1 + m
    if len(lines) != expected_lines:
        return False, f"FORMAT_INVALID: expected {expected_lines} line(s) total (1 + m), got {len(lines)}", {}

    edges: List[tuple[int, int]] = []
    for i in range(1, expected_lines):
        if lines[i].strip() == "":
            return False, f"FORMAT_INVALID: edge line {i+1} is empty", {}
        toks = lines[i].split()
        if len(toks) != 2:
            return False, f"FORMAT_INVALID: edge line {i+1} must have 2 integers (u v), got {len(toks)} token(s)", {}
        try:
            u = int(toks[0])
            v = int(toks[1])
        except ValueError:
            return False, f"FORMAT_INVALID: edge line {i+1} contains non-integer token(s)", {}
        edges.append((u, v))

    parsed = {"n": n, "m": m, "s": cap, "edges": edges}
    return True, "ok", parsed


def check_constraints(parsed: Dict[str, Any]) -> Tuple[bool, str]:
    n = parsed["n"]
    m = parsed["m"]
    s = parsed["s"]
    edges = parsed["edges"]

    # Explicit constraints from CF 999E:
    # n (1..5000), m (0..10000), s (1..n)
    if not (1 <= n <= 5000):
        return False, f"SPEC_INVALID: n out of bounds (1..5000), got {n}"
    if not (0 <= m <= 10000):
        return False, f"SPEC_INVALID: m out of bounds (0..10000), got {m}"
    if not (1 <= s <= n):
        return False, f"SPEC_INVALID: capital s out of bounds (1..n), got s={s}, n={n}"

    if len(edges) != m:
        # Should be impossible if parse_format is correct, but keep for robustness.
        return False, f"SPEC_INVALID: expected exactly m={m} edges, got {len(edges)}"

    for idx, (u, v) in enumerate(edges, start=1):
        if not (1 <= u <= n):
            return False, f"SPEC_INVALID: edge {idx} has u out of bounds (1..n), u={u}, n={n}"
        if not (1 <= v <= n):
            return False, f"SPEC_INVALID: edge {idx} has v out of bounds (1..n), v={v}, n={n}"
        # No constraints on u != v or uniqueness are stated; allow self-loops and duplicates.

    return True, "ok"


def validate_input(input_str: str) -> Tuple[bool, str]:
    ok, msg, parsed = parse_format(input_str)
    if not ok:
        return False, msg
    ok2, msg2 = check_constraints(parsed)
    if not ok2:
        return False, msg2
    return True, "ok"

