def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    if n <= 1:
        print("Exemplary pages.")
        return

    total = sum(a)
    if total % n != 0:
        print("Unrecoverable configuration.")
        return

    avg = total // n
    above = []
    below = []
    for i, x in enumerate(a):
        if x > avg:
            above.append((i, x - avg))  # index, surplus
        elif x < avg:
            below.append((i, avg - x))  # index, deficit

    if not above and not below:
