from typing import Tuple, Dict, Any

# Checks:
# - exact line/token structure: first line N, followed by exactly N lines each with one integer
# - numeric bounds: N in [1, 100]; each amount ai is a non-negative integer (ml)
# - array/string lengths: exactly N amounts
# - graph constraints: none
# - special constraints: integers only (no floats); no extra tokens/lines

def parse_format(input_str: str) -> Tuple[bool, Any]:
    if input_str is None:
        return False, "FORMAT_INVALID: input is None"
    s = input_str
    if len(s.strip()) == 0:
        return False, "FORMAT_INVALID: empty input"

    # Split into lines; allow trailing newline(s) but not extra content.
    lines = s.splitlines()
    if len(lines) == 0:
        return False, "FORMAT_INVALID: empty input"

    # Reject empty leading lines (format is strict in CF problems)
    if lines[0].strip() == "":
        return False, "FORMAT_INVALID: first line is empty"

    def parse_int_token(tok: str, ctx: str) -> Tuple[bool, Any]:
        if tok == "":
            return False, f"FORMAT_INVALID: missing integer token ({ctx})"
        # Disallow '+' sign; allow '-' syntactically (spec may reject later)
        if tok[0] == "+":
            return False, f"FORMAT_INVALID: invalid integer token with '+': {tok} ({ctx})"
        try:
            val = int(tok)
        except ValueError:
            return False, f"FORMAT_INVALID: non-integer token '{tok}' ({ctx})"
        return True, val

    # First line: exactly one token N
    t0 = lines[0].strip().split()
    if len(t0) != 1:
        return False, "FORMAT_INVALID: first line must contain exactly one integer N"
    ok, n = parse_int_token(t0[0], "N")
    if not ok:
        return False, n

    # Expect exactly N more lines (each with single integer)
    if len(lines) != 1 + n:
        return False, f"FORMAT_INVALID: expected {1+n} lines total (N+1), got {len(lines)}"

    a = []
    for i in range(n):
        line = lines[1 + i].strip()
        if line == "":
            return False, f"FORMAT_INVALID: line {2+i} is empty; expected an integer amount"
        toks = line.split()
        if len(toks) != 1:
            return False, f"FORMAT_INVALID: line {2+i} must contain exactly one integer amount"
        ok, val = parse_int_token(toks[0], f"a[{i}]")
        if not ok:
            return False, val
        a.append(val)

    return True, {"n": n, "a": a}


def check_constraints(parsed: Dict[str, Any]) -> Tuple[bool, str]:
    n = parsed["n"]
    a = parsed["a"]

    # From CF 99B constraints (typical): 1 <= n <= 100
    if not (1 <= n <= 100):
        return False, f"SPEC_INVALID: N out of bounds (1..100), got {n}"

    if len(a) != n:
        return False, "SPEC_INVALID: number of amounts does not match N"

    # Amounts are measured in milliliters and pour operations are integer.
    # The statement doesn't explicitly give upper bounds; enforce non-negative integers.
    for i, v in enumerate(a):
        if v < 0:
            return False, f"SPEC_INVALID: amount must be non-negative integer, got a[{i}]={v}"

    return True, "ok"


def validate_input(input_str: str) -> tuple[bool, str]:
    ok, res = parse_format(input_str)
    if not ok:
        # res is an error string already
        return False, res
    ok2, msg = check_constraints(res)
    if not ok2:
        return False, msg
    return True, "ok"

